        private static void CheckRuntimeSlotAllocatorAndProfileContracts()
        {
            var allocator = new RuntimeSlotAllocator(400, 20, 50);
            for (int slot = 0; slot <= 299; slot++)
            {
                Expect(allocator.ClaimRequired(slot),
                    $"runtime slot allocator must claim initial slot {slot}");
            }
            Expect(allocator.ClaimedCount == 300,
                "runtime slot allocator claimed count must track logical claims");

            int[] releaseOrder = { 299, 2, 4, 5, 1 };
            for (int i = 0; i < releaseOrder.Length; i++)
            {
                Expect(allocator.Release(releaseOrder[i]),
                    $"runtime slot allocator must release occupied slot {releaseOrder[i]}");
            }

            int[] expectedReuseOrder = { 1, 2, 4, 5, 299 };
            for (int i = 0; i < expectedReuseOrder.Length; i++)
            {
                int actual = allocator.AllocateLowest(0);
                Expect(actual == expectedReuseOrder[i],
                    $"runtime slot allocator lowest reuse mismatch: expected={expectedReuseOrder[i]}, actual={actual}");
            }

            allocator.Reset();
            Expect(allocator.AllocateLowest(50) == 50 && allocator.AllocateLowest(50) == 51,
                "dynamic runtime allocation must not consume roster or stage slots");
            Expect(!allocator.IsClaimed(0) && !allocator.IsClaimed(20),
                "dynamic runtime allocation must leave low slot bands untouched");

            allocator.Reset();
            Expect(allocator.ClaimRequired(20) && !allocator.ClaimRequired(20),
                "required runtime slot conflicts must be rejected");
            Expect(allocator.ClaimExisting(49, 20) && !allocator.ClaimExisting(19, 20),
                "existing runtime slots must respect their minimum allowed band");
            Expect(allocator.ClaimRequired(399) && allocator.Release(399) &&
                   allocator.PeekLowest(399, 400) == 399,
                "exact high runtime slot claims must return to the free set after release");

            allocator.Reset();
            int firstStagePeek = allocator.PeekLowest(20, 400);
            int secondStagePeek = allocator.PeekLowest(20, 400);
            Expect(firstStagePeek == 20 && secondStagePeek == 20 && !allocator.IsClaimed(20),
                "runtime slot peek must not claim the selected slot");
            Expect(allocator.AllocateLowest(20) == 20 && allocator.IsClaimed(20),
                "stage runtime allocation must claim the lowest stage-or-dynamic slot");
            allocator.Reset();
            Expect(allocator.PeekLowest(0, 400) == 0 &&
                   !allocator.IsClaimed(20) &&
                   allocator.ClaimedCount == 0,
                "runtime slot allocator reset must clear all segment state");

            var growingAllocator = new RuntimeSlotAllocator(512, 20, 50);
            for (int slot = 50; slot < 512; slot++)
            {
                Expect(growingAllocator.ClaimRequired(slot),
                    $"growing runtime slot allocator must claim initial dynamic slot {slot}");
            }
            Expect(growingAllocator.Release(299) && growingAllocator.Release(51) &&
                   growingAllocator.GrowTo(768) && growingAllocator.Capacity == 768 &&
                   growingAllocator.ClaimedCount == 460,
                "runtime slot allocator growth must preserve existing claims and released holes");
            Expect(growingAllocator.AllocateLowest(50) == 51 &&
                   growingAllocator.AllocateLowest(50) == 299 &&
                   growingAllocator.AllocateLowest(50) == 512,
                "runtime slot allocator growth must reuse old lower holes before newly addressable slots");
            Expect(growingAllocator.ClaimRequired(767) && growingAllocator.IsClaimed(767),
                "runtime slot allocator growth must permit an exact high required claim");
            int allocatorCountBeforeNoOp = growingAllocator.ClaimedCount;
            Expect(growingAllocator.GrowTo(768) &&
                   growingAllocator.Capacity == 768 &&
                   growingAllocator.ClaimedCount == allocatorCountBeforeNoOp,
                "runtime slot allocator same-capacity growth must be a successful no-op");
            Expect(!growingAllocator.GrowTo(767) &&
                   growingAllocator.Capacity == 768 &&
                   growingAllocator.ClaimedCount == allocatorCountBeforeNoOp,
                "runtime slot allocator shrink must be rejected without changing state");

            Expect(BattleRuntimeProfileResolver.Resolve(
                       "MobileExtended",
                       "DesktopExtended",
                       BattleRuntimeProfile.Authority400) == BattleRuntimeProfile.MobileExtended,
                "explicit runtime profile override must win over configured and platform defaults");
            Expect(BattleRuntimeProfileResolver.Resolve(
                       null,
                       "DesktopExtended",
                       BattleRuntimeProfile.Authority400) == BattleRuntimeProfile.DesktopExtended,
                "configured runtime profile must win over the platform default");
            Expect(BattleRuntimeProfileResolver.Resolve(
                       null,
                       null,
                       BattleRuntimeProfile.MobileExtended) == BattleRuntimeProfile.MobileExtended,
                "platform runtime profile must be used when no higher-priority value is valid");
            Expect(BattleRuntimeProfileResolver.Resolve(
                       "invalid",
                       "authority400",
                       BattleRuntimeProfile.DesktopExtended) == BattleRuntimeProfile.Authority400,
                "invalid runtime profile overrides must fall through to a valid configured profile");
            Expect(!BattleRuntimeProfileResolver.TryParse("1", out _),
                "runtime profile parser must not accept numeric enum values");

            BattleRuntimeWorldSettings explicitMobile = BattleRuntimeProfilePolicy.Resolve(
                "MobileExtended",
                "DesktopExtended",
                BattleRuntimeProfile.Authority400,
                513);
            BattleRuntimeWorldSettings configuredDesktop = BattleRuntimeProfilePolicy.Resolve(
                null,
                "DesktopExtended",
                BattleRuntimeProfile.Authority400,
                513);
            BattleRuntimeWorldSettings platformAuthority = BattleRuntimeProfilePolicy.Resolve(
                null,
                null,
                BattleRuntimeProfile.Authority400,
                1024);
            Expect(explicitMobile.Profile == BattleRuntimeProfile.MobileExtended &&
                   explicitMobile.InitialRuntimeSlotCapacity == 1050 &&
                   explicitMobile.MaxActiveRuntimeEntities == 1000,
                "runtime profile policy must map an explicit MobileExtended override to 1050 addresses and 1000 active entities");
            Expect(configuredDesktop.Profile == BattleRuntimeProfile.DesktopExtended &&
                   configuredDesktop.InitialRuntimeSlotCapacity == 768 &&
                   configuredDesktop.MaxActiveRuntimeEntities == int.MaxValue,
                "runtime profile policy must normalize configured DesktopExtended capacity to 256-slot pages");
            Expect(platformAuthority.Profile == BattleRuntimeProfile.Authority400 &&
                   platformAuthority.InitialRuntimeSlotCapacity == 400,
                "runtime profile policy must keep the Editor/authority fallback pinned to 400 slots");
            Expect(BattleRuntimeProfileProductionSource.FindArgumentValue(
                       new[] { "player", "-ntsdBattleRuntimeProfile", "DesktopExtended" },
                       BattleRuntimeProfileProductionSource.ProfileArgument) == "DesktopExtended" &&
                   BattleRuntimeProfileProductionSource.FindArgumentValue(
                       new[] { "player", "-ntsdDesktopRuntimeSlotCapacity=769" },
                       BattleRuntimeProfileProductionSource.DesktopCapacityArgument) == "769",
                "runtime profile production source must accept separate and assignment command-line overrides");

            var world = new SimulationWorld();
            Expect(world.RuntimeProfileForServices == BattleRuntimeProfile.Authority400 &&
                   world.MaxRuntimeSlotsForServices == 400,
                "first runtime slot migration batch must remain explicitly pinned to Authority400");
        }

        private static void CheckPagedRuntimeSlotTableContracts()
        {
            var authorityTable = new RuntimeSlotTable(400, 20, 50);
            Expect(authorityTable.LogicalCapacity == 400 &&
                   authorityTable.MaterializedPageCount == 0 &&
                   authorityTable.ClaimedCount == 0,
                "runtime slot table must start empty without materializing pages");

            var entity255 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var entity256 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var entity399 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            Expect(authorityTable.TryClaim(255, entity255, out RuntimeEntityHandle handle255) &&
                   authorityTable.MaterializedPageCount == 1,
                "runtime slot table must materialize the first page at slot 255");
            Expect(authorityTable.TryClaim(256, entity256, out RuntimeEntityHandle handle256) &&
                   authorityTable.MaterializedPageCount == 2,
                "runtime slot table must materialize a second page at slot 256");
            Expect(authorityTable.TryClaim(399, entity399, out RuntimeEntityHandle handle399) &&
                   authorityTable.ClaimedCount == 3,
                "runtime slot table must claim the final Authority400 slot");
            Expect(authorityTable.PeekLowest(255, 400) == 257 &&
                   !authorityTable.IsClaimed(257),
                "runtime slot table peek must expose the lowest free slot without claiming it");
            Expect(!authorityTable.TryClaim(400, new FlowSelfCheckEntity(LF2ObjectType.Character), out _) &&
                   !authorityTable.IsAddressable(400) &&
                   authorityTable.GetRawRuntime(400) == null &&
                   authorityTable.MaterializedPageCount == 2,
                "runtime slot table must keep the Authority400 tail unavailable");
            Expect(authorityTable.TryResolve(handle255, out LF2Entity resolved255) &&
                   ReferenceEquals(resolved255, entity255) &&
                   authorityTable.TryGetCurrentHandle(255, entity255, out RuntimeEntityHandle currentHandle255) &&
                   currentHandle255 == handle255 &&
                   !authorityTable.TryGetCurrentHandle(255, entity256, out _) &&
                   authorityTable.TryGetCurrentOccupant(255, out LF2Entity current255) &&
                   ReferenceEquals(current255, entity255) &&
                   authorityTable.TryResolve(handle256, out LF2Entity resolved256) &&
                   ReferenceEquals(resolved256, entity256) &&
                   authorityTable.TryResolve(handle399, out LF2Entity resolved399) &&
                   ReferenceEquals(resolved399, entity399),
                "runtime entity handles must resolve only their current claimed occupants");
            Expect(authorityTable.GetRawRuntime(255) != null &&
                   !ReferenceEquals(authorityTable.GetRawRuntime(255), entity255.Runtime),
                "runtime slot entries must own independent raw runtime storage");

            Expect(!authorityTable.Release(255, entity256) &&
                   ReferenceEquals(authorityTable.GetCurrentOccupant(255), entity255) &&
                   authorityTable.ClaimedCount == 3,
                "runtime slot table must reject a stale lifecycle release for a different occupant");
            Expect(authorityTable.Release(handle255) &&
                   authorityTable.ClaimedCount == 2 &&
                   !authorityTable.TryResolve(handle255, out _),
                "released runtime entity handles must stop resolving");

            var replacement255 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            Expect(authorityTable.AllocateLowest(255, replacement255, out RuntimeEntityHandle replacementHandle) == 255 &&
                   replacementHandle != handle255 &&
                   authorityTable.TryGetCurrentHandle(255, replacement255, out RuntimeEntityHandle currentReplacementHandle) &&
                   currentReplacementHandle == replacementHandle &&
                   !authorityTable.TryGetCurrentHandle(255, entity255, out _) &&
                   authorityTable.TryResolve(replacementHandle, out LF2Entity replacementResolved) &&
                   ReferenceEquals(replacementResolved, replacement255) &&
                   !authorityTable.TryResolve(handle255, out _) &&
                   !authorityTable.Release(255, entity255) &&
                   ReferenceEquals(authorityTable.GetCurrentOccupant(255), replacement255),
                "same-slot reuse must issue a new generation and keep the old handle invalid");

            authorityTable.Reset();
            Expect(authorityTable.ClaimedCount == 0 &&
                   authorityTable.MaterializedPageCount == 2 &&
                   !authorityTable.TryResolve(replacementHandle, out _),
                "runtime slot table reset must clear claims without losing lazy pages");
            var afterReset255 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            Expect(authorityTable.TryClaim(255, afterReset255, out RuntimeEntityHandle afterResetHandle) &&
                   afterResetHandle != replacementHandle &&
                   !authorityTable.TryResolve(replacementHandle, out _),
                "runtime slot table reset must prevent old handles from becoming valid again");

            var growingTable = new RuntimeSlotTable(512, 20, 50);
            var growingEntity255 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var growingEntity511 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            bool claimedGrowing255 = growingTable.TryClaim(
                255,
                growingEntity255,
                out RuntimeEntityHandle growingHandle255);
            bool claimedGrowing511 = growingTable.TryClaim(
                511,
                growingEntity511,
                out RuntimeEntityHandle growingHandle511);
            Expect(claimedGrowing255 && claimedGrowing511,
                "runtime slot table growth fixture must claim occupants on both existing pages");
            RuntimeEntityHandle growingHoleHandle51 = RuntimeEntityHandle.Invalid;
            RuntimeEntityHandle growingHoleHandle299 = RuntimeEntityHandle.Invalid;
            for (int slot = 50; slot < 512; slot++)
            {
                if (slot == 255 || slot == 511)
                    continue;

                Expect(growingTable.TryClaim(
                           slot,
                           new FlowSelfCheckEntity(LF2ObjectType.Character),
                           out RuntimeEntityHandle claimedHandle),
                    $"runtime slot table growth fixture must claim initial dynamic slot {slot}");
                if (slot == 51)
                    growingHoleHandle51 = claimedHandle;
                else if (slot == 299)
                    growingHoleHandle299 = claimedHandle;
            }
            Expect(growingTable.Release(growingHoleHandle299) &&
                   growingTable.Release(growingHoleHandle51) &&
                   growingTable.ClaimedCount == 460,
                "runtime slot table growth fixture must retain released low-slot holes");
            NTSDEntityRuntime growingRawRuntime255 = growingTable.GetRawRuntime(255);
            NTSDEntityRuntime growingRawRuntime511 = growingTable.GetRawRuntime(511);
            Expect(growingTable.MaterializedPageCount == 2,
                "runtime slot table growth fixture must materialize only its original pages");
            Expect(growingTable.GrowTo(768) &&
                   growingTable.LogicalCapacity == 768 &&
                   growingTable.MaterializedPageCount == 2 &&
                   growingTable.TryResolve(growingHandle255, out LF2Entity grownResolved255) &&
                   ReferenceEquals(grownResolved255, growingEntity255) &&
                   growingTable.TryResolve(growingHandle511, out LF2Entity grownResolved511) &&
                   ReferenceEquals(grownResolved511, growingEntity511) &&
                   ReferenceEquals(growingTable.GetRawRuntime(255), growingRawRuntime255) &&
                   ReferenceEquals(growingTable.GetRawRuntime(511), growingRawRuntime511),
                "runtime slot table growth must preserve occupants, handles, raw runtime, and page objects");
            var grownHoleEntity51 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var grownHoleEntity299 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var grownNewEntity512 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            Expect(growingTable.AllocateLowest(50, grownHoleEntity51, out RuntimeEntityHandle grownHandle51) == 51 &&
                   growingTable.AllocateLowest(50, grownHoleEntity299, out RuntimeEntityHandle grownHandle299) == 299 &&
                   growingTable.AllocateLowest(50, grownNewEntity512, out RuntimeEntityHandle grownHandle512) == 512 &&
                   growingTable.TryResolve(grownHandle51, out LF2Entity grownResolved51) &&
                   ReferenceEquals(grownResolved51, grownHoleEntity51) &&
                   growingTable.TryResolve(grownHandle299, out LF2Entity grownResolved299) &&
                   ReferenceEquals(grownResolved299, grownHoleEntity299) &&
                   growingTable.TryResolve(grownHandle512, out LF2Entity grownResolved512) &&
                   ReferenceEquals(grownResolved512, grownNewEntity512) &&
                   growingTable.MaterializedPageCount == 3,
                "runtime slot table growth must reuse old lower holes before lazily materializing a new-slot page");
            var growingEntity767 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            Expect(growingTable.TryClaim(767, growingEntity767, out RuntimeEntityHandle growingHandle767) &&
                   growingTable.MaterializedPageCount == 3 &&
                   growingTable.TryResolve(growingHandle767, out LF2Entity grownResolved767) &&
                   ReferenceEquals(grownResolved767, growingEntity767),
                "runtime slot table growth must materialize a new page only when a grown slot is accessed");
            int tableClaimedBeforeNoOp = growingTable.ClaimedCount;
            Expect(growingTable.GrowTo(768) &&
                   growingTable.LogicalCapacity == 768 &&
                   growingTable.MaterializedPageCount == 3 &&
                   growingTable.ClaimedCount == tableClaimedBeforeNoOp,
                "runtime slot table same-capacity growth must be a successful no-op");
            Expect(!growingTable.GrowTo(767) &&
                   growingTable.LogicalCapacity == 768 &&
                   growingTable.MaterializedPageCount == 3 &&
                   growingTable.ClaimedCount == tableClaimedBeforeNoOp &&
                   growingTable.TryResolve(growingHandle767, out _),
                "runtime slot table shrink must be rejected without changing existing state");

            var mobileTable = new RuntimeSlotTable(1050, 20, 50);
            var entity1049 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            Expect(mobileTable.TryClaim(1049, entity1049, out RuntimeEntityHandle handle1049) &&
                   mobileTable.MaterializedPageCount == 1 &&
                   mobileTable.TryResolve(handle1049, out LF2Entity resolved1049) &&
                   ReferenceEquals(resolved1049, entity1049),
                "runtime slot table must lazily claim the final MobileExtended dynamic slot");
            Expect(!mobileTable.TryClaim(1050, new FlowSelfCheckEntity(LF2ObjectType.Character), out _) &&
                   !mobileTable.IsAddressable(1050) &&
                   !mobileTable.IsAddressable(1279) &&
                   mobileTable.GetRawRuntime(1050) == null &&
                   mobileTable.GetRawRuntime(1279) == null &&
                   mobileTable.MaterializedPageCount == 1,
                "runtime slot table must expose exactly 1000 MobileExtended dynamic slots and guard its physical tail");

            var world = new SimulationWorld();
            var worldEntity255 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var worldEntity256 = new FlowSelfCheckEntity(LF2ObjectType.Character);
            worldEntity255.SetRequiredRuntimeSlot(255);
            worldEntity256.SetRequiredRuntimeSlot(256);
            world.Register(worldEntity255);
            world.Register(worldEntity256);
            Expect(ReferenceEquals(world.FindEntityByRuntimeSlotIncludingPending(255), worldEntity255) &&
                   ReferenceEquals(world.FindEntityByRuntimeSlotForQuery(256), worldEntity256),
                "production runtime registry must resolve current occupants across page boundaries");
            world.ResetRuntimeState();
            Expect(world.FindEntityByRuntimeSlotIncludingPending(255) == null &&
                   world.FindEntityByRuntimeSlotForQuery(256) == null &&
                   world.ObjectCount == 0,
                "production runtime registry reset must clear cross-page occupant lookups");
        }

        private static void CheckRuntimeRestStoreContracts()
        {
            var store = new RuntimeRestStore(400);
            Expect(store.LogicalCapacity == 400 &&
                   store.MaterializedARestPageCount == 0 &&
                   store.MaterializedVRestPageCount == 0,
                "runtime rest storage must begin empty without materializing dense pages");

            Expect(store.SetARest(20, 7) && store.GetARest(20) == 7 &&
                   store.SetVRest(10, 20, 9) && store.GetVRest(10, 20) == 9 &&
                   store.GetVRest(20, 10) == 0,
                "runtime rest storage must keep ARest separate and VRest directional by victim/attacker slot");
            Expect(store.SetVRest(399, 0, 11) && store.GetVRest(399, 0) == 11 &&
                   store.SetVRest(33, 33, 13) && store.GetVRest(33, 33) == 13,
                "runtime rest storage must retain far pairs independent of space and support self-rest pairs");

            int entriesBeforeZeroRemoval = store.VRestEntryCount;
            Expect(store.SetVRest(10, 20, 0) && store.GetVRest(10, 20) == 0 &&
                   store.VRestEntryCount == entriesBeforeZeroRemoval - 1,
                "runtime rest storage must remove zero VRest values instead of retaining sparse entries");

            store.SetARest(12, 5);
            store.SetVRest(12, 33, 17);
            store.SetVRest(12, 44, 19);
            store.SetVRest(33, 12, 21);
            store.SetVRest(44, 12, 23);
            store.SetVRest(33, 44, 25);
            Expect(store.ResetSlot(12) && store.GetARest(12) == 0 &&
                   store.GetVRest(12, 33) == 0 && store.GetVRest(12, 44) == 0 &&
                   store.GetVRest(33, 12) == 0 && store.GetVRest(44, 12) == 0 &&
                   store.GetVRest(33, 44) == 25,
                "resetting one runtime slot must clear its ARest, victim row, and every peer attacker column only");

            var growing = new RuntimeRestStore(511);
            growing.SetARest(510, 3);
            growing.SetVRest(510, 1, 5);
            RuntimeRestStore.DiagnosticSnapshot beforeGrow = growing.CaptureDiagnosticSnapshot();
            Expect(growing.GrowTo(700) && growing.LogicalCapacity == 700 &&
                   growing.GetARest(510) == 3 && growing.GetVRest(510, 1) == 5 &&
                   growing.SetARest(699, 7) && growing.SetVRest(699, 699, 9),
                "runtime rest storage growth from 511 to 700 must preserve old values and address the new logical tail");
            Expect(!growing.GrowTo(699) && !growing.SetARest(700, 1) &&
                   !growing.SetVRest(699, 700, 1) && !growing.SetVRest(700, 699, 1) &&
                   growing.GetARest(700) == 0 && growing.GetVRest(699, 700) == 0,
                "runtime rest storage must reject shrink and guard the physical page tail beyond logical capacity");

            RuntimeRestStore.DiagnosticSnapshot grownSnapshot = growing.CaptureDiagnosticSnapshot();
            Expect(grownSnapshot.ARestEntries.Count == 2 &&
                   grownSnapshot.ARestEntries[0].AttackerSlot == 510 &&
                   grownSnapshot.ARestEntries[1].AttackerSlot == 699 &&
                   grownSnapshot.VRestEntries.Count == 2 &&
                   grownSnapshot.VRestEntries[0].VictimSlot == 510 &&
                   grownSnapshot.VRestEntries[1].VictimSlot == 699,
                "runtime rest diagnostic snapshots must project entries in deterministic slot order");

            growing.ResetWorld();
            Expect(growing.ARestEntryCount == 0 && growing.VRestEntryCount == 0 &&
                   growing.VRestRowCount == 0 && growing.MaterializedARestPageCount == 0 &&
                   growing.MaterializedVRestPageCount == 0 && growing.GetARest(510) == 0 &&
                   growing.GetVRest(510, 1) == 0,
                "runtime rest world reset must clear all values, sparse rows, and materialized pages");
            Expect(growing.RestoreDiagnosticSnapshot(beforeGrow) && growing.LogicalCapacity == 700 &&
                   growing.GetARest(510) == 3 && growing.GetVRest(510, 1) == 5 &&
                   growing.GetARest(699) == 0 && growing.GetVRest(699, 699) == 0,
                "runtime rest diagnostic restore must recover captured values without shrinking an already-grown store");

            const int differentialCapacity = 32;
            var differential = new RuntimeRestStore(differentialCapacity);
            var expectedARest = new int[differentialCapacity];
            var expectedVRest = new int[differentialCapacity, differentialCapacity];
            var random = new System.Random(0x525354);
            for (int operationIndex = 0; operationIndex < 2000; operationIndex++)
            {
                int operation = random.Next(4);
                int first = random.Next(differentialCapacity);
                int second = random.Next(differentialCapacity);
                int value = random.Next(-2, 16);
                int storedValue = Math.Max(0, value);

                if (operation == 0)
                {
                    differential.SetARest(first, value);
                    expectedARest[first] = storedValue;
                }
                else if (operation == 1)
                {
                    differential.SetVRest(first, second, value);
                    expectedVRest[first, second] = storedValue;
                }
                else if (operation == 2)
                {
                    differential.ResetSlot(first);
                    expectedARest[first] = 0;
                    for (int slot = 0; slot < differentialCapacity; slot++)
                    {
                        expectedVRest[first, slot] = 0;
                        expectedVRest[slot, first] = 0;
                    }
                }
                else
                {
                    differential.ResetWorld();
                    Array.Clear(expectedARest, 0, expectedARest.Length);
                    Array.Clear(expectedVRest, 0, expectedVRest.Length);
                }

                int expectedARestCount = 0;
                int expectedVRestCount = 0;
                int expectedVRestRowCount = 0;
                for (int victimSlot = 0; victimSlot < differentialCapacity; victimSlot++)
                {
                    Expect(differential.GetARest(victimSlot) == expectedARest[victimSlot],
                        $"runtime rest differential ARest mismatch after operation {operationIndex}, slot {victimSlot}");
                    if (expectedARest[victimSlot] > 0)
                        expectedARestCount++;

                    bool hasVRestRow = false;
                    for (int attackerSlot = 0; attackerSlot < differentialCapacity; attackerSlot++)
                    {
                        Expect(differential.GetVRest(victimSlot, attackerSlot) ==
                               expectedVRest[victimSlot, attackerSlot],
                            $"runtime rest differential VRest mismatch after operation {operationIndex}, pair {victimSlot}/{attackerSlot}");
                        if (expectedVRest[victimSlot, attackerSlot] > 0)
                        {
                            expectedVRestCount++;
                            hasVRestRow = true;
                        }
                    }

                    if (hasVRestRow)
                        expectedVRestRowCount++;
                }

                Expect(differential.ARestEntryCount == expectedARestCount &&
                       differential.VRestEntryCount == expectedVRestCount &&
                       differential.VRestRowCount == expectedVRestRowCount,
                    $"runtime rest diagnostic counts mismatch after operation {operationIndex}");
            }

            const int pairTickCapacity = 24;
            var pairTickStore = new RuntimeRestStore(pairTickCapacity);
            var pairTickExpected = new int[pairTickCapacity, pairTickCapacity];
            var pairTickEligible = new bool[pairTickCapacity];
            var pairTickEligibleSlots = new List<int>(pairTickCapacity);
            var pairTickRandom = new System.Random(0x50414952);
            for (int victimSlot = 0; victimSlot < pairTickCapacity; victimSlot++)
            {
                for (int attackerSlot = 0; attackerSlot < pairTickCapacity; attackerSlot++)
                {
                    int value = pairTickRandom.Next(0, 5);
                    pairTickExpected[victimSlot, attackerSlot] = value;
                    pairTickStore.SetVRest(victimSlot, attackerSlot, value);
                }
            }

            for (int tick = 0; tick < 32; tick++)
            {
                pairTickEligibleSlots.Clear();
                for (int slot = 0; slot < pairTickCapacity; slot++)
                {
                    pairTickEligible[slot] = pairTickRandom.Next(0, 2) != 0;
                    if (pairTickEligible[slot])
                        pairTickEligibleSlots.Add(slot);
                }

                Expect(pairTickStore.TickCollisionPairVRest(pairTickEligibleSlots),
                    $"collision pair VRest differential tick {tick} must accept its eligible slot view");
                int expectedEntries = 0;
                int expectedRows = 0;
                for (int victimSlot = 0; victimSlot < pairTickCapacity; victimSlot++)
                {
                    bool rowHasEntry = false;
                    for (int attackerSlot = 0; attackerSlot < pairTickCapacity; attackerSlot++)
                    {
                        if (victimSlot != attackerSlot && pairTickEligible[victimSlot] &&
                            pairTickEligible[attackerSlot] &&
                            pairTickExpected[victimSlot, attackerSlot] > 0)
                        {
                            pairTickExpected[victimSlot, attackerSlot]--;
                        }

                        int expectedValue = pairTickExpected[victimSlot, attackerSlot];
                        Expect(pairTickStore.GetVRest(victimSlot, attackerSlot) == expectedValue,
                            $"collision pair VRest differential mismatch at tick {tick}, pair {victimSlot}/{attackerSlot}");
                        if (expectedValue > 0)
                        {
                            expectedEntries++;
                            rowHasEntry = true;
                        }
                    }

                    if (rowHasEntry)
                        expectedRows++;
                }

                Expect(pairTickStore.VRestEntryCount == expectedEntries &&
                       pairTickStore.VRestRowCount == expectedRows,
                    $"collision pair VRest sparse counters mismatch after differential tick {tick}");
            }

            Expect(pairTickStore.GrowTo(300) && pairTickStore.SetVRest(299, 1, 2) &&
                   pairTickStore.TickCollisionPairVRest(new[] { 1, 299 }) &&
                   pairTickStore.GetVRest(299, 1) == 1,
                "collision pair VRest eligibility stamps must grow with the store and address the extended tail");
        }

        private static void CheckItrRestTrackerBindingContracts()
        {
            var local = new LF2ItrRestTracker
            {
                Arest = 2,
            };
            local.SetVrest(3, 2);
            local.Tick();
            Expect(!local.IsBound && local.BoundVictimSlot == -1 && local.Arest == 1 &&
                   local.GetVrest(3) == 1 && local.HasVrest(3) && !local.VrestTest(3),
                "unbound LF2ItrRestTracker behavior must remain local and compatible");
            local.Tick();
            Expect(local.Arest == 0 && local.GetVrest(3) == 0 && !local.HasVrest(3) &&
                   local.VrestTest(3),
                "local tracker tick must remove VRest entries when they reach zero");

            var importStore = new RuntimeRestStore(32);
            importStore.SetARest(5, 19);
            importStore.SetVRest(5, 9, 17);
            importStore.SetVRest(7, 5, 13);
            var importing = new LF2ItrRestTracker
            {
                Arest = 4,
            };
            importing.SetVrest(2, 6);
            Expect(importing.Bind(importStore, 5, true) && importing.IsBound &&
                   importing.BoundVictimSlot == 5 && importStore.GetARest(5) == 4 &&
                   importStore.GetVRest(5, 2) == 6 && importStore.GetVRest(5, 9) == 0 &&
                   importStore.GetVRest(7, 5) == 13,
                "Bind(importLocal:true) must replace only the bound ARest/victim row and preserve peer columns");
            Expect(importing.Bind(importStore, 5, false),
                "binding the same tracker to the same store/slot must be an idempotent success");

            var excluded = new LF2ItrRestTracker();
            Expect(!excluded.Bind(importStore, 5, false) &&
                   !importing.Bind(importStore, 6, false),
                "runtime rest bindings must be exclusive per victim slot and one slot per tracker");

            importing.Reset();
            Expect(importStore.GetARest(5) == 0 && importStore.GetVRest(5, 2) == 0 &&
                   importStore.GetVRest(7, 5) == 13 && importing.Unbind(false) &&
                   importing.Arest == 4 && importing.GetVrest(2) == 6,
                "bound Reset must clear only the store owner state while Unbind(false) restores the pre-bind local fallback");

            var storeFirst = new RuntimeRestStore(32);
            storeFirst.SetARest(8, 11);
            storeFirst.SetVRest(8, 2, 12);
            var storeFirstTracker = new LF2ItrRestTracker
            {
                Arest = 3,
            };
            storeFirstTracker.SetVrest(4, 5);
            Expect(storeFirstTracker.Bind(storeFirst, 8, false) &&
                   storeFirstTracker.Arest == 11 && storeFirstTracker.GetVrest(2) == 12 &&
                   storeFirstTracker.GetVrest(4) == 0,
                "Bind(importLocal:false) must expose existing store state without importing local fallback");
            storeFirstTracker.Arest = 7;
            storeFirstTracker.SetVrest(2, 6);
            Expect(storeFirstTracker.Unbind(true) && !storeFirstTracker.IsBound &&
                   storeFirstTracker.Arest == 7 && storeFirstTracker.GetVrest(2) == 6 &&
                   storeFirstTracker.GetVrest(4) == 0,
                "Unbind(true) must capture the current store owner state into local fallback");

            var preserveLocalStore = new RuntimeRestStore(32);
            preserveLocalStore.SetARest(9, 15);
            preserveLocalStore.SetVRest(9, 1, 14);
            var preserveLocal = new LF2ItrRestTracker
            {
                Arest = 5,
            };
            preserveLocal.SetVrest(3, 4);
            Expect(preserveLocal.Bind(preserveLocalStore, 9, false),
                "store-first tracker setup must bind successfully");
            preserveLocal.Arest = 8;
            preserveLocal.SetVrest(1, 7);
            Expect(preserveLocal.Unbind(false) && preserveLocal.Arest == 5 &&
                   preserveLocal.GetVrest(3) == 4 && preserveLocal.GetVrest(1) == 0,
                "Unbind(false) must retain pre-bind local fallback instead of capturing store writes");

            var leaseStore = new RuntimeRestStore(16);
            Expect(leaseStore.TryAcquireBinding(3, out RuntimeRestBindingHandle firstLease) &&
                   leaseStore.IsBindingValid(firstLease) &&
                   !leaseStore.TryAcquireBinding(3, out _),
                "runtime rest store must issue one exclusive token lease per victim slot");
            RuntimeRestBindingHandle secondLease = default;
            Expect(leaseStore.ReleaseBinding(firstLease) &&
                   !leaseStore.IsBindingValid(firstLease) &&
                   leaseStore.TryAcquireBinding(3, out secondLease) &&
                   leaseStore.IsBindingValid(secondLease) && firstLease.Token != secondLease.Token,
                "released slots must be reusable with a new token that rejects stale handles");
            leaseStore.ReleaseBinding(secondLease);

            var resetStore = new RuntimeRestStore(16);
            var resetTracker = new LF2ItrRestTracker
            {
                Arest = 2,
            };
            resetTracker.SetVrest(4, 3);
            resetStore.SetARest(6, 9);
            resetStore.SetVRest(6, 4, 8);
            Expect(resetTracker.Bind(resetStore, 6, false) && resetStore.ResetSlot(6) &&
                   !resetTracker.IsBound && resetTracker.BoundVictimSlot == -1 &&
                   resetTracker.Arest == 2 && resetTracker.GetVrest(4) == 3 &&
                   resetStore.GetARest(6) == 0 && resetStore.GetVRest(6, 4) == 0,
                "ResetSlot must invalidate the lease without overwriting the tracker's pre-bind local fallback");

            var worldResetTracker = new LF2ItrRestTracker
            {
                Arest = 3,
            };
            resetStore.SetARest(7, 10);
            Expect(worldResetTracker.Bind(resetStore, 7, false),
                "world-reset lease fixture must bind successfully");
            resetStore.ResetWorld();
            Expect(!worldResetTracker.IsBound && worldResetTracker.Arest == 3 &&
                   resetStore.GetARest(7) == 0,
                "ResetWorld must invalidate every lease without leaking cleared store state into local fallback");

            resetStore.SetARest(8, 12);
            var restoreTracker = new LF2ItrRestTracker
            {
                Arest = 4,
            };
            Expect(restoreTracker.Bind(resetStore, 8, false),
                "diagnostic-restore lease fixture must bind successfully");
            RuntimeRestStore.DiagnosticSnapshot restoredSnapshot = resetStore.CaptureDiagnosticSnapshot();
            resetStore.SetARest(8, 5);
            Expect(resetStore.RestoreDiagnosticSnapshot(restoredSnapshot) &&
                   !restoreTracker.IsBound && restoreTracker.Arest == 4 &&
                   resetStore.GetARest(8) == 12,
                "diagnostic restore must invalidate old leases while restoring captured store values");

            var growingStore = new RuntimeRestStore(16);
            var growingTracker = new LF2ItrRestTracker();
            growingStore.SetARest(15, 6);
            Expect(growingTracker.Bind(growingStore, 15, false) && growingStore.GrowTo(300) &&
                   growingTracker.IsBound && growingTracker.BoundVictimSlot == 15 &&
                   growingTracker.Arest == 6,
                "GrowTo must preserve active binding tokens and bound state");
            growingTracker.Unbind(false);

            var snapshotSource = new LF2ItrRestTracker
            {
                Arest = 6,
            };
            snapshotSource.SetVrest(1, 8);
            snapshotSource.SetVrest(4, 10);
            LF2ItrRestTracker.StateSnapshot ownerSnapshot = snapshotSource.CaptureState();
            var restoreStore = new RuntimeRestStore(16);
            restoreStore.SetVRest(10, 5, 13);
            restoreStore.SetVRest(5, 2, 9);
            var boundRestore = new LF2ItrRestTracker
            {
                Arest = 2,
            };
            boundRestore.SetVrest(3, 3);
            Expect(boundRestore.Bind(restoreStore, 5, false),
                "bound restore fixture must bind successfully");
            boundRestore.RestoreState(ownerSnapshot);
            LF2ItrRestTracker.StateSnapshot capturedBound = boundRestore.CaptureState();
            Expect(boundRestore.Arest == 6 && boundRestore.GetVrest(1) == 8 &&
                   boundRestore.GetVrest(4) == 10 && boundRestore.GetVrest(2) == 0 &&
                   restoreStore.GetVRest(10, 5) == 13 && capturedBound.Arest == 6 &&
                   capturedBound.VrestByAttacker.Count == 2,
                "bound Capture/Restore must replace only the owner row and preserve peer columns");
            Expect(boundRestore.Unbind(false) && boundRestore.Arest == 2 &&
                   boundRestore.GetVrest(3) == 3,
                "bound RestoreState must not mutate the pre-bind local fallback");

            var tickStore = new RuntimeRestStore(16);
            var boundTick = new LF2ItrRestTracker();
            var localTick = new LF2ItrRestTracker();
            boundTick.Arest = 2;
            boundTick.SetVrest(3, 2);
            localTick.Arest = 2;
            localTick.SetVrest(3, 2);
            Expect(boundTick.Bind(tickStore, 5, true),
                "bound tick fixture must import local state");
            boundTick.Tick();
            localTick.Tick();
            Expect(boundTick.Arest == localTick.Arest &&
                   boundTick.GetVrest(3) == localTick.GetVrest(3) &&
                   tickStore.ARestEntryCount == 1 && tickStore.VRestEntryCount == 1,
                "bound and local tracker ticks must produce equivalent positive cooldown state");
            boundTick.Tick();
            localTick.Tick();
            Expect(boundTick.Arest == 0 && boundTick.GetVrest(3) == 0 &&
                   localTick.Arest == 0 && localTick.GetVrest(3) == 0 &&
                   tickStore.ARestEntryCount == 0 && tickStore.VRestEntryCount == 0 &&
                   tickStore.VRestRowCount == 0,
                "bound/local tick-to-zero must remove sparse entries and retain exact counters");
            boundTick.Unbind(false);

            var invalid = new LF2ItrRestTracker();
            Expect(!invalid.Bind(null, 0, false) && !invalid.Bind(new RuntimeRestStore(8), -1, false) &&
                   !invalid.Bind(new RuntimeRestStore(8), 8, false) && !invalid.IsBound,
                "tracker binding must reject null stores and non-addressable victim slots");

            var atomicStore = new RuntimeRestStore(16);
            atomicStore.SetARest(5, 7);
            atomicStore.SetVRest(5, 2, 8);
            atomicStore.SetVRest(5, 3, 9);
            atomicStore.SetVRest(10, 5, 11);
            int atomicARestCount = atomicStore.ARestEntryCount;
            int atomicVRestCount = atomicStore.VRestEntryCount;
            int atomicRowCount = atomicStore.VRestRowCount;
            var invalidMixedState = new Dictionary<int, int>
            {
                [1] = 4,
                [16] = 6,
            };
            Expect(!atomicStore.ReplaceVictimState(5, 12, invalidMixedState) &&
                   atomicStore.GetARest(5) == 7 && atomicStore.GetVRest(5, 2) == 8 &&
                   atomicStore.GetVRest(5, 3) == 9 && atomicStore.GetVRest(5, 1) == 0 &&
                   atomicStore.GetVRest(10, 5) == 11 &&
                   atomicStore.ARestEntryCount == atomicARestCount &&
                   atomicStore.VRestEntryCount == atomicVRestCount &&
                   atomicStore.VRestRowCount == atomicRowCount,
                "ReplaceVictimState must validate every positive attacker slot before atomically replacing existing state");

            var failedImport = new LF2ItrRestTracker
            {
                Arest = 4,
            };
            failedImport.SetVrest(1, 5);
            failedImport.SetVrest(16, 6);
            Expect(!failedImport.Bind(atomicStore, 5, true) && !failedImport.IsBound &&
                   failedImport.Arest == 4 && failedImport.GetVrest(1) == 5 &&
                   failedImport.GetVrest(16) == 6 && atomicStore.GetARest(5) == 7 &&
                   atomicStore.GetVRest(5, 2) == 8 && atomicStore.GetVRest(5, 3) == 9 &&
                   atomicStore.ARestEntryCount == atomicARestCount &&
                   atomicStore.VRestEntryCount == atomicVRestCount &&
                   atomicStore.VRestRowCount == atomicRowCount,
                "failed Bind(importLocal:true) must preserve store/local state and detach its rejected lease");
            var leaseAfterFailedImport = new LF2ItrRestTracker();
            Expect(leaseAfterFailedImport.Bind(atomicStore, 5, false) &&
                   leaseAfterFailedImport.Arest == 7 && leaseAfterFailedImport.GetVrest(2) == 8,
                "a failed importing bind must release its token so the victim slot remains bindable");
            leaseAfterFailedImport.Unbind(false);

            string scriptsRoot = Path.Combine(Application.dataPath, "NTSD", "Scripts");
            string[] productionScripts = Directory.GetFiles(scriptsRoot, "*.cs", SearchOption.AllDirectories);
            int productionBindCallCount = 0;
            for (int i = 0; i < productionScripts.Length; i++)
            {
                string path = productionScripts[i].Replace('\\', '/');
                if (path.Contains("/Test/", StringComparison.Ordinal) ||
                    path.EndsWith("/LF2ItrRestTracker.cs", StringComparison.Ordinal))
                {
                    continue;
                }

                string source = File.ReadAllText(productionScripts[i]);
                System.Text.RegularExpressions.MatchCollection bindCalls =
                    System.Text.RegularExpressions.Regex.Matches(
                        source,
                        @"ItrRest(?:\?)?\.Bind\s*\([^)]*\)",
                        System.Text.RegularExpressions.RegexOptions.Singleline);
                for (int callIndex = 0; callIndex < bindCalls.Count; callIndex++)
                {
                    productionBindCallCount++;
                    string call = bindCalls[callIndex].Value;
                    bool allowedOwner = path.EndsWith(
                                            "/SimulationWorld.Registry.partial.cs",
                                            StringComparison.Ordinal) ||
                                        path.EndsWith(
                                            "/SimulationWorld.QueryAndLinks.partial.cs",
                                            StringComparison.Ordinal);
                    Expect(allowedOwner && call.Contains("_runtimeRestStore", StringComparison.Ordinal) &&
                           System.Text.RegularExpressions.Regex.IsMatch(call, @",\s*false\s*\)$"),
                        $"B1.2 production Bind must be store-first and owned by the SimulationWorld lifecycle: {path}: {call}");
                }
            }
            Expect(productionBindCallCount == 3,
                "B1.2 production binding must remain limited to ordinary reset/rebind, release rollback, and StageSpawnAt restore");
        }

        private static void CheckProductionRuntimeRestStoreLifecycleContracts()
        {
            var world = new SimulationWorld();
            var character = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var weapon = new FlowSelfCheckEntity(LF2ObjectType.LightWeapon);
            var special = new FlowSelfCheckEntity(LF2ObjectType.SpecialAttack);
            var other = new FlowSelfCheckEntity(LF2ObjectType.Other);
            character.SetRequiredRuntimeSlot(0);
            weapon.SetRequiredRuntimeSlot(50);
            special.SetRequiredRuntimeSlot(51);
            other.SetRequiredRuntimeSlot(52);
            world.Register(character);
            world.Register(weapon);
            world.Register(special);
            world.Register(other);

            RuntimeRestStore store = world.RuntimeRestStoreForServices;
            Expect(store != null && store.LogicalCapacity == 400 &&
                   character.ItrRest.IsBound && character.ItrRest.BoundVictimSlot == 0 &&
                   weapon.ItrRest.IsBound && weapon.ItrRest.BoundVictimSlot == 50 &&
                   special.ItrRest.IsBound && special.ItrRest.BoundVictimSlot == 51 &&
                   other.ItrRest.IsBound && other.ItrRest.BoundVictimSlot == 52,
                "production registration must bind character, weapon, special-attack, and other rest trackers to the world store");

            character.ItrRest.Arest = 7;
            character.ItrRest.SetVrest(50, 9);
            weapon.ItrRest.SetVrest(0, 11);
            world.Unregister(character);
            Expect(!character.ItrRest.IsBound && character.Runtime.SlotIndex == -1 &&
                   world.GetRawRestArest(0) == 7 && world.GetRawRestVrest(0, 50) == 9 &&
                   world.GetRawRestVrest(50, 0) == 11,
                "slot release must unbind the occupant while preserving inactive ARest and both VRest directions in the world store");

            var replacement = new FlowSelfCheckEntity(LF2ObjectType.Character);
            replacement.SetRequiredRuntimeSlot(0);
            replacement.ItrRest.Arest = 13;
            replacement.ItrRest.SetVrest(50, 15);
            world.Register(replacement);
            Expect(replacement.ItrRest.IsBound && replacement.ItrRest.BoundVictimSlot == 0 &&
                   replacement.ItrRest.Arest == 0 && replacement.ItrRest.GetVrest(50) == 0 &&
                   weapon.ItrRest.GetVrest(0) == 0 && store.ARestEntryCount == 0 &&
                   store.GetVRest(0, 50) == 0 && store.GetVRest(50, 0) == 0,
                "ordinary same-slot registration must clear owner ARest, victim row, and peer attacker column before rebinding");

            world.ResetRuntimeState();
            Expect(world.ObjectCount == 0 && world.ClaimedRuntimeSlotCountForServices == 0 &&
                   store.ARestEntryCount == 0 && store.VRestEntryCount == 0 &&
                   store.VRestRowCount == 0 && !replacement.ItrRest.IsBound &&
                   !weapon.ItrRest.IsBound && !special.ItrRest.IsBound && !other.ItrRest.IsBound,
                "world reset must unbind every registered tracker and clear the centralized rest store");

            var growingWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            var existingHigh = new FlowSelfCheckEntity(LF2ObjectType.Character);
            existingHigh.SetRequiredRuntimeSlot(511);
            growingWorld.Register(existingHigh);
            existingHigh.ItrRest.Arest = 6;
            existingHigh.ItrRest.SetVrest(1, 8);
            var grownTail = new FlowSelfCheckEntity(LF2ObjectType.Character);
            grownTail.SetRequiredRuntimeSlot(700);
            growingWorld.Register(grownTail);
            Expect(growingWorld.RuntimeSlotCapacity == 768 &&
                   growingWorld.RuntimeRestStoreForServices.LogicalCapacity == 768 &&
                   existingHigh.ItrRest.IsBound && existingHigh.ItrRest.BoundVictimSlot == 511 &&
                   existingHigh.ItrRest.Arest == 6 && existingHigh.ItrRest.GetVrest(1) == 8 &&
                   grownTail.ItrRest.IsBound && grownTail.ItrRest.BoundVictimSlot == 700,
                "desktop slot growth must grow the world rest store, preserve existing leases, and bind the new high slot");

            var rollbackWorld = new SimulationWorld();
            RuntimeRestStore rollbackStore = rollbackWorld.RuntimeRestStoreForServices;
            Expect(rollbackStore.TryAcquireBinding(20, out RuntimeRestBindingHandle blockingLease),
                "stage rollback fixture must reserve a conflicting store lease");
            var rejectedStage = new FlowSelfCheckEntity(LF2ObjectType.Character);
            rejectedStage.SetRequiredRuntimeSlot(20);
            rejectedStage.Runtime.SpawnSemantic = (int)ReleaseSpawnSemantic.StageSpawnAt;
            rollbackWorld.Register(rejectedStage);
            Expect(rejectedStage.Runtime.SlotIndex == 20 && !rejectedStage.ItrRest.IsBound &&
                   !rollbackWorld.RestoreStageSpawnRestState(20, rejectedStage),
                "StageSpawnAt registration must defer binding and surface a conflicting post-Initialize lease");
            rollbackWorld.Unregister(rejectedStage);
            Expect(rejectedStage.Runtime.SlotIndex == -1 &&
                   rollbackWorld.ClaimedRuntimeSlotCountForServices == 0 &&
                   rollbackWorld.ObjectCount == 0 && rollbackStore.IsBindingValid(blockingLease),
                "failed StageSpawnAt binding must support complete slot/bucket rollback without stealing the existing lease");
            rollbackStore.ReleaseBinding(blockingLease);

            var mismatchWorld = new SimulationWorld();
            var mismatched = new FlowSelfCheckEntity(LF2ObjectType.Character);
            mismatched.SetRequiredRuntimeSlot(20);
            mismatchWorld.Register(mismatched);
            RuntimeRestStore mismatchStore = mismatchWorld.RuntimeRestStoreForServices;
            mismatchStore.SetARest(20, 5);
            mismatchStore.SetVRest(20, 3, 7);
            Expect(mismatched.ItrRest.Unbind(false) &&
                   mismatched.ItrRest.Bind(mismatchStore, 21, false),
                "mismatched release fixture must move only the tracker lease away from its occupied runtime slot");
            mismatched.ItrRest.Arest = 9;
            mismatchWorld.Unregister(mismatched);
            Expect(mismatched.Runtime.SlotIndex == 20 &&
                   ReferenceEquals(mismatchWorld.FindEntityByRuntimeSlotIncludingPending(20), mismatched) &&
                   ReferenceEquals(mismatchWorld.FindEntityByRuntimeSlotForQuery(20), mismatched) &&
                   mismatchWorld.ClaimedRuntimeSlotCountForServices == 1 &&
                   mismatchWorld.ObjectCount == 1 && mismatched.RemovedCount == 0 &&
                   ReferenceEquals(mismatched.Match, mismatchWorld) &&
                   mismatched.ItrRest.IsBound && mismatched.ItrRest.BoundVictimSlot == 21 &&
                   mismatchStore.GetARest(20) == 5 && mismatchStore.GetVRest(20, 3) == 7 &&
                   mismatchStore.GetARest(21) == 9,
                "public unregister must reject a mismatched tracker lease without changing bucket, context, claim, slot index, lease, or rest state");
            mismatched.ItrRest.Unbind(false);
            Expect(mismatched.ItrRest.Bind(mismatchStore, 20, false),
                "mismatched release fixture must restore the owner binding for cleanup");
            mismatchWorld.Unregister(mismatched);

            var pendingWorld = new SimulationWorld();
            var pendingReuse = new PendingRestReuseSelfCheckEntity();
            pendingReuse.SetRequiredRuntimeSlot(50);
            pendingWorld.Register(pendingReuse);
            pendingReuse.ItrRest.Arest = 9;
            pendingWorld.LateEntityUpdateAll(1);
            Expect(pendingReuse.LateTickCount == 1 && pendingReuse.Runtime.SlotIndex == 50 &&
                   pendingReuse.ItrRest.IsBound && pendingReuse.ItrRest.BoundVictimSlot == 50 &&
                   pendingReuse.ItrRest.Arest == 0 && pendingWorld.ObjectCount == 1 &&
                   pendingWorld.ClaimedRuntimeSlotCountForServices == 1,
                "pending unregister/re-register must release the old lease in-stack and bind the reused slot without stale rest");
        }

        private static void CheckExtendedSimulationWorldCapacityContracts()
        {
            bool rejectedTooSmallCapacity = false;
            try
            {
                _ = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 49);
            }
            catch (ArgumentOutOfRangeException)
            {
                rejectedTooSmallCapacity = true;
            }

            bool rejectedNonAuthorityCapacity = false;
            try
            {
                _ = new SimulationWorld(BattleRuntimeProfile.Authority400, 512);
            }
            catch (ArgumentException)
            {
                rejectedNonAuthorityCapacity = true;
            }

            Expect(rejectedTooSmallCapacity && rejectedNonAuthorityCapacity,
                "capacity-aware worlds must retain the dynamic slot band and keep Authority400 exactly 400 slots");

            LF2CharacterData data = BuildComboWrapperCharacterData("SelfCheck_ExtendedWorld", 180);
            var world = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            LF2Character ai = CreateCharacter("SelfCheck_ExtendedWorld_AI", 33, data);
            LF2Character highTarget = CreateCharacter("SelfCheck_ExtendedWorld_Target", 4, data);
            var grownTail = new FlowSelfCheckEntity(LF2ObjectType.Character);
            ai.SetRequiredRuntimeSlot(0);
            highTarget.SetRequiredRuntimeSlot(511);
            grownTail.SetRequiredRuntimeSlot(700);
            ai.AiControlled = true;
            highTarget.AiControlled = false;
            ai.RelationTeam = 1;
            highTarget.RelationTeam = 2;
            ai.Runtime.SetPosition(100, 0, 200);
            highTarget.Runtime.SetPosition(260, 0, 210);
            ai.Runtime.SyncIntegerPosition();
            highTarget.Runtime.SyncIntegerPosition();

            world.Register(ai);
            world.Register(highTarget);
            world.Register(grownTail);

            Expect(world.RuntimeProfileForServices == BattleRuntimeProfile.DesktopExtended &&
                   world.MaxRuntimeSlotsForServices == 768 &&
                   highTarget.Runtime.SlotIndex == 511 &&
                   grownTail.Runtime.SlotIndex == 700 &&
                   ReferenceEquals(world.FindEntityByRuntimeSlotIncludingPending(511), highTarget) &&
                   ReferenceEquals(world.FindEntityByRuntimeSlotIncludingPending(700), grownTail),
                "DesktopExtended infrastructure must grow by one page for a required high runtime slot");

            Expect(world.AiNearestSpatialMatchesBruteForSelfCheck(ai, world.InputPhase),
                "DesktopExtended AI spatial nearest-target query must match the authority slot scan before input consumption");

            world.AiInputAndComboAll(2);
            Expect(ai.Runtime.Unk360 == 511,
                "capacity-aware AI slot snapshots and target scans must see a character in runtime slot 511");

            world.ResetRuntimeState();
            Expect(world.RuntimeProfileForServices == BattleRuntimeProfile.DesktopExtended &&
                   world.MaxRuntimeSlotsForServices == 768 &&
                   world.FindEntityByRuntimeSlotIncludingPending(511) == null &&
                   world.FindEntityByRuntimeSlotIncludingPending(700) == null &&
                   world.ObjectCount == 0,
                "extended world reset must clear high-slot occupants without changing the configured profile or capacity");

            var defaultWorld = new SimulationWorld();
            Expect(defaultWorld.RuntimeProfileForServices == BattleRuntimeProfile.Authority400 &&
                   defaultWorld.MaxRuntimeSlotsForServices == SimulationWorld.AuthorityRuntimeSlotCapacity,
                "the public SimulationWorld constructor must remain pinned to Authority400/400");
        }

        private static void CheckActivatedRuntimeProfileContracts()
        {
            var mobileWorld = new SimulationWorld(
                BattleRuntimeProfile.MobileExtended,
                BattleRuntimeProfilePolicy.MobileRuntimeSlotCapacity);
            var mobileEntities = new FlowSelfCheckEntity[1000];
            for (int slot = 0; slot < mobileEntities.Length; slot++)
            {
                var entity = new FlowSelfCheckEntity(LF2ObjectType.Character);
                entity.SetRequiredRuntimeSlot(slot);
                mobileEntities[slot] = entity;
                mobileWorld.Register(entity);
                Expect(entity.Runtime.SlotIndex == slot,
                    $"MobileExtended must accept active runtime entity {slot + 1} at required slot {slot}");
            }

            var rejectedMobileEntity = new FlowSelfCheckEntity(LF2ObjectType.Character);
            rejectedMobileEntity.SetRequiredRuntimeSlot(1049);
            mobileWorld.Register(rejectedMobileEntity);
            Expect(mobileWorld.ClaimedRuntimeSlotCountForServices == 1000 &&
                   mobileWorld.ObjectCount == 1000 &&
                   rejectedMobileEntity.Runtime.SlotIndex == -1 &&
                   mobileWorld.FindEntityByRuntimeSlotIncludingPending(1049) == null,
                "MobileExtended must deterministically reject the 1001st active entity before publishing slot or bucket residue");
            var findMobileFreeRuntimeSlot = typeof(SimulationWorld).GetMethod(
                "FindFirstFreeRuntimeSlot",
                System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.NonPublic);
            Expect(findMobileFreeRuntimeSlot != null,
                "MobileExtended admission fixture must retain the shared free-slot query");
            int blockedMobileFreeSlot = (int)findMobileFreeRuntimeSlot.Invoke(
                mobileWorld,
                new object[] { 50, mobileWorld.MaxRuntimeSlotsForServices });
            Expect(blockedMobileFreeSlot == -1 &&
                   mobileWorld.FindEntityByRuntimeSlotIncludingPending(1049) == null,
                "MobileExtended free-slot queries must reject at 1000 total active entities even while high dynamic addresses remain unclaimed");

            mobileEntities[333].Runtime.PendingFlushDestroy = true;
            Expect(mobileWorld.ClaimedRuntimeSlotCountForServices == 1000,
                "MobileExtended pending-destroy entities must consume admission until the existing release boundary");
            var replacementMobileEntity = new FlowSelfCheckEntity(LF2ObjectType.Character);
            replacementMobileEntity.SetRequiredRuntimeSlot(333);
            mobileWorld.Register(replacementMobileEntity);
            Expect(mobileWorld.ClaimedRuntimeSlotCountForServices == 1000 &&
                   mobileWorld.ObjectCount == 1000 &&
                   replacementMobileEntity.Runtime.SlotIndex == 333 &&
                   ReferenceEquals(
                       mobileWorld.FindEntityByRuntimeSlotIncludingPending(333),
                       replacementMobileEntity),
                "MobileExtended must admit a replacement only after ReleasePendingDestroySlots frees its deterministic budget");
            mobileWorld.ResetRuntimeState();
            Expect(mobileWorld.ClaimedRuntimeSlotCountForServices == 0,
                "MobileExtended reset must clear the active admission count");

            var desktopWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            var desktopEntities = new FlowSelfCheckEntity[512];
            for (int slot = 0; slot < desktopEntities.Length; slot++)
            {
                var entity = new FlowSelfCheckEntity(LF2ObjectType.Character);
                entity.SetRequiredRuntimeSlot(slot);
                desktopEntities[slot] = entity;
                desktopWorld.Register(entity);
            }

            desktopWorld.Unregister(desktopEntities[51]);
            var reusedDesktopEntity = new FlowSelfCheckEntity(LF2ObjectType.Character);
            desktopWorld.Register(reusedDesktopEntity);
            Expect(reusedDesktopEntity.Runtime.SlotIndex == 51 &&
                   desktopWorld.MaxRuntimeSlotsForServices == 512,
                "DesktopExtended ordinary allocation must reuse the lowest old hole before growing");

            var findFreeRuntimeSlot = typeof(SimulationWorld).GetMethod(
                "FindFirstFreeRuntimeSlot",
                System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.NonPublic);
            Expect(findFreeRuntimeSlot != null,
                "DesktopExtended growth fixture must retain the shared free-slot query");
            int peekedGrownSlot = (int)findFreeRuntimeSlot.Invoke(
                desktopWorld,
                new object[] { 50, desktopWorld.MaxRuntimeSlotsForServices });
            Expect(peekedGrownSlot == 512 &&
                   desktopWorld.MaxRuntimeSlotsForServices == 768,
                "DesktopExtended free-slot queries must grow one page only after the current range is full");
            var firstGrownDesktopEntity = new FlowSelfCheckEntity(LF2ObjectType.Character);
            desktopWorld.Register(firstGrownDesktopEntity);
            Expect(firstGrownDesktopEntity.Runtime.SlotIndex == 512,
                "DesktopExtended ordinary registration must claim the first address on the grown page");

            var aiResizeWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            var retainedAiEntity = new FlowSelfCheckEntity(LF2ObjectType.Character);
            retainedAiEntity.SetRequiredRuntimeSlot(511);
            aiResizeWorld.Register(retainedAiEntity);
            var buildAiSnapshot = typeof(SimulationWorld).GetMethod(
                "BuildAiInputSlotSnapshot",
                System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.NonPublic);
            var aiAt = typeof(SimulationWorld).GetMethod(
                "AiAt",
                System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.NonPublic);
            Expect(buildAiSnapshot != null && aiAt != null,
                "DesktopExtended AI growth fixture must retain AI snapshot helpers");
            buildAiSnapshot.Invoke(aiResizeWorld, null);
            var requiredHighEntity = new FlowSelfCheckEntity(LF2ObjectType.Character);
            requiredHighEntity.SetRequiredRuntimeSlot(700);
            aiResizeWorld.Register(requiredHighEntity);
            LF2Entity retainedAiSnapshot = aiAt.Invoke(aiResizeWorld, new object[] { 511 }) as LF2Entity;
            Expect(aiResizeWorld.MaxRuntimeSlotsForServices == 768 &&
                   requiredHighEntity.Runtime.SlotIndex == 700 &&
                   ReferenceEquals(retainedAiSnapshot, retainedAiEntity),
                "DesktopExtended required-slot growth must preserve existing AI snapshot contents while resizing its buffer");
            Expect(SimulationTickDriver.WorldMatchesRuntimeSettings(
                       aiResizeWorld,
                       BattleRuntimeProfilePolicy.Create(BattleRuntimeProfile.DesktopExtended, 512)),
                "Driver pre-battle profile refresh must accept a DesktopExtended world that has grown beyond its configured initial capacity");

            BattleParityFrameSnapshot skippedExtendedChecksum =
                SimulationTickDriver.CaptureSupportedFrameSnapshot(
                    aiResizeWorld,
                    1,
                    FrameInputSet.Empty(1));
            Expect(skippedExtendedChecksum == null &&
                   !SimulationTickDriver.SupportsAuthorityFrameChecksum(aiResizeWorld),
                "SimulationTickDriver legacy Authority snapshot helper must skip Extended worlds without throwing");
            IBattleChecksumSnapshot extendedChecksum =
                SimulationTickDriver.CaptureSupportedChecksumSnapshot(
                    aiResizeWorld,
                    1,
                    FrameInputSet.Empty(1));
            Expect(extendedChecksum is BattleExtendedChecksumSnapshot &&
                   SimulationTickDriver.SupportsFrameChecksum(aiResizeWorld),
                "SimulationTickDriver general checksum helper must support Extended worlds without changing the legacy Authority helper");
            var authorityWorld = new SimulationWorld();
            Expect(SimulationTickDriver.CaptureSupportedFrameSnapshot(
                       authorityWorld,
                       1,
                       FrameInputSet.Empty(1)) != null,
                "SimulationTickDriver must retain frame checksum capture for Authority400 worlds");
        }

        private static void CheckIncrementalLooseQuadtreeContracts()
        {
            var preferredRoot = new SpatialAabbXZ(0, 0, 256, 256);
            var handle0 = new RuntimeEntityHandle(0, 1);
            var handle1 = new RuntimeEntityHandle(1, 1);
            var handle2 = new RuntimeEntityHandle(2, 1);
            var entries = new List<IncrementalSpatialEntry>
            {
                new IncrementalSpatialEntry(handle0, new SpatialAabbXZ(10, 10, 20, 20)),
                new IncrementalSpatialEntry(handle1, new SpatialAabbXZ(200, 200, 210, 210)),
            };
            var tree = new LooseQuadtreeBroadphase(1, 4);

            SpatialSynchronizeResult initial = tree.Synchronize(entries, preferredRoot);
            Expect(initial.Succeeded && initial.FullRebuild && initial.IndexedCount == 2 &&
                   tree.IncrementalFullRebuildCount == 1,
                "incremental quadtree must establish its first generation-aware index with one deterministic rebuild");

            SpatialSynchronizeResult stationary = tree.Synchronize(entries, preferredRoot);
            Expect(stationary.Succeeded && !stationary.FullRebuild &&
                   stationary.InsertedCount == 0 && stationary.UpdatedInPlaceCount == 0 &&
                   stationary.MigratedCount == 0 && stationary.RemovedCount == 0 &&
                   tree.IncrementalFullRebuildCount == 1,
                "stationary incremental entries must not rebuild, migrate, or rewrite their node placement");

            entries[0] = new IncrementalSpatialEntry(
                handle0,
                new SpatialAabbXZ(15, 15, 25, 25));
            SpatialSynchronizeResult looseUpdate = tree.Synchronize(entries, preferredRoot);
            Expect(looseUpdate.Succeeded && !looseUpdate.FullRebuild &&
                   looseUpdate.UpdatedInPlaceCount == 1 && looseUpdate.MigratedCount == 0,
                "an AABB update retained by its current loose node must update in place");

            entries[0] = new IncrementalSpatialEntry(
                handle0,
                new SpatialAabbXZ(170, 170, 180, 180));
            SpatialSynchronizeResult crossedBoundary = tree.Synchronize(entries, preferredRoot);
            Expect(crossedBoundary.Succeeded && !crossedBoundary.FullRebuild &&
                   crossedBoundary.MigratedCount == 1 && tree.IncrementalMigrationCount >= 1,
                "an AABB leaving its current loose node must migrate without rebuilding the root");

            entries.RemoveAt(1);
            entries.Add(new IncrementalSpatialEntry(
                handle2,
                new SpatialAabbXZ(30, 30, 40, 40)));
            SpatialSynchronizeResult spawnRemove = tree.Synchronize(entries, preferredRoot);
            Expect(spawnRemove.Succeeded && spawnRemove.InsertedCount == 1 &&
                   spawnRemove.RemovedCount == 1 && spawnRemove.IndexedCount == 2,
                "incremental synchronization must insert spawned handles and remove absent handles in one tick");

            RuntimeEntityHandle replacementHandle0 = new RuntimeEntityHandle(0, 2);
            entries[0] = new IncrementalSpatialEntry(
                replacementHandle0,
                new SpatialAabbXZ(170, 170, 180, 180));
            SpatialSynchronizeResult generationReuse = tree.Synchronize(entries, preferredRoot);
            var queriedHandles = new List<RuntimeEntityHandle>();
            tree.QueryHandles(entries[0].Bounds, queriedHandles);
            Expect(generationReuse.Succeeded && generationReuse.InsertedCount == 1 &&
                   generationReuse.RemovedCount == 1 &&
                   queriedHandles.Contains(replacementHandle0) && !queriedHandles.Contains(handle0),
                "slot reuse must evict the stale generation and return only the current handle");

            entries.RemoveAt(0);
            SpatialSynchronizeResult invalidRemoval = tree.Synchronize(entries, preferredRoot);
            entries.Insert(0, new IncrementalSpatialEntry(
                replacementHandle0,
                new SpatialAabbXZ(170, 170, 180, 180)));
            SpatialSynchronizeResult validRestore = tree.Synchronize(entries, preferredRoot);
            Expect(invalidRemoval.Succeeded && invalidRemoval.RemovedCount == 1 &&
                   validRestore.Succeeded && validRestore.InsertedCount == 1 &&
                   validRestore.IndexedCount == 2,
                "valid-invalid-valid AABB participation must remove and later reinsert the same current handle");

            entries[0] = new IncrementalSpatialEntry(
                replacementHandle0,
                new SpatialAabbXZ(2000, 2000, 2010, 2010));
            SpatialSynchronizeResult rootEscape = tree.Synchronize(entries, preferredRoot);
            Expect(rootEscape.Succeeded && rootEscape.FullRebuild &&
                   tree.IncrementalFullRebuildCount == 2 &&
                   tree.IncrementalRootMinX <= 2000 &&
                   tree.IncrementalRootMinX + tree.IncrementalRootSide >= 2010 &&
                   tree.IncrementalRootMinZ <= 2000 &&
                   tree.IncrementalRootMinZ + tree.IncrementalRootSide >= 2010,
                "an AABB escaping the loose root must trigger a deterministic full rebuild that covers it");

            var random = new System.Random(0x423242);
            var differentialTree = new LooseQuadtreeBroadphase(4, 7);
            var differentialEntries = new List<IncrementalSpatialEntry>(64);
            var differentialBounds = new Dictionary<RuntimeEntityHandle, SpatialAabbXZ>();
            var treePairs = new List<long>(256);
            var brutePairs = new List<long>(256);
            var queryHandles = new List<RuntimeEntityHandle>(64);
            for (int i = 0; i < 64; i++)
            {
                int x = random.Next(-200, 601);
                int z = random.Next(-100, 401);
                int width = random.Next(4, 48);
                int depth = random.Next(4, 48);
                differentialEntries.Add(new IncrementalSpatialEntry(
                    new RuntimeEntityHandle(i, 1),
                    new SpatialAabbXZ(x, z, x + width, z + depth)));
            }

            for (int tick = 0; tick < 24; tick++)
            {
                if (tick == 7)
                    differentialEntries.RemoveAt(differentialEntries.Count - 1);
                if (tick == 13)
                {
                    differentialEntries.Add(new IncrementalSpatialEntry(
                        new RuntimeEntityHandle(63, 2),
                        new SpatialAabbXZ(40, 40, 70, 70)));
                }

                for (int i = 0; i < differentialEntries.Count; i++)
                {
                    IncrementalSpatialEntry entry = differentialEntries[i];
                    int dx = random.Next(-4, 5);
                    int dz = random.Next(-4, 5);
                    SpatialAabbXZ bounds = entry.Bounds;
                    differentialEntries[i] = new IncrementalSpatialEntry(
                        entry.Handle,
                        new SpatialAabbXZ(
                            bounds.MinX + dx,
                            bounds.MinZ + dz,
                            bounds.MaxX + dx,
                            bounds.MaxZ + dz));
                }

                SpatialSynchronizeResult result = differentialTree.Synchronize(
                    differentialEntries,
                    preferredRoot);
                Expect(result.Succeeded && result.IndexedCount == differentialEntries.Count,
                    $"incremental fixed-seed differential tick {tick} must synchronize every active handle");

                differentialBounds.Clear();
                for (int i = 0; i < differentialEntries.Count; i++)
                    differentialBounds.Add(differentialEntries[i].Handle, differentialEntries[i].Bounds);

                treePairs.Clear();
                for (int i = 0; i < differentialEntries.Count; i++)
                {
                    IncrementalSpatialEntry first = differentialEntries[i];
                    differentialTree.QueryHandles(first.Bounds, queryHandles);
                    for (int q = 0; q < queryHandles.Count; q++)
                    {
                        RuntimeEntityHandle other = queryHandles[q];
                        if (other.Slot <= first.Handle.Slot ||
                            !differentialBounds.TryGetValue(other, out SpatialAabbXZ otherBounds) ||
                            !first.Bounds.Overlaps(otherBounds))
                        {
                            continue;
                        }
                        treePairs.Add(SpatialPairKey(first.Handle.Slot, other.Slot));
                    }
                }

                brutePairs.Clear();
                for (int i = 0; i < differentialEntries.Count; i++)
                {
                    for (int j = i + 1; j < differentialEntries.Count; j++)
                    {
                        if (differentialEntries[i].Bounds.Overlaps(differentialEntries[j].Bounds))
                        {
                            brutePairs.Add(SpatialPairKey(
                                differentialEntries[i].Handle.Slot,
                                differentialEntries[j].Handle.Slot));
                        }
                    }
                }

                SortUniqueSpatialPairs(treePairs);
                SortUniqueSpatialPairs(brutePairs);
                Expect(SpatialPairListsEqual(treePairs, brutePairs),
                    $"incremental fixed-seed differential tick {tick} must match brute overlap pairs");
            }
        }

        private static void CheckLooseQuadtreeShadowBroadphaseContracts()
        {
            Expect(CollisionBroadphaseBackendResolver.Resolve(
                       "LooseQuadtree",
                       "BruteForce") == CollisionBroadphaseBackend.LooseQuadtree &&
                   CollisionBroadphaseBackendResolver.Resolve(
                       null,
                       "LooseQuadtree") == CollisionBroadphaseBackend.LooseQuadtree &&
                   CollisionBroadphaseBackendResolver.Resolve(
                       "invalid",
                       null) == CollisionBroadphaseBackend.BruteForce &&
                   !CollisionBroadphaseBackendResolver.TryParse("1", out _),
                "collision broadphase backend must use explicit-over-config precedence and default to BruteForce");

            var bruteParityWorld = new SimulationWorld();
            var treeParityWorld = new SimulationWorld(
                BattleRuntimeProfile.Authority400,
                SimulationWorld.AuthorityRuntimeSlotCapacity,
                CollisionBroadphaseBackend.LooseQuadtree);
            LF2FrameData parityAttackerFrame = BuildCollisionAuditFrame(
                0,
                LF2States.Standing,
                MakeCollisionAuditItr(0, -20, -20, 40, 40, 20, 1),
                null);
            LF2FrameData parityTargetFrame = BuildCollisionAuditFrame(
                0,
                LF2States.Standing,
                null,
                new BodyBox { kind = 0, x = -20, y = -20, w = 40, h = 40 });
            LF2Character bruteAttacker = CreateInteractionCharacter(
                "SelfCheck_FormalBroadphaseAttacker",
                1,
                BuildCollisionAuditData("SelfCheck_FormalBroadphaseAttacker", parityAttackerFrame));
            LF2Character bruteTarget = CreateInteractionCharacter(
                "SelfCheck_FormalBroadphaseTarget",
                37,
                BuildCollisionAuditData("SelfCheck_FormalBroadphaseTarget", parityTargetFrame));
            LF2Character treeAttacker = CreateInteractionCharacter(
                "SelfCheck_FormalBroadphaseAttackerTree",
                1,
                BuildCollisionAuditData("SelfCheck_FormalBroadphaseAttackerTree", parityAttackerFrame));
            LF2Character treeTarget = CreateInteractionCharacter(
                "SelfCheck_FormalBroadphaseTargetTree",
                37,
                BuildCollisionAuditData("SelfCheck_FormalBroadphaseTargetTree", parityTargetFrame));
            RegisterCollisionAuditPair(bruteParityWorld, bruteAttacker, bruteTarget, 1, 2);
            RegisterCollisionAuditPair(treeParityWorld, treeAttacker, treeTarget, 1, 2);
            SetCollisionAuditFramePair(bruteAttacker, parityAttackerFrame, parityAttackerFrame);
            SetCollisionAuditFramePair(bruteTarget, parityTargetFrame, parityTargetFrame);
            SetCollisionAuditFramePair(treeAttacker, parityAttackerFrame, parityAttackerFrame);
            SetCollisionAuditFramePair(treeTarget, parityTargetFrame, parityTargetFrame);
            InteractionArea parityItr = parityAttackerFrame.itrs[0];
            List<SceneQueryHit> bruteImmediate = bruteParityWorld.SceneQuery.QueryBodyHits(
                bruteAttacker,
                parityAttackerFrame,
                parityItr);
            bool bruteImmediateMatched = bruteImmediate.Count == 1 &&
                                         bruteImmediate[0].Target == bruteTarget;
            List<SceneQueryHit> treeImmediate = treeParityWorld.SceneQuery.QueryBodyHits(
                treeAttacker,
                parityAttackerFrame,
                parityItr);
            bool treeImmediateMatched = treeImmediate.Count == 1 &&
                                        treeImmediate[0].Target == treeTarget;
            var immediateVolume = new PhysicsState.BattleVolume(
                -1000f,
                -1000f,
                0f,
                0f,
                0f,
                2000f,
                2000f,
                1000f);
            List<SceneQueryHit> bruteVolumeImmediate = bruteParityWorld.SceneQuery.QueryBodyHits(
                bruteAttacker,
                parityAttackerFrame,
                parityItr,
                immediateVolume);
            int bruteVolumeImmediateCount = bruteVolumeImmediate.Count;
            List<SceneQueryHit> treeVolumeImmediate = treeParityWorld.SceneQuery.QueryBodyHits(
                treeAttacker,
                parityAttackerFrame,
                parityItr,
                immediateVolume);
            int treeVolumeImmediateCount = treeVolumeImmediate.Count;
            List<SceneQueryHit> bruteBodyImmediate = bruteParityWorld.SceneQuery.QueryBodyHits(
                immediateVolume,
                bruteAttacker);
            int bruteBodyImmediateCount = bruteBodyImmediate.Count;
            List<SceneQueryHit> treeBodyImmediate = treeParityWorld.SceneQuery.QueryBodyHits(
                immediateVolume,
                treeAttacker);
            int treeBodyImmediateCount = treeBodyImmediate.Count;
            Expect(bruteImmediateMatched && treeImmediateMatched &&
                   bruteVolumeImmediateCount == treeVolumeImmediateCount &&
                   bruteVolumeImmediateCount == 1 &&
                   bruteBodyImmediateCount == treeBodyImmediateCount &&
                   bruteBodyImmediateCount == 1,
                "LooseQuadtree immediate itr/volume/body queries must preserve brute target selection and order");

            var immediateOrderWorld = new SimulationWorld(
                BattleRuntimeProfile.Authority400,
                SimulationWorld.AuthorityRuntimeSlotCapacity,
                CollisionBroadphaseBackend.LooseQuadtree);
            LF2Character invalidFirst = CreateInteractionCharacter(
                "SelfCheck_ImmediateInvalidFirst",
                37,
                BuildCollisionAuditData("SelfCheck_ImmediateInvalidFirst", parityTargetFrame));
            LF2Character orderedAttacker = CreateInteractionCharacter(
                "SelfCheck_ImmediateOrderedAttacker",
                1,
                BuildCollisionAuditData("SelfCheck_ImmediateOrderedAttacker", parityAttackerFrame));
            LF2Character orderedTarget = CreateInteractionCharacter(
                "SelfCheck_ImmediateOrderedTarget",
                37,
                BuildCollisionAuditData("SelfCheck_ImmediateOrderedTarget", parityTargetFrame));
            invalidFirst.SetRuntimeSlotIndex(1);
            orderedAttacker.SetRuntimeSlotIndex(2);
            orderedTarget.SetRuntimeSlotIndex(3);
            RegisterCollisionAuditPair(immediateOrderWorld, invalidFirst, orderedAttacker, 1, 2);
            immediateOrderWorld.Register(orderedTarget);
            LF2FrameData invalidImmediateFrame =
                BuildCollisionAuditFrame(0, LF2States.Standing, null, null);
            SetCollisionAuditFramePair(invalidFirst, invalidImmediateFrame, invalidImmediateFrame);
            SetCollisionAuditFramePair(orderedAttacker, parityAttackerFrame, parityAttackerFrame);
            SetCollisionAuditFramePair(orderedTarget, parityTargetFrame, parityTargetFrame);
            List<SceneQueryHit> orderedImmediate = immediateOrderWorld.SceneQuery.QueryBodyHits(
                orderedAttacker,
                parityAttackerFrame,
                parityItr);
            Expect(orderedImmediate.Count == 1 && orderedImmediate[0].Target == orderedTarget,
                "LooseQuadtree immediate query must preserve valid targets when an earlier source entry falls back due to invalid AABB");
            uint bruteRngBefore = bruteParityWorld.Rng.State;
            ulong bruteCallsBefore = bruteParityWorld.Rng.CallCount;
            uint treeRngBefore = treeParityWorld.Rng.State;
            ulong treeCallsBefore = treeParityWorld.Rng.CallCount;
            var treeParityQuery = treeParityWorld.SceneQuery as BruteForceSceneQuery;
            Expect(treeParityQuery != null,
                "formal LooseQuadtree collection requires a BruteForceSceneQuery");
            treeParityQuery.ForceRoleAwareTreeForDiagnostics = true;
            List<SceneQueryHit> bruteParityCandidates = CollectCollisionAuditCandidates(
                bruteParityWorld,
                bruteAttacker,
                true);
            List<SceneQueryHit> treeParityCandidates = CollectCollisionAuditCandidates(
                treeParityWorld,
                treeAttacker,
                true);
            Expect(treeParityQuery != null &&
                   treeParityQuery.CollisionBroadphase == CollisionBroadphaseBackend.LooseQuadtree &&
                   treeParityQuery.LastFormalCollectorModeForDiagnostics ==
                   CollisionFormalCollectorMode.ForceRoleAware &&
                   !treeParityQuery.FormalCollectionAborted &&
                   treeParityQuery.FormalSpatialSynchronizeResult.Succeeded &&
                   treeParityQuery.FormalSpatialSynchronizeResult.FullRebuild &&
                   treeParityQuery.FormalSpatialSynchronizeResult.IndexedCount == 1 &&
                   treeParityQuery.FormalBroadphaseForSelfCheck.IncrementalFullRebuildCount == 1,
                "formal LooseQuadtree collection must use the role-aware tree path and complete its initial rebuild");
            Expect(treeParityCandidates.Count == bruteParityCandidates.Count &&
                   treeParityCandidates.Count == 1 &&
                   treeParityCandidates[0].Target == treeTarget,
                "formal LooseQuadtree collection must preserve brute candidate count, order, and target");
            Expect(bruteParityWorld.Rng.State == bruteRngBefore &&
                   bruteParityWorld.Rng.CallCount == bruteCallsBefore &&
                   treeParityWorld.Rng.State == treeRngBefore &&
                   treeParityWorld.Rng.CallCount == treeCallsBefore,
                "formal LooseQuadtree collection must preserve brute and tree RNG state and call count");

            uint bruteStationaryRng = bruteParityWorld.Rng.State;
            ulong bruteStationaryCalls = bruteParityWorld.Rng.CallCount;
            uint treeStationaryRng = treeParityWorld.Rng.State;
            ulong treeStationaryCalls = treeParityWorld.Rng.CallCount;
            List<SceneQueryHit> bruteStationaryCandidates = CollectCollisionAuditCandidates(
                bruteParityWorld,
                bruteAttacker,
                true);
            List<SceneQueryHit> treeStationaryCandidates = CollectCollisionAuditCandidates(
                treeParityWorld,
                treeAttacker,
                true);
            Expect(!treeParityQuery.FormalCollectionAborted &&
                   treeParityQuery.LastFormalCollectorModeForDiagnostics ==
                   CollisionFormalCollectorMode.ForceRoleAware &&
                   treeParityQuery.FormalSpatialSynchronizeResult.Succeeded &&
                   !treeParityQuery.FormalSpatialSynchronizeResult.FullRebuild &&
                   treeParityQuery.FormalSpatialSynchronizeResult.InsertedCount == 0 &&
                   treeParityQuery.FormalSpatialSynchronizeResult.UpdatedInPlaceCount == 0 &&
                   treeParityQuery.FormalSpatialSynchronizeResult.MigratedCount == 0 &&
                   treeParityQuery.FormalSpatialSynchronizeResult.RemovedCount == 0 &&
                   treeParityQuery.FormalBroadphaseForSelfCheck.IncrementalFullRebuildCount == 1,
                "formal incremental collection must reuse a stationary role-aware tree index");
            Expect(treeStationaryCandidates.Count == bruteStationaryCandidates.Count &&
                   treeStationaryCandidates.Count == 1 &&
                   treeStationaryCandidates[0].Target == treeTarget,
                "formal stationary collection must preserve brute candidate count, order, and target");
            Expect(bruteParityWorld.Rng.State == bruteStationaryRng &&
                   bruteParityWorld.Rng.CallCount == bruteStationaryCalls &&
                   treeParityWorld.Rng.State == treeStationaryRng &&
                   treeParityWorld.Rng.CallCount == treeStationaryCalls,
                "formal stationary collection must preserve brute and tree RNG state and call count");

            bruteTarget.Runtime.SetPosition(600, 0, 0);
            bruteTarget.Runtime.SyncIntegerPosition();
            treeTarget.Runtime.SetPosition(600, 0, 0);
            treeTarget.Runtime.SyncIntegerPosition();
            uint bruteMovedRng = bruteParityWorld.Rng.State;
            ulong bruteMovedCalls = bruteParityWorld.Rng.CallCount;
            uint treeMovedRng = treeParityWorld.Rng.State;
            ulong treeMovedCalls = treeParityWorld.Rng.CallCount;
            List<SceneQueryHit> bruteMovedCandidates = CollectCollisionAuditCandidates(
                bruteParityWorld,
                bruteAttacker,
                true);
            List<SceneQueryHit> treeMovedCandidates = CollectCollisionAuditCandidates(
                treeParityWorld,
                treeAttacker,
                true);
            Expect(!treeParityQuery.FormalCollectionAborted &&
                   treeParityQuery.FormalSpatialSynchronizeResult.Succeeded,
                "formal incremental movement must synchronize the role-aware tree without aborting");
            Expect(treeMovedCandidates.Count == bruteMovedCandidates.Count &&
                   treeMovedCandidates.Count == 0,
                "formal incremental movement must preserve brute candidate count, order, and target");
            Expect(bruteParityWorld.Rng.State == bruteMovedRng &&
                   bruteParityWorld.Rng.CallCount == bruteMovedCalls &&
                   treeParityWorld.Rng.State == treeMovedRng &&
                   treeParityWorld.Rng.CallCount == treeMovedCalls,
                "formal incremental movement must preserve brute and tree RNG state and call count");

            var fallbackWorld = new SimulationWorld(
                BattleRuntimeProfile.Authority400,
                SimulationWorld.AuthorityRuntimeSlotCapacity,
                CollisionBroadphaseBackend.LooseQuadtree);
            LF2Character fallbackAttacker = CreateInteractionCharacter(
                "SelfCheck_FormalBroadphaseFallbackAttacker",
                1,
                BuildCollisionAuditData(
                    "SelfCheck_FormalBroadphaseFallbackAttacker",
                    parityAttackerFrame));
            LF2Character fallbackTarget = CreateInteractionCharacter(
                "SelfCheck_FormalBroadphaseFallbackTarget",
                37,
                    BuildCollisionAuditData(
                        "SelfCheck_FormalBroadphaseFallbackTarget",
                    BuildCollisionAuditFrame(0, LF2States.Standing, null, null)));
            RegisterCollisionAuditPair(fallbackWorld, fallbackAttacker, fallbackTarget, 1, 2);
            SetCollisionAuditFramePair(fallbackAttacker, parityAttackerFrame, parityAttackerFrame);
            LF2FrameData fallbackTargetFrame = BuildCollisionAuditFrame(0, LF2States.Standing, null, null);
            SetCollisionAuditFramePair(fallbackTarget, fallbackTargetFrame, fallbackTargetFrame);
            fallbackWorld.CaptureCollisionFrameSnapshotsAll();
            fallbackWorld.CollectCollisionCandidatesAll();
            var fallbackQuery = fallbackWorld.SceneQuery as BruteForceSceneQuery;
            Expect(fallbackQuery != null &&
                   fallbackQuery.FormalFallbackParticipantCount == 1 &&
                   !fallbackQuery.FormalCollectionAborted,
                "formal LooseQuadtree must conservatively retain participants whose AABB cannot be built: " +
                $"mode={fallbackQuery?.LastFormalCollectorModeForDiagnostics}," +
                $"participants={fallbackQuery?.LastRoleAwareParticipantCountForDiagnostics}," +
                $"inert={fallbackQuery?.LastRoleAwareInertParticipantCountForDiagnostics}," +
                $"bodies={fallbackQuery?.LastRoleAwareBodyEntryCountForDiagnostics}," +
                $"itrs={fallbackQuery?.LastRoleAwareItrQueryCountForDiagnostics}," +
                $"fallback={fallbackQuery?.FormalFallbackParticipantCount}," +
                $"aborted={fallbackQuery?.FormalCollectionAborted}");
            fallbackWorld.EndCollisionCandidateConsumption();

            var edgeA = new SpatialAabbXZ(0, 0, 10, 10);
            var edgeB = new SpatialAabbXZ(10, 0, 20, 10);
            var overlapB = new SpatialAabbXZ(9, 0, 20, 10);
            Expect(!edgeA.Overlaps(edgeB) && edgeA.Overlaps(overlapB),
                "LooseQuadtree AABBs must use half-open X/Z overlap semantics");

            var retainedEntries = new List<SpatialBroadphaseEntry>
            {
                new SpatialBroadphaseEntry(0, 0, new SpatialAabbXZ(80, 80, 176, 176)),
                new SpatialBroadphaseEntry(1, 1, new SpatialAabbXZ(4, 4, 8, 8)),
            };
            var retainedTree = new LooseQuadtreeBroadphase(1, 4);
            retainedTree.Rebuild(retainedEntries, new SpatialAabbXZ(0, 0, 256, 256));
            Expect(retainedTree.NodeCount == 5 && retainedTree.RootRetainedEntryCount == 1,
                "an AABB crossing a child loose boundary must remain once in its parent after split");

            var depthEntries = new List<SpatialBroadphaseEntry>(17);
            for (int i = 0; i < 17; i++)
            {
                depthEntries.Add(new SpatialBroadphaseEntry(
                    i,
                    i,
                    new SpatialAabbXZ(1, 1, 2, 2)));
            }

            var depthTree = new LooseQuadtreeBroadphase(16, 8);
            depthTree.Rebuild(depthEntries, new SpatialAabbXZ(0, 0, 256, 256));
            var depthQuery = new List<int>();
            depthTree.Query(new SpatialAabbXZ(1, 1, 2, 2), depthQuery);
            depthQuery.Sort();
            Expect(depthTree.NodeCount > 1 &&
                   depthTree.MaximumObservedDepth == 8 &&
                   depthQuery.Count == 17,
                "17 coincident entries must split deterministically and stop at max depth without duplication");

            var growthEntries = new List<SpatialBroadphaseEntry>
            {
                new SpatialBroadphaseEntry(0, 0, new SpatialAabbXZ(-600, -20, -590, -10)),
                new SpatialBroadphaseEntry(1, 1, new SpatialAabbXZ(1500, 900, 1510, 910)),
            };
            var growthTree = new LooseQuadtreeBroadphase(1, 4);
            growthTree.Rebuild(growthEntries, new SpatialAabbXZ(0, 180, 800, 350));
            Expect(growthTree.RootMinX <= -600 && growthTree.RootMinZ <= -20 &&
                   growthTree.RootMinX + growthTree.RootSide >= 1510 &&
                   growthTree.RootMinZ + growthTree.RootSide >= 910,
                "root growth must use floor semantics and cover negative/out-of-stage bounds");

            var ordered = new List<SpatialBroadphaseEntry>(40);
            var reversed = new List<SpatialBroadphaseEntry>(40);
            for (int i = 0; i < 40; i++)
            {
                int x = (i % 8) * 12 - 30;
                int z = (i / 8) * 9 - 20;
                ordered.Add(new SpatialBroadphaseEntry(
                    100 + i,
                    i,
                    new SpatialAabbXZ(x, z, x + 18, z + 14)));
            }
            for (int i = ordered.Count - 1; i >= 0; i--)
            {
                SpatialBroadphaseEntry entry = ordered[i];
                reversed.Add(new SpatialBroadphaseEntry(
                    entry.RuntimeSlot,
                    reversed.Count,
                    entry.Bounds));
            }

            List<long> orderedPairs = CollectLooseQuadtreePairs(ordered);
            List<long> reversedPairs = CollectLooseQuadtreePairs(reversed);
            Expect(SpatialPairListsEqual(orderedPairs, reversedPairs),
                "quadtree overlap pairs must be invariant to insertion order");

            var random = new System.Random(0x4E545344);
            var randomEntries = new List<SpatialBroadphaseEntry>(1000);
            for (int i = 0; i < 1000; i++)
            {
                int x = random.Next(-4000, 4001);
                int z = random.Next(-2000, 2001);
                int w = random.Next(1, 65);
                int d = random.Next(1, 65);
                randomEntries.Add(new SpatialBroadphaseEntry(
                    i,
                    i,
                    new SpatialAabbXZ(x, z, x + w, z + d)));
            }

            List<long> treePairs = CollectLooseQuadtreePairs(randomEntries);
            List<long> brutePairs = CollectSpatialBrutePairs(randomEntries);
            Expect(SpatialPairListsEqual(treePairs, brutePairs),
                "fixed-seed 1000-AABB quadtree output must equal the O(N^2) differential baseline");

            LF2FrameData kind5Frame = Frame(0, LF2States.Standing, 1, 0, 0, 0);
            kind5Frame.centerx = 50;
            kind5Frame.itrs.Add(new InteractionArea
            {
                kind = 5,
                x = 10,
                y = 0,
                w = 20,
                h = 20,
                zwidth = 0,
            });
            LF2Character kind5Entity = CreateInteractionCharacter(
                "SelfCheck_LooseQuadtreeKind5",
                1,
                BuildCollisionAuditData("SelfCheck_LooseQuadtreeKind5", kind5Frame));
            kind5Entity.Runtime.SetPosition(100, 0, 30);
            kind5Entity.Runtime.SyncIntegerPosition();
            kind5Entity.PS.dir = "right";
            Expect(BruteForceSceneQuery.TryBuildCollisionBroadphaseAabb(
                       kind5Entity,
                       kind5Frame,
                       out SpatialAabbXZ rightKind5Bounds) &&
                   rightKind5Bounds.Equals(new SpatialAabbXZ(60, 15, 80, 45)),
                "shadow broadphase bounds must include kind5 and default zwidth=15 from the collision snapshot");
            kind5Entity.PS.dir = "left";
            Expect(BruteForceSceneQuery.TryBuildCollisionBroadphaseAabb(
                       kind5Entity,
                       kind5Frame,
                       out SpatialAabbXZ leftKind5Bounds) &&
                   leftKind5Bounds.Equals(new SpatialAabbXZ(120, 15, 140, 45)),
                "shadow broadphase bounds must use the same facing flip and centerx formula as collision collection");
            Expect(!leftKind5Bounds.Overlaps(new SpatialAabbXZ(120, 45, 140, 46)) &&
                   leftKind5Bounds.Overlaps(new SpatialAabbXZ(120, 44, 140, 45)),
                "shadow zwidth bounds must reject exact boundary contact and retain a one-unit overlap");

            var diagnosticWorld = new SimulationWorld();
            InteractionArea diagnosticItr = MakeCollisionAuditItr(0, -20, -20, 40, 40, 20, 1);
            LF2Character diagnosticAttacker = CreateInteractionCharacter(
                "SelfCheck_LooseQuadtreeDiagnosticAttacker",
                1,
                BuildCollisionAuditData(
                    "SelfCheck_LooseQuadtreeDiagnosticAttacker",
                    BuildCollisionAuditFrame(0, LF2States.Standing, diagnosticItr, null)));
            LF2Character diagnosticTarget = CreateInteractionCharacter(
                "SelfCheck_LooseQuadtreeDiagnosticTarget",
                37,
                BuildCollisionAuditData(
                    "SelfCheck_LooseQuadtreeDiagnosticTarget",
                    BuildCollisionAuditFrame(
                        0,
                        LF2States.Standing,
                        null,
                        new BodyBox { kind = 0, x = -20, y = -20, w = 40, h = 40 })));
            RegisterCollisionAuditPair(diagnosticWorld, diagnosticAttacker, diagnosticTarget, 1, 2);
            LF2Character suppressedTarget = CreateInteractionCharacter(
                "SelfCheck_LooseQuadtreeSuppressedTarget",
                38,
                BuildCollisionAuditData(
                    "SelfCheck_LooseQuadtreeSuppressedTarget",
                    BuildCollisionAuditFrame(
                        0,
                        LF2States.Standing,
                        null,
                        new BodyBox { kind = 0, x = -20, y = -20, w = 40, h = 40 })));
            diagnosticWorld.Register(suppressedTarget);
            ConfigureCollisionAuditEntity(suppressedTarget, 2, 0);
            suppressedTarget.Runtime.SuppressCollisionCandidateUntilTick = 1;
            LF2Character pendingTarget = CreateInteractionCharacter(
                "SelfCheck_LooseQuadtreePendingTarget",
                39,
                BuildCollisionAuditData(
                    "SelfCheck_LooseQuadtreePendingTarget",
                    BuildCollisionAuditFrame(
                        0,
                        LF2States.Standing,
                        null,
                        new BodyBox { kind = 0, x = -20, y = -20, w = 40, h = 40 })));
            diagnosticWorld.Register(pendingTarget);
            ConfigureCollisionAuditEntity(pendingTarget, 2, 0);
            pendingTarget.Runtime.PendingFlushDestroy = true;
            var diagnosticQuery = diagnosticWorld.SceneQuery as BruteForceSceneQuery;
            Expect(diagnosticQuery != null && !diagnosticQuery.ShadowBroadphaseDiagnosticsEnabled,
                "production shadow broadphase diagnostics must default off");

            int attackerSlot = diagnosticAttacker.Runtime.SlotIndex;
            diagnosticTarget.ItrRest.SetVrest(attackerSlot, 2);
            uint rngBeforeOff = diagnosticWorld.Rng.State;
            ulong callsBeforeOff = diagnosticWorld.Rng.CallCount;
            diagnosticWorld.CaptureCollisionFrameSnapshotsAll();
            diagnosticWorld.TickCollisionPairVRestAll();
            diagnosticWorld.CollectCollisionCandidatesAll();
            Expect(diagnosticQuery.TryGetCollisionCandidateSequence(
                       diagnosticAttacker,
                       out List<SceneQueryHit> offCandidates) &&
                   offCandidates.Count == 0 &&
                   diagnosticTarget.ItrRest.GetVrest(attackerSlot) == 1 &&
                   diagnosticWorld.Rng.State == rngBeforeOff &&
                   diagnosticWorld.Rng.CallCount == callsBeforeOff &&
                   diagnosticQuery.ShadowBroadphaseDiagnostics.RebuildCount == 0,
                "diagnostics-off collection must preserve the authority candidate/RNG/VRest behavior without building the tree");
            diagnosticWorld.EndCollisionCandidateConsumption();

            diagnosticTarget.ItrRest.SetVrest(attackerSlot, 2);
            diagnosticQuery.ShadowBroadphaseDiagnosticsEnabled = true;
            uint rngBeforeOn = diagnosticWorld.Rng.State;
            ulong callsBeforeOn = diagnosticWorld.Rng.CallCount;
            diagnosticWorld.CaptureCollisionFrameSnapshotsAll();
            diagnosticWorld.TickCollisionPairVRestAll();
            diagnosticWorld.CollectCollisionCandidatesAll();
            SpatialBroadphaseDiagnostics diagnostics = diagnosticQuery.ShadowBroadphaseDiagnostics;
            Expect(diagnosticQuery.TryGetCollisionCandidateSequence(
                       diagnosticAttacker,
                       out List<SceneQueryHit> onCandidates) &&
                   onCandidates.Count == offCandidates.Count &&
                   diagnosticTarget.ItrRest.GetVrest(attackerSlot) == 1 &&
                   diagnosticWorld.Rng.State == rngBeforeOn &&
                   diagnosticWorld.Rng.CallCount == callsBeforeOn &&
                   diagnostics.RebuildCount == 1 &&
                   diagnostics.IndexedCount == 2 &&
                   diagnostics.BrutePairCount == 1 &&
                   diagnostics.QuadtreePairCount == 1 &&
                   diagnostics.MismatchCount == 0,
                "diagnostics-on shadow comparison must preserve candidate/RNG/VRest behavior, exclude suppressed/pending entities, and match the brute AABB set");
            diagnosticWorld.EndCollisionCandidateConsumption();

            diagnosticTarget.ItrRest.RemoveVrest(attackerSlot);
            diagnosticWorld.CaptureCollisionFrameSnapshotsAll();
            diagnosticWorld.TickCollisionPairVRestAll();
            diagnosticWorld.CollectCollisionCandidatesAll();
            Expect(diagnosticQuery.TryGetCollisionCandidateSequence(
                       diagnosticAttacker,
                       out List<SceneQueryHit> acceptedCandidates) &&
                   acceptedCandidates.Count == 1 &&
                   acceptedCandidates[0].Target == diagnosticTarget &&
                   diagnostics.AcceptedPairCount == 1 &&
                   diagnostics.MismatchCount == 0,
                "a real accepted collision pair must be represented by the shadow quadtree set");
            diagnosticWorld.EndCollisionCandidateConsumption();
        }

        private static List<long> CollectLooseQuadtreePairs(List<SpatialBroadphaseEntry> entries)
        {
            var tree = new LooseQuadtreeBroadphase();
            tree.Rebuild(entries, new SpatialAabbXZ(0, 180, 800, 350));
            var query = new List<int>(64);
            var pairs = new List<long>();
            for (int i = 0; i < entries.Count; i++)
            {
                SpatialBroadphaseEntry first = entries[i];
                tree.Query(first.Bounds, query);
                for (int q = 0; q < query.Count; q++)
                {
                    int j = query[q];
                    if (j <= i || j >= entries.Count)
                        continue;
                    SpatialBroadphaseEntry second = entries[j];
                    if (!first.Bounds.Overlaps(second.Bounds))
                        continue;
                    pairs.Add(SpatialPairKey(first.RuntimeSlot, second.RuntimeSlot));
                }
            }
            SortUniqueSpatialPairs(pairs);
            return pairs;
        }

        private static List<long> CollectSpatialBrutePairs(List<SpatialBroadphaseEntry> entries)
        {
            var pairs = new List<long>();
            for (int i = 0; i < entries.Count; i++)
            {
                for (int j = i + 1; j < entries.Count; j++)
                {
                    if (entries[i].Bounds.Overlaps(entries[j].Bounds))
                        pairs.Add(SpatialPairKey(entries[i].RuntimeSlot, entries[j].RuntimeSlot));
                }
            }
            SortUniqueSpatialPairs(pairs);
            return pairs;
        }

        private static long SpatialPairKey(int first, int second)
        {
            uint min = (uint)Math.Min(first, second);
            uint max = (uint)Math.Max(first, second);
            return ((long)min << 32) | max;
        }

        private static void SortUniqueSpatialPairs(List<long> pairs)
        {
            if (pairs.Count < 2)
                return;
            pairs.Sort();
            int write = 1;
            for (int read = 1; read < pairs.Count; read++)
            {
                if (pairs[read] == pairs[write - 1])
                    continue;
                pairs[write++] = pairs[read];
            }
            if (write < pairs.Count)
                pairs.RemoveRange(write, pairs.Count - write);
        }

        private static bool SpatialPairListsEqual(List<long> first, List<long> second)
        {
            if (first.Count != second.Count)
                return false;
            for (int i = 0; i < first.Count; i++)
            {
                if (first[i] != second[i])
                    return false;
            }
            return true;
        }

        private static void CheckCollisionPairVRestDecouplingContracts()
        {
            LF2CharacterData pairData = new LF2CharacterData
            {
                name = "SelfCheck_CollisionPairVRest",
                frames = new List<LF2FrameData>(),
            };
            var world = new SimulationWorld();
            var first = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var second = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var missingData = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var suppressed = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var pending = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var newbornBeforeCollect = new FlowSelfCheckEntity(LF2ObjectType.Character);
            LF2Entity[] entities = { first, second, missingData, suppressed, pending, newbornBeforeCollect };
            for (int slot = 0; slot < entities.Length; slot++)
            {
                entities[slot].SetRequiredRuntimeSlot(slot);
                if (!ReferenceEquals(entities[slot], missingData))
                    ((FlowSelfCheckEntity)entities[slot]).BindData($"PairVRest_{slot}", 30000 + slot, pairData);
                world.Register(entities[slot]);
            }

            suppressed.Runtime.SuppressCollisionCandidateUntilTick = 100;
            pending.Runtime.PendingFlushDestroy = true;
            int firstSlot = first.Runtime.SlotIndex;
            int secondSlot = second.Runtime.SlotIndex;
            int missingSlot = missingData.Runtime.SlotIndex;
            int suppressedSlot = suppressed.Runtime.SlotIndex;
            int pendingSlot = pending.Runtime.SlotIndex;
            int newbornSlot = newbornBeforeCollect.Runtime.SlotIndex;
            first.ItrRest.SetVrest(secondSlot, 2);
            second.ItrRest.SetVrest(firstSlot, 3);
            first.ItrRest.SetVrest(firstSlot, 4);
            first.ItrRest.SetVrest(missingSlot, 5);
            first.ItrRest.SetVrest(suppressedSlot, 2);
            suppressed.ItrRest.SetVrest(firstSlot, 2);
            first.ItrRest.SetVrest(pendingSlot, 2);
            first.ItrRest.SetVrest(newbornSlot, 2);

            world.CaptureCollisionFrameSnapshotsAll();
            world.TickCollisionPairVRestAll();
            Expect(first.ItrRest.GetVrest(secondSlot) == 1 &&
                   second.ItrRest.GetVrest(firstSlot) == 2 &&
                   first.ItrRest.GetVrest(firstSlot) == 4 &&
                   first.ItrRest.GetVrest(missingSlot) == 5 &&
                   first.ItrRest.GetVrest(suppressedSlot) == 1 &&
                   suppressed.ItrRest.GetVrest(firstSlot) == 1 &&
                   first.ItrRest.GetVrest(pendingSlot) == 2 &&
                   first.ItrRest.GetVrest(newbornSlot) == 1,
                "collision pair VRest pass must tick each eligible direction once, skip self/missing-data/pending pairs, and ignore candidate suppression");

            var released = new FlowSelfCheckEntity(LF2ObjectType.Character);
            released.SetRequiredRuntimeSlot(6);
            released.BindData("PairVRest_Released", 30006, pairData);
            world.Register(released);
            int releasedSlot = released.Runtime.SlotIndex;
            first.ItrRest.SetVrest(releasedSlot, 3);
            released.ItrRest.SetVrest(firstSlot, 4);
            world.Unregister(released);
            world.TickCollisionPairVRestAll();
            Expect(first.ItrRest.GetVrest(releasedSlot) == 3 &&
                   world.GetRawRestVrest(releasedSlot, firstSlot) == 4,
                "collision pair VRest pass must leave both directions unchanged when either slot was released before collection");

            var earlyWorld = new SimulationWorld();
            var earlyFirst = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var earlySecond = new FlowSelfCheckEntity(LF2ObjectType.Character);
            earlyFirst.SetRequiredRuntimeSlot(0);
            earlySecond.SetRequiredRuntimeSlot(1);
            earlyFirst.BindData("PairVRest_Early0", 30100, pairData);
            earlySecond.BindData("PairVRest_Early1", 30101, pairData);
            earlyWorld.Register(earlyFirst);
            earlyWorld.Register(earlySecond);
            earlyFirst.ItrRest.Arest = 2;
            earlyFirst.ItrRest.SetVrest(1, 2);
            earlyWorld.SetNeedClearInput(true);
            new NTSDBattleTickSystem(earlyWorld).RunReleaseTick(1);
            Expect(earlyFirst.ItrRest.Arest == 1 && earlyFirst.ItrRest.GetVrest(1) == 2,
                "NeedClearInput early return must occur after ARest tick but before collision pair VRest tick");

            var extendedWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            var extendedLow = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var extendedHigh = new FlowSelfCheckEntity(LF2ObjectType.Character);
            extendedLow.SetRequiredRuntimeSlot(1);
            extendedHigh.SetRequiredRuntimeSlot(700);
            extendedLow.BindData("PairVRest_ExtendedLow", 30200, pairData);
            extendedHigh.BindData("PairVRest_ExtendedHigh", 30201, pairData);
            extendedWorld.Register(extendedLow);
            extendedWorld.Register(extendedHigh);
            extendedHigh.ItrRest.SetVrest(1, 2);
            extendedLow.ItrRest.SetVrest(700, 3);
            extendedWorld.TickCollisionPairVRestAll();
            Expect(extendedWorld.RuntimeSlotCapacity == 768 &&
                   extendedHigh.ItrRest.GetVrest(1) == 1 &&
                   extendedLow.ItrRest.GetVrest(700) == 2,
                "extended collision pair VRest pass must address grown high slots in both directions");

            const int sparseCapacity = 65536;
            const int sparseHighSlot = 65000;
            var sparseWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, sparseCapacity);
            var sparseLow = new FlowSelfCheckEntity(LF2ObjectType.Character);
            var sparseHigh = new FlowSelfCheckEntity(LF2ObjectType.Character);
            sparseLow.SetRequiredRuntimeSlot(1);
            sparseHigh.SetRequiredRuntimeSlot(sparseHighSlot);
            sparseLow.BindData("PairVRest_SparseLow", 30300, pairData);
            sparseHigh.BindData("PairVRest_SparseHigh", 30301, pairData);
            sparseWorld.Register(sparseLow);
            sparseWorld.Register(sparseHigh);
            sparseLow.ItrRest.SetVrest(sparseHighSlot, 2);
            sparseHigh.ItrRest.SetVrest(1, 3);
            sparseWorld.TickCollisionPairVRestAll();
            Expect(sparseWorld.RuntimeSlotCapacity == sparseCapacity &&
                   sparseWorld.LastCollisionPairVRestEligibilityVisitCount == 2 &&
                   sparseLow.ItrRest.GetVrest(sparseHighSlot) == 1 &&
                   sparseHigh.ItrRest.GetVrest(1) == 2,
                "collision pair VRest eligibility scan must visit registered bucket items rather than every addressable slot in a sparse high-capacity world");
        }

        private static void CheckExtendedServiceBoundaryContracts()
        {
            var world = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            var holder = new FlowSelfCheckEntity(LF2ObjectType.Character);
            holder.SetRequiredRuntimeSlot(511);
            holder.ObjectId = 4;
            var attacker = new PhaseRoutingSelfCheckSpecialAttack();
            attacker.BindSource("SelfCheck_ExtendedHolder", 200, 0);
            attacker.SetRequiredRuntimeSlot(50);
            attacker.Runtime.HolderStableId = 511;
            world.Register(holder);
            world.Register(attacker);

            var resolveHolder = typeof(LF2SpecialAttack).GetMethod(
                "ResolveActiveHolder",
                System.Reflection.BindingFlags.Static |
                System.Reflection.BindingFlags.NonPublic);
            Expect(resolveHolder != null,
                "extended service boundary fixture must retain the special-attack holder resolver");
            LF2Entity resolvedHolder = resolveHolder.Invoke(null, new object[] { attacker }) as LF2Entity;
            Expect(ReferenceEquals(resolvedHolder, holder),
                "special-attack holder resolution must accept the final slot of an extended world");

            var karasu = new FlowSelfCheckEntity(LF2ObjectType.Other);
            karasu.SetRequiredRuntimeSlot(510);
            karasu.ObjectId = 209;
            world.Register(karasu);

            LF2CharacterData karasuData = new LF2CharacterData
            {
                name = "SelfCheck_Karasu209",
                frames = new List<LF2FrameData> { Frame(0, 10, 1, 0, 39, 79) },
            };
            var karasuWrapper = new LF2CharacterDataWrapper(209, karasuData);
            var karasuTypes = new Dictionary<int, int>
            {
                [209] = (int)LF2ObjectType.Other,
            };
            var karasuWrappers = new Dictionary<int, LF2CharacterDataWrapper>
            {
                [209] = karasuWrapper,
            };
            using (new TemporaryRuntimeObjectConfigs(karasuTypes, karasuWrappers))
            {
                var replaceKarasu = typeof(LF2SpecialAttack).GetMethod(
                    "ReplaceWithActiveKarasuData",
                    System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic);
                Expect(replaceKarasu != null,
                    "extended service boundary fixture must retain the Karasu replacement helper");
                replaceKarasu.Invoke(attacker, null);
            }

            Expect(attacker.ObjectId == 209,
                "Karasu replacement scan must include high runtime slots in an extended world");

            var transitionProbe = new FlowSelfCheckEntity(LF2ObjectType.Character);
            transitionProbe.SetRequiredRuntimeSlot(51);
            world.Register(transitionProbe);
            var countAvailable = typeof(LF2Entity).GetMethod(
                "CountAvailableTransitionEffectSlots",
                System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.NonPublic);
            Expect(countAvailable != null,
                "extended service boundary fixture must retain the transition-effect slot counter");
            int available = (int)countAvailable.Invoke(transitionProbe, null);
            Expect(available == 458,
                $"transition effect slot count must use the extended dynamic range; actual={available}");

            bool parityRejected = false;
            try
            {
                world.CaptureParityFrameSnapshot(0);
            }
            catch (InvalidOperationException)
            {
                parityRejected = true;
            }
            Expect(parityRejected,
                "fixed 400-slot parity snapshots must reject non-Authority400 worlds");

            var extendedAuthorityCapacityWorld =
                new SimulationWorld(BattleRuntimeProfile.DesktopExtended, SimulationWorld.AuthorityRuntimeSlotCapacity);
            bool extendedProfileParityRejected = false;
            try
            {
                extendedAuthorityCapacityWorld.CaptureParityFrameSnapshot(0);
            }
            catch (InvalidOperationException)
            {
                extendedProfileParityRejected = true;
            }
            Expect(extendedProfileParityRejected,
                "fixed 400-slot parity snapshots must reject an extended profile even when capacity is 400");

            var authorityWorld = new SimulationWorld();
            BattleParityFrameSnapshot authoritySnapshot = authorityWorld.CaptureParityFrameSnapshot(0);
            Expect(authoritySnapshot != null &&
                   authoritySnapshot.Schema == BattleParityFrameSnapshot.SchemaId &&
                   authoritySnapshot.Hashes != null &&
                   !string.IsNullOrEmpty(authoritySnapshot.Hashes.Slots),
                "Authority400 parity snapshots must retain the fixed 400-slot schema");
        }

        private static void CheckExtendedChecksumContracts()
        {
            var viewTable = new RuntimeSlotTable(1050, 20, 50);
            int viewPagesBefore = viewTable.MaterializedPageCount;
            RuntimeSlotTable.ReadOnlySlotView emptyHighView = viewTable.GetReadOnlyView(1049);
            Expect(!emptyHighView.Claimed && emptyHighView.Generation == 0 &&
                   emptyHighView.RawRuntime == null &&
                   viewTable.MaterializedPageCount == viewPagesBefore,
                "extended checksum slot views must inspect high unmaterialized slots without creating pages");

            var sparseRest = new RuntimeRestStore(65536);
            sparseRest.SetVRest(900, 700, 3);
            sparseRest.SetVRest(3, 1049, 5);
            sparseRest.SetARest(700, 4);
            sparseRest.SetARest(3, 2);
            RuntimeRestStore.DiagnosticSnapshot sparseFirst = sparseRest.CaptureSparseSnapshot();
            RuntimeRestStore.DiagnosticSnapshot sparseSecond = sparseRest.CaptureSparseSnapshot();
            Expect(sparseFirst.LogicalCapacity == 65536 &&
                   sparseFirst.VRestEntries.Count == 2 &&
                   sparseFirst.VRestEntries[0].VictimSlot == 3 &&
                   sparseFirst.VRestEntries[1].VictimSlot == 900 &&
                   BattleCanonicalJson.Sha256(System.Linq.Enumerable.ToArray(
                       System.Linq.Enumerable.Select(sparseFirst.VRestEntries, entry =>
                           new object[] { entry.VictimSlot, entry.AttackerSlot, entry.Value }))) ==
                   BattleCanonicalJson.Sha256(System.Linq.Enumerable.ToArray(
                       System.Linq.Enumerable.Select(sparseSecond.VRestEntries, entry =>
                           new object[] { entry.VictimSlot, entry.AttackerSlot, entry.Value }))),
                "extended checksum rest snapshots must be deterministic sparse entries despite unordered writes");

            var mobileWorld = new SimulationWorld(BattleRuntimeProfile.MobileExtended, 1050);
            var mobileHigh = new FlowSelfCheckEntity(LF2ObjectType.Character);
            mobileHigh.SetRequiredRuntimeSlot(1049);
            mobileWorld.Register(mobileHigh);
            int mobileSlotPagesBefore = GetPrivateRuntimeSlotTable(mobileWorld).MaterializedPageCount;
            int mobileRestPagesBefore = mobileWorld.RuntimeRestStoreForServices.MaterializedVRestPageCount;
            BattleExtendedChecksumSnapshot mobileFirst = mobileWorld.CaptureExtendedChecksumSnapshot(11);
            BattleExtendedChecksumSnapshot mobileSecond = mobileWorld.CaptureExtendedChecksumSnapshot(11);
            Expect(mobileFirst.Schema == BattleExtendedChecksumSnapshot.SchemaId &&
                   mobileFirst.Profile == nameof(BattleRuntimeProfile.MobileExtended) &&
                   mobileFirst.LogicalCapacity == 1050 && mobileFirst.ClaimedCount == 1 &&
                   mobileFirst.Hashes.Overall == mobileSecond.Hashes.Overall &&
                   mobileFirst.ToJson().Contains("\"runtimeSlot\":1049") &&
                   !mobileFirst.ToJson().Contains("full-row-major") &&
                   GetPrivateRuntimeSlotTable(mobileWorld).MaterializedPageCount == mobileSlotPagesBefore &&
                   mobileWorld.RuntimeRestStoreForServices.MaterializedVRestPageCount == mobileRestPagesBefore,
                "MobileExtended checksums must retain high slots, use sparse rest data, and not materialize or mutate capture state");

            mobileHigh.ItrRest.Arest = 6;
            mobileHigh.ItrRest.SetVrest(900, 7);
            BattleExtendedChecksumSnapshot mobileRested = mobileWorld.CaptureExtendedChecksumSnapshot(11);
            Expect(mobileRested.Hashes.ARest != mobileFirst.Hashes.ARest &&
                   mobileRested.Hashes.VRest != mobileFirst.Hashes.VRest &&
                   mobileRested.Hashes.Overall != mobileFirst.Hashes.Overall &&
                   mobileRested.ToJson().Contains("\"slot\":1049") &&
                   mobileRested.ToJson().Contains("\"victimSlot\":1049") &&
                   mobileRested.ToJson().Contains("\"attackerSlot\":900"),
                "Extended checksums must include high-slot ARest and high-victim/high-attacker VRest state");

            BattleExtendedChecksumSnapshot mobileBeforeRaw =
                mobileWorld.CaptureExtendedChecksumSnapshot(11);
            NTSDEntityRuntime highRawRuntime = mobileWorld.GetRawRuntimeSlotState(900);
            highRawRuntime.HP = 321;
            highRawRuntime.X = 44.5;
            highRawRuntime.Frame = 73;
            highRawRuntime.HolderStableId = 1049;
            BattleExtendedChecksumSnapshot mobileAfterRaw =
                mobileWorld.CaptureExtendedChecksumSnapshot(11);
            Expect(mobileAfterRaw.Hashes.Slots != mobileBeforeRaw.Hashes.Slots &&
                   mobileAfterRaw.Hashes.Overall != mobileBeforeRaw.Hashes.Overall,
                "Extended checksums must project materialized unclaimed raw runtime state");

            var desktopWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            var desktopHigh = new FlowSelfCheckEntity(LF2ObjectType.Character);
            desktopHigh.SetRequiredRuntimeSlot(700);
            desktopHigh.Runtime.StableId = 7001;
            desktopWorld.Register(desktopHigh);
            BattleExtendedChecksumSnapshot desktopFirst = desktopWorld.CaptureExtendedChecksumSnapshot(11);
            Expect(desktopFirst.LogicalCapacity == 768 &&
                   desktopFirst.ToJson().Contains("\"runtimeSlot\":700"),
                "DesktopExtended checksums must follow runtime capacity growth and retain slot 700");

            var sameCapacityDesktop = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 1050);
            var sameCapacityDesktopHigh = new FlowSelfCheckEntity(LF2ObjectType.Character);
            sameCapacityDesktopHigh.SetRequiredRuntimeSlot(1049);
            sameCapacityDesktop.Register(sameCapacityDesktopHigh);
            BattleExtendedChecksumSnapshot sameCapacityDesktopSnapshot =
                sameCapacityDesktop.CaptureExtendedChecksumSnapshot(11);
            Expect(mobileFirst.Hashes.Overall != sameCapacityDesktopSnapshot.Hashes.Overall,
                "extended checksum metadata must separate otherwise equal-capacity runtime profiles");

            string beforeReuseSlots = desktopFirst.Hashes.Slots;
            desktopWorld.Unregister(desktopHigh);
            var desktopReplacement = new FlowSelfCheckEntity(LF2ObjectType.Character);
            desktopReplacement.SetRequiredRuntimeSlot(700);
            desktopReplacement.Runtime.StableId = 7001;
            desktopWorld.Register(desktopReplacement);
            BattleExtendedChecksumSnapshot desktopReused = desktopWorld.CaptureExtendedChecksumSnapshot(11);
            Expect(desktopReused.Hashes.Slots != beforeReuseSlots &&
                   desktopReused.ToJson().Contains("\"generation\":") &&
                   desktopReused.ToJson().Contains("\"stableId\":7001"),
                "extended slot checksums must change on pure generation reuse with the same stable id and runtime body");

            bool rejectedUnboundRest = false;
            mobileHigh.ItrRest.Unbind(false);
            try
            {
                mobileWorld.CaptureExtendedChecksumSnapshot(11);
            }
            catch (InvalidOperationException)
            {
                rejectedUnboundRest = true;
            }
            Expect(rejectedUnboundRest,
                "Extended checksum capture must reject a claimed entity that is not bound to the current rest store");

            var authorityWorld = new SimulationWorld();
            IBattleChecksumSnapshot authorityChecksum =
                SimulationTickDriver.CaptureSupportedChecksumSnapshot(
                    authorityWorld,
                    11,
                    FrameInputSet.Empty(11));
            Expect(authorityChecksum is BattleParityFrameSnapshot &&
                   authorityChecksum.Schema == BattleParityFrameSnapshot.SchemaId &&
                   mobileRested.Schema == BattleExtendedChecksumSnapshot.SchemaId &&
                   mobileRested.ToJson().Contains("\"schema\":\"ntsd-unity-extended-battle-checksum-v1\"") &&
                   SimulationTickDriver.CaptureSupportedFrameSnapshot(
                       mobileWorld,
                       11,
                       FrameInputSet.Empty(11)) == null &&
                   SimulationTickDriver.SupportsFrameChecksum(mobileWorld) &&
                   !SimulationTickDriver.SupportsAuthorityFrameChecksum(mobileWorld),
                "driver checksum APIs must retain Authority v3 snapshots while publishing Extended checksums through the general path only");
        }

        private static RuntimeSlotTable GetPrivateRuntimeSlotTable(SimulationWorld world)
        {
            var field = typeof(SimulationWorld).GetField(
                "_runtimeSlots",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            return field?.GetValue(world) as RuntimeSlotTable;
        }

        private static void CheckParityTraceInfrastructure()
        {
            var defaultRuntime = new NTSDEntityRuntime();
            defaultRuntime.Reset();
            Expect(defaultRuntime.HolderCopySlotIndex == 99 &&
                   Nearly(defaultRuntime.KnockbackVx, 0.1) &&
                   Nearly(defaultRuntime.KnockbackVy, 0.1) &&
                   Nearly(defaultRuntime.KnockbackVz, 0.1) &&
                   defaultRuntime.Blink == 0 &&
                   defaultRuntime.TransientMp == 0 &&
                   defaultRuntime.TransientMp2 == 1000 &&
                   defaultRuntime.TransientMp3 == 1000 &&
                   defaultRuntime.TransientMp4 == 1000,
                "parity runtime reset must preserve authority holder/knockback/blink/transient defaults");

            var rng = new DeterministicRng(0x12345678u);
            Expect(rng.State == 0x12345678u && rng.CallCount == 0,
                "parity RNG must expose its seeded state with a zero call count");
            uint expectedState = unchecked(0x12345678u * 0x343FDu + 0x269EC3u);
            int expectedRaw = (int)((expectedState >> 16) & 0x7FFFu);
            Expect(rng.NextRaw() == expectedRaw && rng.State == expectedState && rng.CallCount == 1,
                "parity RNG state/call count must advance with NextRaw");
            rng.Seed(0x12345678u);
            Expect(rng.State == 0x12345678u && rng.CallCount == 0,
                "parity RNG Seed must reset CallCount for replay bootstrap");

            var canonicalA = new Dictionary<string, object>
            {
                ["z"] = 2,
                ["a"] = 1,
            };
            var canonicalB = new Dictionary<string, object>
            {
                ["a"] = 1,
                ["z"] = 2,
            };
            string canonicalHash = BattleCanonicalJson.Sha256(canonicalA);
            Expect(canonicalHash == BattleCanonicalJson.Sha256(canonicalB),
                "canonical parity hash must not depend on dictionary insertion order");
            canonicalB["z"] = 3;
            Expect(canonicalHash != BattleCanonicalJson.Sha256(canonicalB),
                "canonical parity hash must be sensitive to field changes");
            Expect(SimulationWorld.NormalizeTraceAssetCue(" ./DATA//sound/003.WAV ") == "003.wav",
                "parity event cue projection must normalize slash paths to a lowercase basename");
            Expect(SimulationWorld.NormalizeTraceAssetCue(@"data\sound\004.wav") == "004.wav",
                "parity event cue projection must normalize backslash paths to a basename");
            Expect(SimulationWorld.NormalizeTraceAssetCue("data/snddata_005.WAV") == "005.wav",
                "parity event cue projection must remove the canonical snddata_ filename prefix");

            Dictionary<int, FrameInputSet> denseTraceInputs = FrameInputSet.BuildDenseTraceTimeline(
                4,
                new[] { 2, 0 },
                new[]
                {
                    new FrameInputSet(2, new[]
                    {
                        new SimulationPlayerInput(0, SimulationInputButtons.Left),
                        new SimulationPlayerInput(2, SimulationInputButtons.Attack),
                    }),
                    new FrameInputSet(3, new[]
                    {
                        new SimulationPlayerInput(0, SimulationInputButtons.None),
                    }),
                    new FrameInputSet(4, new[]
                    {
                        new SimulationPlayerInput(7, SimulationInputButtons.Defend),
                    }),
                });
            Expect(denseTraceInputs.Count == 4 &&
                   denseTraceInputs[1].Players.Count == 2 &&
                   denseTraceInputs[1].Players[0].PlayerSlot == 0 &&
                   denseTraceInputs[1].Players[0].Buttons == SimulationInputButtons.None &&
                   denseTraceInputs[1].Players[1].PlayerSlot == 2 &&
                   denseTraceInputs[1].Players[1].Buttons == SimulationInputButtons.None,
                "dense trace input must emit every active human in player-slot order from tick one");
            Expect(denseTraceInputs[2].Players[0].Buttons == SimulationInputButtons.Left &&
                   denseTraceInputs[2].Players[1].Buttons == SimulationInputButtons.Attack &&
                   denseTraceInputs[3].Players[0].Buttons == SimulationInputButtons.None &&
                   denseTraceInputs[3].Players[1].Buttons == SimulationInputButtons.Attack &&
                   denseTraceInputs[4].Players[0].Buttons == SimulationInputButtons.None &&
                   denseTraceInputs[4].Players[1].Buttons == SimulationInputButtons.Attack,
                "dense trace input must carry held masks, preserve explicit releases, and ignore inactive players");

            LF2CharacterData data = new LF2CharacterData
            {
                name = "SelfCheck_ParityInput",
                frames = new List<LF2FrameData>
                {
                    new LF2FrameData
                    {
                        frameId = 0,
                        frameName = "self_check_parity_input",
                        state = 0,
                        wait = 10,
                        next = 0,
                    },
                    Frame(
                        LF2StandardFrames.WalkingStart,
                        LF2States.Walking,
                        10,
                        LF2StandardFrames.WalkingStart,
                        39,
                        79),
                    Frame(
                        LF2StandardFrames.RunningStart,
                        LF2States.Running,
                        10,
                        LF2StandardFrames.RunningStart,
                        39,
                        79),
                    Frame(
                        LF2StandardFrames.Running1,
                        LF2States.Running,
                        10,
                        LF2StandardFrames.Running1,
                        39,
                        79),
                    Frame(
                        LF2StandardFrames.RunningEnd,
                        LF2States.Running,
                        10,
                        LF2StandardFrames.RunningEnd,
                        39,
                        79),
                },
            };
            LF2Character character = CreateCharacter("SelfCheck_ParityInput", 2, data);
            character.Team = 1;
            var world = new SimulationWorld();
            BattleSlotRuntimeState rosterSlot = world.Runtime.Roster.Slots[0];
            rosterSlot.Active = true;
            rosterSlot.IsHuman = true;
            rosterSlot.CharacterId = 2;
            rosterSlot.Team = 1;
            world.Runtime.Roster.ActiveSlotCount = 1;
            world.Register(character);

            var heldTickSystem = new NTSDBattleTickSystem(world);
            for (int tick = 1; tick <= 6; tick++)
            {
                world.ApplyFrameInputSet(new FrameInputSet(tick, new[]
                {
                    new SimulationPlayerInput(
                        0,
                        SimulationInputButtons.Left),
                }));
                heldTickSystem.RunReleaseTick(tick);

                if (tick == 2)
                {
                    Expect(character.Runtime.KeyLeft == 0,
                        $"C# authority frame-advance boundary must clear tick2 current left; " +
                        $"keyLeft={character.Runtime.KeyLeft},frame={character.Frame.N}");
                    Expect(character.Frame.N == LF2StandardFrames.WalkingStart &&
                           character.Runtime.Dir == "left",
                        $"tick2 CharacterInput must consume left before the C# authority clear boundary; " +
                        $"frame={character.Frame.N},dir={character.Runtime.Dir}");
                }

                if (tick == 3)
                {
                    Expect(character.Runtime.KeyLeft == 0 && character.Runtime.PrevLeft == 0 &&
                           character.Runtime.CdLeft == 5 &&
                           character.Runtime.InputHistory[3] == 4 &&
                           character.Runtime.InputHistory[4] == 4 &&
                           character.Runtime.InputHistory[5] == 4,
                        $"complete held packet tick3 must rebuild the C# authority edge; " +
                        $"keyLeft={character.Runtime.KeyLeft},prevLeft={character.Runtime.PrevLeft}," +
                        $"cdLeft={character.Runtime.CdLeft}," +
                        $"history={string.Join(",", character.Runtime.InputHistory)}");
                }
            }
            Expect(rosterSlot.RuntimeSlotIndex == character.Runtime.SlotIndex,
                "frame input must bind the roster player to the resolved fixed runtime slot");
            Expect(character.Runtime.KeyLeft == 0 && character.Runtime.PrevLeft == 0 &&
                   character.Runtime.CdLeft == 5 &&
                   character.Runtime.InputHistory[1] == 4 &&
                   character.Runtime.InputHistory[2] == 4 &&
                   character.Runtime.InputHistory[3] == 4 &&
                   character.Runtime.InputHistory[4] == 4 &&
                   character.Runtime.InputHistory[5] == 4,
                $"six complete held-left packets must repeat the C# authority edge/history; " +
                $"keyLeft={character.Runtime.KeyLeft},prevLeft={character.Runtime.PrevLeft}," +
                $"cdLeft={character.Runtime.CdLeft}," +
                $"history={string.Join(",", character.Runtime.InputHistory)}");

            LF2Character sparseLocal = CreateCharacter("SelfCheck_ParitySparseLocal", 3, data);
            ((SelfCheckController)sparseLocal.Controller).InputBuffer.EnqueueForTick(1, FuncKeyMask.left, true);
            sparseLocal.RunHumanInputPollPhase(1);
            int[] sparseHistory = (int[])sparseLocal.Runtime.InputHistory.Clone();
            var sparseWorld = new SimulationWorld();
            sparseWorld.Register(sparseLocal);
            sparseWorld.SerialTickAll(1);
            Expect(sparseLocal.Runtime.KeyLeft == 0,
                "C# authority frame-advance boundary must clear sparse tick1 runtime left");
            sparseLocal.RunHumanInputPollPhase(2);
            Expect(sparseLocal.Runtime.KeyLeft == 1 && sparseLocal.Runtime.PrevLeft == 1 &&
                   sparseLocal.Runtime.CdLeft == 4 &&
                   System.Linq.Enumerable.SequenceEqual(sparseHistory, sparseLocal.Runtime.InputHistory),
                "sparse local event input must retain held state without manufacturing a repeated edge");

            world.AdvanceBattleFlowTick(3);
            rosterSlot.RuntimeSlotIndex = -1;
            rosterSlot.StableId = -1;
            character.AttackingCounter = 37;
            BattleParityFrameSnapshot first = world.CaptureParityFrameSnapshot(
                3,
                FrameInputSet.Empty(3));
            BattleParityFrameSnapshot second = world.CaptureParityFrameSnapshot(
                3,
                FrameInputSet.Empty(3));
            Expect(first.Hashes.Overall == second.Hashes.Overall &&
                   first.Hashes.ARest == "2e37abc158da57c53691211785eceb5b1a93f0d0f6f06bfeca854cbabdd11cfa" &&
                   first.Hashes.Events == "ea70093faeca028415dc3a0ab08d57702700f4941b5cdd279fe6f709106888c4",
                "parity snapshot hashes must be deterministic and use canonical empty rest/event domains");
            Expect(rosterSlot.RuntimeSlotIndex == -1 && rosterSlot.StableId == -1,
                "parity snapshot capture must not repair or mutate roster bindings");
            Expect(first.SlotCommitments.Length == 400 &&
                   first.SlotCommitments[character.Runtime.SlotIndex] ==
                       BattleCanonicalJson.Sha256(first.AllSlotsDomain[character.Runtime.SlotIndex]),
                "v3 parity snapshot must bind every slot body to its canonical commitment");
            Expect(first.CompactSlotsDomain.Length == 1 &&
                   !first.ToJson().Contains("\"runtimeSlot\":399"),
                "compact parity JSON must omit reset-equivalent fixed runtime slots");
            Expect(first.ToJson().Contains("\"attacking\":37"),
                "parity slot schema must capture the real runtime AttackingCounter field");

            string slotsBefore = first.Hashes.Slots;
            character.Runtime.X += 1.0;
            character.Runtime.SyncIntegerPosition();
            BattleParityFrameSnapshot moved = world.CaptureParityFrameSnapshot(
                3,
                FrameInputSet.Empty(3));
            Expect(moved.Hashes.Slots != slotsBefore,
                "slot domain hash must change when a fixed-slot runtime changes");

            character.ItrRest.Arest = 4;
            character.ItrRest.SetVrest(1, 6);
            BattleParityFrameSnapshot rested = world.CaptureParityFrameSnapshot(
                3,
                FrameInputSet.Empty(3));
            Expect(rested.Hashes.ARest != first.Hashes.ARest &&
                   rested.Hashes.VRest != first.Hashes.VRest,
                "arest/vrest domain hashes must be sensitive to sparse cooldown state");
            Expect(rested.ToJson().Contains("\"attackerSlot\":0,\"value\":6,\"victimSlot\":1"),
                "v3 vrest projection must preserve authority matrix byte order");

            character.Runtime.XBoundPositive = true;
            character.Runtime.XBoundNegative = true;
            character.Runtime.ZBoundPositive = true;
            character.Runtime.ZBoundNegative = true;
            character.Runtime.RenderPicOffset = 318;
            character.Runtime.WeaponFlightCounter = 31;
            character.Runtime.TransformOriginalObjectId = 324;
            character.Runtime.TransformTargetObjectId = 33;
            character.Runtime.OwnerStableId = 77;
            character.Runtime.RelationTeam = 88;
            character.Runtime.ReleaseTick = 99;
            string activeProjectionJson = world.CaptureParityFrameSnapshot(
                3,
                FrameInputSet.Empty(3)).ToJson();
            Expect(activeProjectionJson.Contains("\"blockBackZ\":1") &&
                   activeProjectionJson.Contains("\"blockFwdZ\":1") &&
                   activeProjectionJson.Contains("\"blockLeft\":1") &&
                   activeProjectionJson.Contains("\"blockRight\":1") &&
                   activeProjectionJson.Contains("\"unk318\":318") &&
                   activeProjectionJson.Contains("\"unk31C\":31") &&
                   activeProjectionJson.Contains("\"unk324\":324") &&
                   activeProjectionJson.Contains("\"unk33C\":33") &&
                   activeProjectionJson.Contains("\"ownerId\":77") &&
                   activeProjectionJson.Contains("\"unk364\":88") &&
                   activeProjectionJson.Contains("\"releaseTick\":99"),
                "BATTLE-AUDIT7-T1: active slot parity projection must serialize real block, Unk, owner, relation and release fields");

            world.Unregister(character);
            BattleParityFrameSnapshot inactiveRested = world.CaptureParityFrameSnapshot(
                3,
                FrameInputSet.Empty(3));
            Expect(inactiveRested.SlotCommitments.Length == 400 &&
                   inactiveRested.Hashes.ARest == rested.Hashes.ARest &&
                   inactiveRested.Hashes.VRest == rested.Hashes.VRest,
                "BATTLE-AUDIT7-T1/F5: full 400-slot parity rest domains must retain inactive raw-slot ARest/VRest state");
        }

        private static void CheckReferencePoolObjectIdPreserved()
        {
            LF2ReferencePool pool = LF2ReferencePool.Instance;
            Expect(pool != null, "reference pool identity fixture requires an LF2ReferencePool singleton");

            const int requestedObjectId = 407;
            ILF2Object obj = pool.Get(LF2ObjectType.Character, requestedObjectId);
            try
            {
                Expect(obj != null && obj.ObjectId == requestedObjectId,
                    $"reference pool Get must preserve requested ObjectId after Reset; actual={obj?.ObjectId ?? -1}");
            }
            finally
            {
                obj?.Reset();
                pool.Release(obj);
            }
        }

        private static void CheckReferencePoolRejectsUnownedObjects()
        {
            LF2ReferencePool pool = LF2ReferencePool.Instance;
            Expect(pool != null, "reference-pool ownership regression requires the production singleton");

            int availableBefore = pool.GetAvailableCount(LF2ObjectType.SpecialAttack);
            var unowned = new FlowSelfCheckEntity(LF2ObjectType.SpecialAttack);
            pool.Release(unowned);
            Expect(pool.GetAvailableCount(LF2ObjectType.SpecialAttack) == availableBefore,
                "releasing an object that was never borrowed must not contaminate the SpecialAttack pool");

            ILF2Object borrowed = pool.Get(LF2ObjectType.SpecialAttack, 205);
            Expect(borrowed is LF2SpecialAttack,
                $"SpecialAttack pool must return LF2SpecialAttack, actual={borrowed?.GetType().Name ?? "null"}");
            pool.Release(borrowed);
        }

        private static void CheckObjectPoolReleaseEscapesExternalParent()
        {
            using var initialization = new TemporaryObjectPoolInitialization();
            LF2ObjectPool pool = LF2ObjectPool.Instance;
            using var isolatedState = new TemporaryIsolatedObjectPoolState(pool);
            GameObject externalParent = new GameObject("SelfCheck_ObjectPoolExternalParent");
            LF2ObjectRenderer borrowedRenderer = null;

            try
            {
                GameObject borrowedRoot = pool.Get(out borrowedRenderer);
                Expect(borrowedRoot != null && borrowedRenderer != null,
                    "object-pool external-parent regression requires a borrowed production renderer");

                borrowedRoot.transform.SetParent(externalParent.transform, true);
                borrowedRoot.transform.localPosition = new Vector3(7f, 8f, 9f);
                borrowedRoot.transform.localRotation = Quaternion.Euler(10f, 20f, 30f);
                pool.Release(borrowedRenderer);
                borrowedRenderer = null;

                Expect(borrowedRoot.transform.parent == pool.transform &&
                       borrowedRoot.transform.localPosition == Vector3.zero &&
                       borrowedRoot.transform.localRotation == Quaternion.identity &&
                       !borrowedRoot.activeSelf &&
                       pool.AvailableObjectCountForAcceptance == 1 &&
                       pool.ActiveObjectCountForAcceptance == 0,
                    "released pool root must escape an external parent and return normalized to the available pool");

                UnityEngine.Object.DestroyImmediate(externalParent);
                externalParent = null;

                GameObject reusedRoot = pool.Get(out borrowedRenderer);
                Expect(reusedRoot != null && ReferenceEquals(reusedRoot, borrowedRoot) &&
                       reusedRoot.transform.parent == pool.transform && reusedRoot.activeSelf,
                    "destroying the prior external parent must not destroy an available pooled root");
            }
            finally
            {
                if (borrowedRenderer != null)
                    pool.Release(borrowedRenderer);
                if (externalParent != null)
                    UnityEngine.Object.DestroyImmediate(externalParent);
            }
        }

        private static void CheckCharacterGroundMovementUsesIntegerSnapshot()
        {
            var data = new LF2CharacterData
            {
                name = "SelfCheck_IntegerGroundMovement",
                walking_speed = 4f,
                walking_speedz = 2f,
                walking_frame_rate = 1,
                frames = new List<LF2FrameData>
                {
                    Frame(0, LF2States.Standing, 1, 0, 39, 79),
                    Frame(5, LF2States.Walking, 1, 5, 39, 79),
                },
            };

            LF2Character character = CreateCharacter("SelfCheck_IntegerGroundMovement", 1, data);
            character.Runtime.KeyRight = 1;
            character.Runtime.Y = -0.5;
            character.Runtime.YInt = 0;
            character.Runtime.Vx = 0.0;

            character.ApplyWalkRunFrameInternal(heavy: false);
            Expect(System.Math.Abs(character.Runtime.Vx - 4.0) <= 1e-12,
                $"walking ground gate must use YInt==0 when Y is fractional; actual Vx={character.Runtime.Vx:R}");

            character.Runtime.KeyRight = 0;
            character.Runtime.KeyUp = 1;
            const double initialVx = 123456789.125;
            character.Runtime.Vx = initialVx;
            character.ApplyRunLaneInternal(3f);
            double expectedVx = initialVx * (5.0 / 6.0);
            Expect(System.Math.Abs(character.Runtime.Vx - expectedVx) <= 1e-9,
                $"running lane factor must preserve double 5/6 precision; actual={character.Runtime.Vx:R}, expected={expectedVx:R}");

            CheckSharedCharacterDatGroundMovementUsesIntegerSnapshot();
        }

        private static void CheckLocalFreeRunUsesSingleTickHostPacing()
        {
            var local = new LockstepSimulationSettings
            {
                driveMode = SimulationDriveMode.LocalFreeRun,
                maxCatchUpTicksPerFrame = 1,
                maxBacklogTicks = 1,
            };
            local.Normalize();

            Expect(local.maxCatchUpTicksPerFrame == LockstepSimulationSettings.DefaultMaxTicksPerFrame &&
                   local.maxBacklogTicks >= local.maxCatchUpTicksPerFrame,
                "local free-run must preserve one-tick host pacing instead of forcing four complete battle ticks into one Unity Update");

            var explicitThroughput = new LockstepSimulationSettings
            {
                driveMode = SimulationDriveMode.LocalFreeRun,
                maxCatchUpTicksPerFrame = 4,
                maxBacklogTicks = 8,
            };
            explicitThroughput.Normalize();

            Expect(explicitThroughput.maxCatchUpTicksPerFrame == 4,
                "local free-run must retain an explicitly configured multi-tick throughput diagnostic");

            var buffered = new LockstepSimulationSettings
            {
                driveMode = SimulationDriveMode.LockstepBuffered,
                maxCatchUpTicksPerFrame = 1,
                maxBacklogTicks = 1,
            };
            buffered.Normalize();

            Expect(buffered.maxCatchUpTicksPerFrame == 1,
                "lockstep-buffered mode must preserve its explicitly configured one-tick host pacing");
        }

        private static void CheckBufferedHumanInputSemantics()
        {
            CheckMappedAction(
                "AttackAction/J",
                (input, pressed) => input.SetAttackActionPressed(pressed),
                expectedKeyJump: 1,
                expectedKeyDefend: 0,
                expectedKeyAttack: 0,
                expectedCooldown: runtime => runtime.CdAttack,
                expectedFrame: character => character.Frame.N == LF2StandardFrames.Punch ||
                                            character.Frame.N == LF2StandardFrames.Punch4);

            CheckMappedAction(
                "JumpAction/K",
                (input, pressed) => input.SetJumpActionPressed(pressed),
                expectedKeyJump: 0,
                expectedKeyDefend: 1,
                expectedKeyAttack: 0,
                expectedCooldown: runtime => runtime.CdJump,
                expectedFrame: character => character.Frame.N == LF2StandardFrames.Jumping);

            CheckMappedAction(
                "DefendAction/L",
                (input, pressed) => input.SetDefendActionPressed(pressed),
                expectedKeyJump: 0,
                expectedKeyDefend: 0,
                expectedKeyAttack: 1,
                expectedCooldown: runtime => runtime.CdDefend,
                expectedFrame: character => character.Frame.N == LF2StandardFrames.Defend);

            CheckBufferedActionCombination();
            CheckBufferedDirectionReversal();
            CheckFrameSnapshotHumanInputPolling();
        }

        private static void CheckRecordedInputAlignmentContracts()
        {
            LF2FrameData velocityFrame = Frame(20, LF2States.Attack, 1, 20, 39, 79);
            velocityFrame.dvy = 2;
            var data = new LF2CharacterData
            {
                name = "SelfCheck_InputAlignmentContracts",
                running_speedz = 3f,
                dash_distance = 10f,
                dash_height = -4f,
                frames = new List<LF2FrameData>
                {
                    Frame(0, LF2States.Standing, 1, 0, 39, 79),
                    Frame(10, LF2States.DeepSpecific, 1, 10, 39, 79),
                    Frame(11, LF2States.FirenSpecific, 1, 11, 39, 79),
                    velocityFrame,
                    Frame(LF2StandardFrames.SuperPunch, LF2States.Attack, 1, LF2StandardFrames.SuperPunch, 39, 79),
                    Frame(LF2StandardFrames.JumpAttack, LF2States.Attack, 1, LF2StandardFrames.JumpAttack, 39, 79),
                    Frame(LF2StandardFrames.DashAttack, LF2States.Attack, 1, LF2StandardFrames.DashAttack, 39, 79),
                    Frame(LF2StandardFrames.Defend, LF2States.Defending, 1, LF2StandardFrames.Defend, 39, 79),
                    Frame(LF2StandardFrames.JumpingAir, LF2States.Jump, 1, LF2StandardFrames.JumpingAir, 39, 79),
                    Frame(LF2StandardFrames.DashForward, LF2States.Dash, 1, LF2StandardFrames.DashForward, 39, 79),
                },
            };

            LF2Character character = CreateCharacter("SelfCheck_InputAlignment", 1, data);

            character.ImmediateFrame(LF2StandardFrames.Defend);
            character.Runtime.Vx = 7.0;
            character.Runtime.Vz = 5.0;
            character.ProcessReleaseInput();
            Expect(character.Frame.N == LF2StandardFrames.Defend &&
                   Nearly(character.Runtime.Vx, 7.0) && Nearly(character.Runtime.Vz, 5.0),
                "INPUT-1: state 7 must not be dispatched through release input");

            character.ImmediateFrame(LF2StandardFrames.JumpingAir);
            character.Runtime.Y = -0.5;
            character.Runtime.YInt = 0;
            character.Runtime.KeyJump = 1;
            character.AttackingCounter = 7;
            character.ProcessReleaseInput();
            Expect(character.Frame.N == LF2StandardFrames.JumpingAir && character.AttackingCounter == 7,
                "INPUT-2: jump input gate must use YInt and reject fractional Y when YInt is grounded");

            character.Runtime.YInt = -1;
            character.ProcessReleaseInput();
            Expect(character.Frame.N == LF2StandardFrames.JumpAttack && character.AttackingCounter == 0,
                "INPUT-2/7: airborne jump attack must run and retain its explicit attacking reset");

            character.ImmediateFrame(10);
            character.Runtime.Y = -0.5;
            character.Runtime.YInt = 0;
            character.Runtime.KeyJump = 0;
            character.Runtime.KeyUp = 1;
            character.Runtime.Vz = 0.0;
            character.ProcessReleaseInput();
            Expect(Nearly(character.Runtime.Vz, -3.0),
                "INPUT-3: state 301/19 lane input must use the grounded YInt snapshot");

            character.ImmediateFrame(11);
            character.Runtime.KeyUp = 0;
            character.Runtime.KeyDown = 1;
            character.Runtime.Vz = 0.0;
            character.ProcessReleaseInput();
            Expect(Nearly(character.Runtime.Vz, 3.0),
                "INPUT-3: state 19 lane input must share the grounded YInt gate");

            character.ImmediateFrame(0);
            character.Runtime.KeyUp = 0;
            character.Runtime.KeyDown = 0;
            character.Runtime.KeyJump = 1;
            character.Runtime.CdAttack = 5;
            character.HitConfirmEa = 3;
            character.ProcessReleaseInput();
            Expect(character.Frame.N == LF2StandardFrames.SuperPunch && character.HitConfirmEa == 3,
                "INPUT-6: Super Punch selection must not consume HitConfirm early");

            character.ImmediateFrame(LF2StandardFrames.DashForward);
            character.Runtime.KeyJump = 1;
            character.Runtime.CdAttack = 0;
            character.Runtime.Dir = "right";
            character.Runtime.Vx = 8.0;
            character.AttackingCounter = 9;
            character.ProcessReleaseInput();
            Expect(character.Frame.N == LF2StandardFrames.DashAttack && character.AttackingCounter == 9,
                "INPUT-7: raw input frame writes must preserve attacking when the source branch does not clear it");

            character.Frame.PN = 777;
            character.Trans.SyncDirectFrameData(character.Frame.D.wait, character.Frame.D.next, 13);
            character.SetInputFrameDirectInternal(LF2StandardFrames.DashAttack);
            Expect(character.Frame.PN == 777 && character.Trans.WaitCounter == 13,
                "INPUT-7: raw input frame writes must preserve PrevFrame/PN and the frame wait counter");

            LF2Character human = CreateCharacter("SelfCheck_InputVelocityHuman", 2, data);
            human.ImmediateFrame(20);
            human.Runtime.Vy = 0.0;
            human.RunPostCooldownInputPhase(1);
            Expect(Nearly(human.Runtime.Vy, 2.0),
                "INPUT-4: human post-cooldown input must apply the frame velocity tail exactly once");

            LF2Character ai = CreateCharacter("SelfCheck_InputVelocityAi", 3, data);
            ai.ImmediateFrame(20);
            ai.AiControlled = true;
            ai.Runtime.Vy = 0.0;
            ai.RunPostCooldownInputPhase(2);
            Expect(Nearly(ai.Runtime.Vy, 2.0),
                "INPUT-4: AI post-cooldown input must apply the frame velocity tail exactly once");

            LF2Character lockOwner = CreateCharacter("SelfCheck_RuntimeDefendLock", 4, data);
            lockOwner.Runtime.CdDefendLock = 7;
            lockOwner.InputState.SyncFromRuntime(lockOwner.Runtime);
            lockOwner.Runtime.CdDefendLock = 3;
            var world = new SimulationWorld();
            world.Register(lockOwner);
            world.VrestTickAll(1);
            lockOwner.RunPostCooldownInputPhase(1);
            Expect(lockOwner.Runtime.CdDefendLock == 2,
                "INPUT-5: Runtime must be the sole defend-lock truth and decrement it once per tick");

            CheckSharedCharacterDatInputAlignmentContracts();
            CheckLocomotionSingleAdvanceAndMoveRawWriteContracts();
        }

        private static void CheckLocomotionSingleAdvanceAndMoveRawWriteContracts()
        {
            var data = new LF2CharacterData
            {
                name = "SelfCheck_LocomotionSingleAdvance",
                walking_speed = 4f,
                walking_speedz = 2f,
                walking_frame_rate = 1,
                running_speed = 8f,
                running_speedz = 3f,
                running_frame_rate = 1,
                frames = new List<LF2FrameData>
                {
                    Frame(0, LF2States.Standing, 0, 0, 39, 79),
                    Frame(LF2StandardFrames.WalkingStart, LF2States.Walking, 0, LF2StandardFrames.WalkingStart, 39, 79),
                    Frame(LF2StandardFrames.Walking1, LF2States.Walking, 0, LF2StandardFrames.Walking1, 39, 79),
                    Frame(LF2StandardFrames.Walking2, LF2States.Walking, 0, LF2StandardFrames.Walking2, 39, 79),
                    Frame(LF2StandardFrames.WalkingEnd, LF2States.Walking, 0, LF2StandardFrames.WalkingEnd, 39, 79),
                    Frame(LF2StandardFrames.RunningStart, LF2States.Running, 0, LF2StandardFrames.RunningStart, 39, 79),
                    Frame(LF2StandardFrames.Running1, LF2States.Running, 0, LF2StandardFrames.Running1, 39, 79),
                    Frame(LF2StandardFrames.RunningEnd, LF2States.Running, 0, LF2StandardFrames.RunningEnd, 39, 79),
                },
            };

            LF2Character moveRaw = CreateCharacter("SelfCheck_MoveRawWrite", 10, data);
            moveRaw.Frame.PN = 777;
            moveRaw.AttackingCounter = 9;
            moveRaw.Trans.SyncDirectFrameData(moveRaw.Frame.D.wait, moveRaw.Frame.D.next, 13);
            moveRaw.SetMoveFrameDirectInternal(LF2StandardFrames.WalkingStart);
            Expect(moveRaw.Frame.N == LF2StandardFrames.WalkingStart &&
                   moveRaw.Frame.PN == 777 &&
                   moveRaw.Trans.WaitCounter == 13 &&
                   moveRaw.AttackingCounter == 9,
                "RISK-2: move raw writes must preserve PrevFrame/PN, WaitCounter, and AttackingCounter");

            LF2Character walking = CreateCharacter("SelfCheck_WalkingSingleAdvance", 11, data);
            walking.Controller = new CharacterInputModule();
            walking.Runtime.Vx = 7.0;
            walking.Controller.InputBuffer.EnqueueForTick(1, FuncKeyMask.up, true);
            walking.RunPostCooldownInputPhase(1);
            Expect(walking.Runtime.AnimCounter == 1 &&
                   walking.Frame.N == LF2StandardFrames.Walking1 &&
                   Nearly(walking.Runtime.Vx, 5.0) &&
                   Nearly(walking.Runtime.Vz, -2.0),
                "RISK-1: walking input pass must advance locomotion exactly once before late frame rollover");
            walking.SimFrameTick(1);
            Expect(walking.Runtime.AnimCounter == 1 &&
                   walking.Frame.N == LF2StandardFrames.Walking1 &&
                   Nearly(walking.Runtime.Vx, 5.0) &&
                   Nearly(walking.Runtime.Vz, -2.0),
                "RISK-1: walking wait rollover must not run the locomotion resolver a second time in FrameEvent");

            LF2Character running = CreateCharacter("SelfCheck_RunningSingleAdvance", 12, data);
            running.Controller = new CharacterInputModule();
            running.ImmediateFrame(LF2StandardFrames.RunningStart);
            running.Controller.InputBuffer.EnqueueForTick(2, FuncKeyMask.up, true);
            running.RunPostCooldownInputPhase(2);
            double expectedRunVx = 8.0 * (5.0 / 6.0);
            Expect(running.Runtime.AnimCounter == 1 &&
                   running.Frame.N == LF2StandardFrames.Running1 &&
                   Nearly(running.Runtime.Vx, expectedRunVx) &&
                   Nearly(running.Runtime.Vz, -3.0),
                "RISK-1: running input pass must advance locomotion exactly once before late frame rollover");
            running.SimFrameTick(2);
            Expect(running.Runtime.AnimCounter == 1 &&
                   running.Frame.N == LF2StandardFrames.Running1 &&
                   Nearly(running.Runtime.Vx, expectedRunVx) &&
                   Nearly(running.Runtime.Vz, -3.0),
                "RISK-1: running wait rollover must not run the locomotion resolver a second time in FrameEvent");

            LF2Character stateEntry = CreateCharacter("SelfCheck_WalkingStateEntry", 13, data);
            stateEntry.Runtime.AnimCounter = 7;
            stateEntry.Runtime.AnimSub = 4;
            stateEntry.OnFrameTransit(LF2StandardFrames.WalkingStart, false);
            Expect(stateEntry.Runtime.AnimCounter == 0 && stateEntry.Runtime.AnimSub == 0,
                "RISK-1: removing duplicate frame locomotion must retain walking state-entry side effects");
        }

        private static void CheckSharedCharacterDatInputAlignmentContracts()
        {
            LF2FrameData dashFrame = Frame(
                LF2StandardFrames.DashForward,
                LF2States.Dash,
                1,
                LF2StandardFrames.DashForward,
                39,
                79);
            dashFrame.dvy = 2;
            var data = new LF2CharacterData
            {
                name = "SelfCheck_SharedInputAlignment",
                running_speed = 8f,
                running_speedz = 3f,
                running_frame_rate = 1,
                dash_distance = 10f,
                dash_distancez = 4f,
                dash_height = -4f,
                frames = new List<LF2FrameData>
                {
                    Frame(0, LF2States.Standing, 1, 0, 39, 79),
                    Frame(LF2StandardFrames.RunningStart, LF2States.Running, 1, LF2StandardFrames.RunningStart, 39, 79),
                    Frame(LF2StandardFrames.Running1, LF2States.Running, 1, LF2StandardFrames.Running1, 39, 79),
                    Frame(LF2StandardFrames.RunningEnd, LF2States.Running, 1, LF2StandardFrames.RunningEnd, 39, 79),
                    Frame(LF2StandardFrames.SuperPunch, LF2States.Attack, 1, LF2StandardFrames.SuperPunch, 39, 79),
                    Frame(LF2StandardFrames.RunAttack, LF2States.Attack, 1, LF2StandardFrames.RunAttack, 39, 79),
                    Frame(LF2StandardFrames.Rowing2, LF2States.Rowing, 1, LF2StandardFrames.Rowing2, 39, 79),
                    Frame(LF2StandardFrames.JumpAttack, LF2States.Attack, 1, LF2StandardFrames.JumpAttack, 39, 79),
                    Frame(LF2StandardFrames.JumpingAir, LF2States.Jump, 1, LF2StandardFrames.JumpingAir, 39, 79),
                    dashFrame,
                    Frame(LF2StandardFrames.Crouch, LF2States.StopRunning, 1, LF2StandardFrames.Crouch, 39, 79),
                    Frame(LF2StandardFrames.StopRunning, LF2States.StopRunning, 1, LF2StandardFrames.StopRunning, 39, 79),
                },
            };

            SelfCheckCharacterDatShell running = CreateSharedInputShell(data, LF2StandardFrames.RunningStart);
            running.Frame.PN = 444;
            running.Runtime.KeyJump = 1;
            running.Runtime.KeyAttack = 1;
            running.Runtime.KeyDefend = 1;
            running.Runtime.CdAttack = 5;
            running.Runtime.CdDefend = 5;
            running.Runtime.CdJump = 5;
            running.RunPostCooldownInputPhase(1);
            Expect(running.Frame.N == LF2StandardFrames.DashForward,
                "INPUT-8: shared running must apply attack, then defend, then jump so jump wins simultaneous input");
            Expect(running.Frame.PN == 444,
                "INPUT-7: shared raw input frame writes must preserve PrevFrame/PN");
            Expect(Nearly(running.Runtime.Vy, -2.0),
                "INPUT-4: shared post-cooldown input must apply the final frame velocity tail exactly once");

            SelfCheckCharacterDatShell runningDefend = CreateSharedInputShell(data, LF2StandardFrames.RunningStart);
            runningDefend.Runtime.KeyAttack = 1;
            runningDefend.Runtime.CdDefend = 5;
            runningDefend.RunPostCooldownInputPhase(2);
            Expect(runningDefend.Frame.N == LF2StandardFrames.Rowing2,
                "INPUT-8: shared running must retain the authority running-defend branch");

            SelfCheckCharacterDatShell stopRunning = CreateSharedInputShell(data, LF2StandardFrames.RunningStart);
            stopRunning.Runtime.KeyLeft = 1;
            stopRunning.RunPostCooldownInputPhase(3);
            Expect(stopRunning.Frame.N == LF2StandardFrames.StopRunning &&
                   Nearly(stopRunning.Runtime.Vx, 8.0),
                "INPUT-8: reverse running input must enter stop-running while preserving old-direction velocity");

            SelfCheckCharacterDatShell groundedJump = CreateSharedInputShell(data, LF2StandardFrames.JumpingAir);
            groundedJump.Runtime.Y = -0.5;
            groundedJump.Runtime.YInt = 0;
            groundedJump.Runtime.KeyJump = 1;
            groundedJump.RunPostCooldownInputPhase(4);
            Expect(groundedJump.Frame.N == LF2StandardFrames.JumpingAir,
                "INPUT-2: shared jump attack must gate on YInt and reject a grounded integer snapshot");

            groundedJump.Runtime.YInt = -1;
            groundedJump.RunPostCooldownInputPhase(5);
            Expect(groundedJump.Frame.N == LF2StandardFrames.JumpAttack,
                "INPUT-2: shared jump attack must accept an airborne integer snapshot");

            SelfCheckCharacterDatShell superPunch = CreateSharedInputShell(data, 0);
            superPunch.Runtime.KeyJump = 1;
            superPunch.Runtime.CdAttack = 5;
            superPunch.HitConfirmCounter = 3;
            superPunch.RunPostCooldownInputPhase(6);
            Expect(superPunch.Frame.N == LF2StandardFrames.SuperPunch && superPunch.HitConfirmCounter == 3,
                "INPUT-6: shared Super Punch selection must not consume HitConfirm early");

            SelfCheckCharacterDatShell crouchAttack = CreateSharedInputShell(data, LF2StandardFrames.Crouch);
            crouchAttack.Runtime.KeyJump = 1;
            crouchAttack.Runtime.CdAttack = 5;
            crouchAttack.RunPostCooldownInputPhase(7);
            Expect(crouchAttack.Frame.N == LF2StandardFrames.Crouch,
                "INPUT-9: frame 215 must not accept the extra KeyJump/CdAttack action branch");

            SelfCheckCharacterDatShell crouchDefend = CreateSharedInputShell(data, LF2StandardFrames.Crouch);
            crouchDefend.Runtime.KeyAttack = 1;
            crouchDefend.Runtime.CdDefend = 5;
            crouchDefend.RunPostCooldownInputPhase(8);
            Expect(crouchDefend.Frame.N == LF2StandardFrames.Rowing2,
                "INPUT-9: frame 215 must retain the authority KeyAttack/CdDefend branch");
        }

        private static SelfCheckCharacterDatShell CreateSharedInputShell(
            LF2CharacterData data,
            int frameId)
        {
            var shell = new SelfCheckCharacterDatShell();
            shell.InitializeForCpoint();
            shell.Name = $"SelfCheck_SharedInput_{frameId}";
            shell.ObjectId = 2;
            shell.FrameCache.Load(new LF2CharacterDataWrapper(2, data));
            shell.Frame.N = frameId;
            shell.Frame.D = shell.FrameCache.GetFrameDataById(frameId);
            shell.Frame.PN = frameId;
            shell.Runtime.Dir = "right";
            shell.Runtime.Y = 0.0;
            shell.Runtime.YInt = 0;
            shell.Runtime.PP = 500;
            shell.Runtime.HP = 500;
            shell.Runtime.HPBound = 500;
            shell.Trans.SyncDirectFrameData(shell.Frame.D.wait, shell.Frame.D.next, 0);
            shell.RefreshRuntimeSnapshot();
            return shell;
        }

        private static void CheckMappedAction(
            string name,
            Action<CharacterInputModule, bool> setPressed,
            byte expectedKeyJump,
            byte expectedKeyDefend,
            byte expectedKeyAttack,
            Func<NTSDEntityRuntime, byte> expectedCooldown,
            Func<LF2Character, bool> expectedFrame)
        {
            LF2Character character = CreateBufferedInputCharacter($"SelfCheck_{name}");
            var input = (CharacterInputModule)character.Controller;

            setPressed(input, true);
            character.RunPostCooldownInputPhase(1);

            Expect(character.Runtime.KeyJump == expectedKeyJump &&
                   character.Runtime.KeyDefend == expectedKeyDefend &&
                   character.Runtime.KeyAttack == expectedKeyAttack,
                $"{name} must map to the NTSD internal field contract");
            Expect(expectedCooldown(character.Runtime) == 5,
                $"{name} must set only its matching NTSD semantic cooldown edge");
            Expect(expectedFrame(character),
                $"{name} must trigger its logical action in the target simulation tick");

            setPressed(input, false);
            character.RunPostCooldownInputPhase(2);
            Expect(character.Runtime.KeyJump == 0 &&
                   character.Runtime.KeyDefend == 0 &&
                   character.Runtime.KeyAttack == 0,
                $"{name} release must clear its internal field without a stuck input");
        }

        private static void CheckBufferedActionCombination()
        {
            LF2Character character = CreateBufferedInputCharacter("SelfCheck_ActionCombination");
            var input = (CharacterInputModule)character.Controller;

            input.SetAttackActionPressed(true);
            input.SetJumpActionPressed(true);
            character.RunPostCooldownInputPhase(1);
            Expect(character.Runtime.KeyJump == 1 && character.Runtime.KeyDefend == 1 && character.Runtime.KeyAttack == 0,
                "J+K must preserve both internal held fields without writing the defend field");
            Expect(character.Runtime.CdAttack == 5 && character.Runtime.CdJump == 5 && character.Runtime.CdDefend == 0,
                "J+K must update attack/jump cooldowns without cross-writing defend cooldown");

            input.SetAttackActionPressed(false);
            character.RunPostCooldownInputPhase(2);
            Expect(character.Runtime.KeyJump == 0 && character.Runtime.KeyDefend == 1 && character.Runtime.KeyAttack == 0,
                "releasing J while K stays held must not clear or duplicate the K field");

            input.SetJumpActionPressed(false);
            character.RunPostCooldownInputPhase(3);
            Expect(character.Runtime.KeyJump == 0 && character.Runtime.KeyDefend == 0 && character.Runtime.KeyAttack == 0,
                "releasing the final combination key must leave no held action field");
        }

        private static void CheckBufferedDirectionReversal()
        {
            GameObject presentationFixture = new GameObject("SelfCheck_DirectionPresentation");
            try
            {
                SpriteRenderer renderer = presentationFixture.AddComponent<SpriteRenderer>();
                LF2Character walking = CreateBufferedInputCharacter("SelfCheck_WalkingReversal");
                walking.Sprite.Initialize(renderer, new List<Sprite>());
                SimInputBuffer walkingBuffer = walking.Controller.InputBuffer;
                walkingBuffer.EnqueueForTick(1, FuncKeyMask.right, true);
                walking.RunPostCooldownInputPhase(1);
                walkingBuffer.EnqueueForTick(2, FuncKeyMask.right, false);
                walkingBuffer.EnqueueForTick(2, FuncKeyMask.left, true);
                walking.RunPostCooldownInputPhase(2);

                Expect(walking.Runtime.KeyRight == 0 && walking.Runtime.KeyLeft == 1,
                    "D release + A press must clear right and set left in the same target tick");
                Expect(walking.Runtime.Dir == "left" && walking.PS.dir == "left" && walking.Runtime.Vx < 0.0,
                    $"standing/walking reversal must face left and write negative velocity immediately; " +
                    $"frame={walking.Frame.N},dir={walking.Runtime.Dir},psDir={walking.PS.dir}," +
                    $"vx={walking.Runtime.Vx:R},keyR={walking.Runtime.KeyRight},keyL={walking.Runtime.KeyLeft}," +
                    $"prevR={walking.Runtime.PrevRight},prevL={walking.Runtime.PrevLeft}," +
                    $"cdR={walking.Runtime.CdRight},cdL={walking.Runtime.CdLeft},animSub={walking.Runtime.AnimSub}");
                Expect(walking.Sprite.Dir == "left" && renderer.flipX,
                    "standing/walking reversal must flip the visible sprite in the same tick");

                walking.PS.dir = "right";
                walking.Sprite.SwitchLR("right");
                renderer.flipX = false;
                walking.SwitchDir("left");
                Expect(walking.Runtime.Dir == "left" && walking.PS.dir == "left" &&
                       walking.Sprite.Dir == "left" && renderer.flipX,
                    "SwitchDir must repair PS and renderer drift even when Runtime already has the requested direction");

                LF2Character running = CreateBufferedInputCharacter("SelfCheck_RunningReversal");
                running.ImmediateFrame(LF2StandardFrames.RunningStart);
                running.SwitchDir("right");
                SimInputBuffer runningBuffer = running.Controller.InputBuffer;
                runningBuffer.EnqueueForTick(1, FuncKeyMask.right, true);
                running.RunPostCooldownInputPhase(1);
                runningBuffer.EnqueueForTick(2, FuncKeyMask.right, false);
                runningBuffer.EnqueueForTick(2, FuncKeyMask.left, true);
                running.RunPostCooldownInputPhase(2);

                Expect(running.Runtime.KeyRight == 0 && running.Runtime.KeyLeft == 1,
                    "running reversal must consume the same-tick D release + A press snapshot");
                Expect(running.Frame.N == LF2StandardFrames.StopRunning && running.Runtime.Vx > 0.0 &&
                       running.Runtime.Dir == "right" && running.PS.dir == "right",
                    "running reversal must enter frame 218 while preserving the old-direction velocity for that tick");
            }
            finally
            {
                UnityEngine.Object.DestroyImmediate(presentationFixture);
            }
        }

        private static void CheckFrameSnapshotHumanInputPolling()
        {
            CheckHeldSnapshotEdgesAndHistory();

            LF2Character right = CreateFrameSnapshotComboCharacter("SelfCheck_HeldRightDrj", 5);
            HoldDirectionForTicks(right, FuncKeyMask.right, 1, 6);
            EnqueueInputTick(right, 7, (FuncKeyMask.att, true));
            right.RunPostCooldownInputPhase(7);
            Expect(right.Frame.N == 102 && right.Runtime.ComboDrj == 0 &&
                   right.Runtime.CdDefend == 0 && right.Runtime.CdRight == 0 && right.Runtime.CdJump == 0,
                $"partial held-right+defend must not commit before the DJA fallthrough, while direct hit_d enters102 and clears cooldowns; " +
                $"frame={right.Frame.N},combo={right.Runtime.ComboDrj},cdD={right.Runtime.CdDefend}," +
                $"cdR={right.Runtime.CdRight},cdJ={right.Runtime.CdJump}");
            EnqueueInputTick(right, 8, (FuncKeyMask.def, true));
            right.RunPostCooldownInputPhase(8);
            Expect(right.Frame.N != 240,
                $"jump after the partial held-right direct tail must not incorrectly enter frame 240; " +
                $"frame={right.Frame.N},combo={right.Runtime.ComboDrj},cdD={right.Runtime.CdDefend}," +
                $"cdR={right.Runtime.CdRight},cdJ={right.Runtime.CdJump}");

            LF2Character left = CreateFrameSnapshotComboCharacter("SelfCheck_HeldLeftDrj", 8);
            HoldDirectionForTicks(left, FuncKeyMask.left, 1, 6);
            EnqueueInputTick(left, 7, (FuncKeyMask.att, true));
            left.RunPostCooldownInputPhase(7);
            Expect(left.Frame.N == 102 && left.Runtime.ComboDlj == 0 &&
                   left.Runtime.CdDefend == 0 && left.Runtime.CdLeft == 0 && left.Runtime.CdJump == 0,
                $"partial held-left+defend must not commit before the DJA fallthrough, while direct hit_d enters102 and clears cooldowns; " +
                $"frame={left.Frame.N},combo={left.Runtime.ComboDlj},cdD={left.Runtime.CdDefend}," +
                $"cdL={left.Runtime.CdLeft},cdJ={left.Runtime.CdJump}");
            EnqueueInputTick(left, 8, (FuncKeyMask.def, true));
            left.RunPostCooldownInputPhase(8);
            Expect(left.Frame.N != 240,
                $"jump after the partial held-left direct tail must not incorrectly enter frame 240; " +
                $"frame={left.Frame.N},combo={left.Runtime.ComboDlj},cdD={left.Runtime.CdDefend}," +
                $"cdL={left.Runtime.CdLeft},cdJ={left.Runtime.CdJump}");

            LF2Character sameTick = CreateFrameSnapshotComboCharacter("SelfCheck_RightSameTickDrj", 5);
            EnqueueInputTick(sameTick, 1,
                (FuncKeyMask.right, true), (FuncKeyMask.att, true), (FuncKeyMask.def, true));
            sameTick.RunPostCooldownInputPhase(1);
            Expect(sameTick.Frame.N == 240 && sameTick.Runtime.Dir == "right",
                "fresh right plus defend+jump in one tick must complete DRJ from frame 5");

            LF2Character sameTickLeft = CreateFrameSnapshotComboCharacter("SelfCheck_LeftSameTickDrj", 8);
            EnqueueInputTick(sameTickLeft, 1,
                (FuncKeyMask.left, true), (FuncKeyMask.att, true), (FuncKeyMask.def, true));
            sameTickLeft.RunPostCooldownInputPhase(1);
            Expect(sameTickLeft.Frame.N == 240 && sameTickLeft.Runtime.Dir == "left",
                "fresh left plus defend+jump in one tick must complete DLJ from frame 8");

            LF2Character releasedDefend = CreateFrameSnapshotComboCharacter("SelfCheck_ReleasedDefendDrj", 5);
            HoldDirectionForTicks(releasedDefend, FuncKeyMask.right, 1, 6);
            EnqueueInputTick(releasedDefend, 7, (FuncKeyMask.att, true));
            releasedDefend.RunPostCooldownInputPhase(7);
            EnqueueInputTick(releasedDefend, 8, (FuncKeyMask.att, false), (FuncKeyMask.def, true));
            releasedDefend.RunPostCooldownInputPhase(8);
            Expect(releasedDefend.Frame.N != 240,
                "releasing defend before the jump tick must not fabricate a staggered DRJ trigger");

            LF2Character both = CreateFrameSnapshotComboCharacter("SelfCheck_BothDirectionsDrj", 5);
            EnqueueInputTick(both, 1,
                (FuncKeyMask.right, true), (FuncKeyMask.left, true),
                (FuncKeyMask.att, true), (FuncKeyMask.def, true));
            both.RunPostCooldownInputPhase(1);
            Expect(both.Frame.N == 240 && both.Runtime.Dir == "right",
                "when both horizontal directions are held, DRJ must retain the authority right-wrapper priority");

            LF2Character dja = CreateFrameSnapshotComboCharacter("SelfCheck_NoDirectionDja", 5);
            int hpBefore = dja.Health.HP;
            EnqueueInputTick(
                dja,
                1,
                (FuncKeyMask.att, true),
                (FuncKeyMask.def, true),
                (FuncKeyMask.jump, true));
            dja.RunPostCooldownInputPhase(1);
            Expect(dja.Frame.N == 290 && dja.Health.HP == hpBefore &&
                   dja.Runtime.KeyRight == 0 && dja.Runtime.KeyLeft == 0 &&
                   dja.Runtime.KeyUp == 0 && dja.Runtime.KeyDown == 0,
                $"same-tick directionless DJA must enter hit_ja=290 without fabricating movement or damage; " +
                $"frame={dja.Frame.N},combo={dja.Runtime.ComboDja}");
        }

        private static void CheckHeldSnapshotEdgesAndHistory()
        {
            LF2Character character = CreateFrameSnapshotComboCharacter("SelfCheck_HeldSnapshot", 240);
            EnqueueInputTick(
                character,
                1,
                (FuncKeyMask.right, true),
                (FuncKeyMask.left, true),
                (FuncKeyMask.up, true),
                (FuncKeyMask.down, true),
                (FuncKeyMask.att, true),
                (FuncKeyMask.def, true),
                (FuncKeyMask.jump, true));

            character.RunPostCooldownInputPhase(1);
            NTSDEntityRuntime runtime = character.Runtime;
            Expect(runtime.KeyRight == 1 && runtime.KeyLeft == 1 &&
                   runtime.KeyUp == 1 && runtime.KeyDown == 1 &&
                   runtime.KeyAttack == 1 && runtime.KeyDefend == 1 && runtime.KeyJump == 1,
                "input polling must retain all final held keys");
            Expect(runtime.PrevRight == 0 && runtime.PrevLeft == 0 &&
                   runtime.PrevUp == 0 && runtime.PrevDown == 0 &&
                   runtime.PrevAttack == 0 && runtime.PrevDefend == 0 && runtime.PrevJump == 0,
                "first held snapshot must compare against the prior unheld state");
            Expect(runtime.CdRight == 5 && runtime.CdLeft == 5 &&
                   runtime.CdUp == 5 && runtime.CdDown == 5 &&
                   runtime.CdDefend == 5 && runtime.CdJump == 5 && runtime.CdAttack == 5,
                "new press edges must write cooldown 5");
            Expect(runtime.InputHistory[1] == 8 && runtime.InputHistory[2] == 2 &&
                   runtime.InputHistory[3] == 9 && runtime.InputHistory[4] == 0 &&
                   runtime.InputHistory[5] == 5,
                "new press history must use right,left,up,down,attack,defend,jump order");
            int[] firstPollHistory = (int[])runtime.InputHistory.Clone();

            runtime.ClearDirectionalInputKeys();
            runtime.ClearActionInputKeys();
            character.RunPostCooldownInputPhase(2);
            Expect(runtime.PrevRight == 1 && runtime.PrevLeft == 1 &&
                   runtime.PrevUp == 1 && runtime.PrevDown == 1 &&
                   runtime.PrevAttack == 1 && runtime.PrevDefend == 1 && runtime.PrevJump == 1,
                "held polling must baseline edges from the prior physical held snapshot after frame advance clears runtime keys");
            Expect(runtime.KeyRight == 1 && runtime.KeyLeft == 1 &&
                   runtime.KeyUp == 1 && runtime.KeyDown == 1 &&
                   runtime.KeyAttack == 1 && runtime.KeyDefend == 1 && runtime.KeyJump == 1 &&
                   runtime.CdRight == 4 && runtime.CdLeft == 4 &&
                   runtime.CdUp == 4 && runtime.CdDown == 4 &&
                   runtime.CdDefend == 4 && runtime.CdJump == 4 && runtime.CdAttack == 4 &&
                   System.Linq.Enumerable.SequenceEqual(firstPollHistory, runtime.InputHistory),
                "held polling must restore runtime keys without manufacturing cooldown or history edges");

            LF2Character walking = CreateBufferedInputCharacter("SelfCheck_HeldDirectionRemainsWalking");
            EnqueueInputTick(walking, 1, (FuncKeyMask.right, true));
            walking.RunPostCooldownInputPhase(1);
            Expect(walking.Frame.D.state == LF2States.Walking &&
                   walking.Frame.N != LF2StandardFrames.RunningStart,
                "the first physical direction edge must enter walking, not running");
            walking.Runtime.ClearDirectionalInputKeys();
            walking.RunPostCooldownInputPhase(2);
            Expect(walking.Runtime.KeyRight == 1 && walking.Runtime.PrevRight == 1 &&
                   walking.Runtime.CdRight == 4 && walking.Frame.D.state == LF2States.Walking &&
                   walking.Frame.N != LF2StandardFrames.RunningStart,
                $"holding D across runtime key clear must remain walking without a repeated double-tap edge; " +
                $"frame={walking.Frame.N},state={walking.Frame.D.state},prev={walking.Runtime.PrevRight}," +
                $"cd={walking.Runtime.CdRight},animSub={walking.Runtime.AnimSub}");

            LF2Character quickRepress = CreateBufferedInputCharacter("SelfCheck_QuickDirectionRepressRuns");
            EnqueueInputTick(quickRepress, 1, (FuncKeyMask.right, true));
            quickRepress.RunPostCooldownInputPhase(1);
            Expect(quickRepress.Frame.D.state == LF2States.Walking &&
                   quickRepress.Frame.N != LF2StandardFrames.RunningStart,
                "the first physical D press in a quick-repress sequence must enter walking");
            quickRepress.Runtime.ClearDirectionalInputKeys();
            quickRepress.Runtime.ClearActionInputKeys();

            EnqueueInputTick(quickRepress, 2, (FuncKeyMask.right, false));
            quickRepress.RunPostCooldownInputPhase(2);
            Expect(quickRepress.Runtime.KeyRight == 0 && quickRepress.Runtime.PrevRight == 1,
                "the physical D release must update the local held snapshot after runtime key clear");
            quickRepress.Runtime.ClearDirectionalInputKeys();
            quickRepress.Runtime.ClearActionInputKeys();

            EnqueueInputTick(quickRepress, 3, (FuncKeyMask.right, true));
            quickRepress.RunPostCooldownInputPhase(3);
            Expect(quickRepress.Runtime.KeyRight == 1 && quickRepress.Runtime.PrevRight == 0 &&
                   quickRepress.Runtime.CdRight == 5 &&
                   quickRepress.Frame.N == LF2StandardFrames.RunningStart &&
                   quickRepress.Frame.D.state == LF2States.Running,
                $"a real D release then quick re-press inside the AnimSub window must enter running; " +
                $"frame={quickRepress.Frame.N},state={quickRepress.Frame.D.state}," +
                $"prev={quickRepress.Runtime.PrevRight},cd={quickRepress.Runtime.CdRight}," +
                $"animSub={quickRepress.Runtime.AnimSub}");
        }

        private static LF2Character CreateFrameSnapshotComboCharacter(string name, int startFrame)
        {
            LF2FrameData frame5 = Frame(5, 999, 1, 5, 39, 79);
            frame5.hit_Fj = 240;
            frame5.hit_ja = 290;
            frame5.hit_d = 102;
            LF2FrameData frame8 = Frame(8, 999, 1, 8, 39, 79);
            frame8.hit_Fj = 240;
            frame8.hit_ja = 290;
            frame8.hit_d = 102;
            var data = new LF2CharacterData
            {
                name = name,
                frames = new List<LF2FrameData>
                {
                    Frame(0, 999, 1, 0, 39, 79),
                    frame5,
                    frame8,
                    Frame(102, 999, 1, 102, 39, 79),
                    Frame(240, 999, 1, 240, 39, 79),
                    Frame(290, 999, 1, 290, 39, 79),
                },
            };

            LF2Character character = CreateCharacter(name, 2, data);
            character.ImmediateFrame(startFrame);
            return character;
        }

        private static void HoldDirectionForTicks(
            LF2Character character,
            FuncKeyMask direction,
            int startTick,
            int count)
        {
            EnqueueInputTick(character, startTick, (direction, true));
            for (int tick = startTick; tick < startTick + count; tick++)
                character.RunPostCooldownInputPhase(tick);
        }

        private static void EnqueueInputTick(
            LF2Character character,
            int tickIndex,
            params (FuncKeyMask key, bool down)[] events)
        {
            SimInputBuffer inputBuffer = character.Controller.InputBuffer;
            for (int i = 0; i < events.Length; i++)
                inputBuffer.EnqueueForTick(tickIndex, events[i].key, events[i].down);
        }

