            LF2CharacterData heavyData = new LF2CharacterData
            {
                name = "SelfCheck_C02_HeavyPickup",
                type_sub = (int)LF2ObjectType.HeavyWeapon,
                frames = new List<LF2FrameData>
                {
                    Frame(0, LF2States.HeavyWeaponOnGround, 100, 0, 39, 79),
