            };
            var pickupWorld = new SimulationWorld();
            var kind2Attacker = new CurrentDatDispatchSelfCheckEntity(
                LF2ObjectType.Other, 983, LF2ObjectType.Character);
            kind2Attacker.BindData(983, BuildCatchingFrames());
