            var burningWorld = new SimulationWorld();
            burningWorld.Register(burning);
            burning.Health.HP = 3;
            burning.Health.HPBound = 2;
            burning.WeaponCount = 10;
            burning.Runtime.SetPosition(0.0, -1.0, 0.0);
            burning.Runtime.SetVelocity(0.0, 2.0, 0.0);
