            var frozenWorld = new SimulationWorld();
            frozenWorld.Register(frozen);
            frozen.Health.HP = 3;
            frozen.Health.HPBound = 2;
            frozen.FallDamageDiv = 0;
            frozen.Runtime.SetPosition(0.0, -1.0, 0.0);
