        private static LF2FrameData InteractionFrame(InteractionArea itr)
        {
            LF2FrameData frame = Frame(0, LF2States.Standing, 1, 0, 0, 0);
            frame.bodies.Add(new BodyBox
            {
                kind = 0,
                x = -20,
                y = -20,
                w = 40,
                h = 40,
            });
            if (itr != null)
                frame.itrs.Add(itr);
            return frame;
        }

