                LF2Character partner = CreateCharacter("SelfCheck_Oid8_Cooldown", 8, wrappers[8].characterData);
                self.SetRuntimeSlotIndex(1);
                partner.SetRuntimeSlotIndex(12);
                world.Register(self);
