        private static void CheckAudit7AppManagerSpawnContract()
        {
            const int characterOid = 983;
            const int seed = 0x4137;
            LF2CharacterDataWrapper wrapper = BuildStageSpawnWrapper(characterOid, "SelfCheck_Audit7AppSpawn");
            var config = new MatchConfig
            {
                seed = seed,
                players = new List<PlayerSlotConfig>
                {
                    new PlayerSlotConfig
                    {
                        use = true,
                        isHuman = true,
                        characterId = characterOid,
                        team = GameConfig.TeamIndependent,
                        inputId = 0,
                        aiId = -1,
                    },
                },
            };

            using var appManagerScope = new TemporaryAppManagerRuntimeScope();
            AppManager appManager = appManagerScope.Instance;
            Expect(appManager != null && AppManager.Instance == appManager && appManager.InputModule != null,
                "BATTLE-AUDIT7-F3/F4: production character spawn fixture requires an initialized AppManager singleton");

            MatchConfig originalConfig = appManager.CurrentMatchConfig;
            LF2Entity spawned = null;
            try
            {
                using var runtimeConfigs = new TemporaryRuntimeObjectConfigs(
                    new Dictionary<int, int> { [characterOid] = (int)LF2ObjectType.Character },
                    new Dictionary<int, LF2CharacterDataWrapper> { [characterOid] = wrapper });
                using var objectPoolState = new TemporaryObjectPoolInitialization();
                var world = new SimulationWorld();
                world.Runtime.Stage.SetSceneSnapshot(1000, 180, 350, 0, 0);
                world.Runtime.Roster.ApplyMatchConfig(config);
                world.Rng.Seed(seed);

                var expectedRng = new DeterministicRng(seed);
                int expectedX = 250 + expectedRng.NextRaw() % 500;
                int expectedZ = 180 + expectedRng.NextRaw() % 170;

                using (new TemporarySimulationDriverWorld(world))
                {
                    appManager.SetMatchConfig(config);
                    var setupMethod = typeof(AppManager).GetMethod(
                        "SetupBattleCharacters",
                        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                    Expect(setupMethod != null,
                        "BATTLE-AUDIT7-F3/F4: AppManager.SetupBattleCharacters production entry changed");
                    setupMethod.Invoke(appManager, new object[] { default(UnityEngine.SceneManagement.Scene) });

                    BattleSlotRuntimeState rosterSlot = world.Runtime.Roster.Slots[0];
                    spawned = world.FindEntityByRuntimeSlotForQuery(rosterSlot.RuntimeSlotIndex);
                    Expect(spawned is LF2Character && spawned.ObjectId == characterOid &&
                           rosterSlot.StableId == spawned.Runtime.StableId,
                        "BATTLE-AUDIT7-F2/F3: production app spawn must bind the created character back to its original roster slot");
                    Expect(Nearly(spawned.Runtime.X, expectedX) && spawned.Runtime.XInt == expectedX &&
                           Nearly(spawned.Runtime.Y, 0.0) && spawned.Runtime.YInt == 0 &&
                           Nearly(spawned.Runtime.Z, expectedZ) && spawned.Runtime.ZInt == expectedZ &&
                           world.Rng.CallCount == 2,
                        "BATTLE-AUDIT7-F3: production character spawn must use runtime bounds and exactly two seeded RNG calls, independent of Scene spawn points");
                    Expect(Nearly(spawned.Runtime.Vx, 0.1) && Nearly(spawned.Runtime.Vy, 0.0) &&
                           Nearly(spawned.Runtime.Vz, 0.1) && spawned.HitStun == 75,
                        "BATTLE-AUDIT7-F4: normal production character spawn must initialize HitStop=75 and velocity=(0.1,0,0.1)");
                    Expect(spawned.Team == 10 && spawned.RelationTeam == 10 && !spawned.AiControlled,
                        "BATTLE-AUDIT7-F2/F4: normal spawn must retain normalized independent team and human ownership");
                }
            }
            finally
            {
                try
                {
                    spawned?.FreeEntityLikeExe();
                }
                finally
                {
                    appManager.SetMatchConfig(originalConfig);
                }
            }
        }

        private static void CheckStageWavePositiveSpawnRefill()
        {
            const int stageOid = 202;
            LF2CharacterDataWrapper stageWrapper = BuildStageSpawnWrapper(stageOid, "SelfCheck_StagePositive");
            System.Func<int, LF2CharacterDataWrapper> previousResolver = LF2Entity.RuntimeCharacterConfigResolverOverride;
            try
            {
                using var runtimeConfigs = new TemporaryRuntimeObjectConfigs(
                    new Dictionary<int, int> { [stageOid] = (int)LF2ObjectType.Character },
                    new Dictionary<int, LF2CharacterDataWrapper> { [stageOid] = stageWrapper });
                using var objectPoolState = new TemporaryObjectPoolInitialization();
                LF2Entity.RuntimeCharacterConfigResolverOverride = oid => oid == stageOid ? stageWrapper : null;

                var world = new SimulationWorld();
                world.Runtime.Match.BattleGameModeId = 2;
                LF2Character factorCharacter = CreateCharacter(
                    "SelfCheck_StageFactor",
                    1,
                    BuildStageSpawnCharacterData("SelfCheck_StageFactor"));
                factorCharacter.SetRuntimeSlotIndex(0);
                world.Register(factorCharacter);
                world.StageCampaigns.Add(new BattleStageCampaignData
                {
                    Id = 10,
                    Phases = new List<BattleStagePhaseData>
                    {
                        new BattleStagePhaseData
                        {
                            Spawns = new List<BattleStageSpawnData>
                            {
                                new BattleStageSpawnData
                                {
                                    Id = stageOid,
                                    Act = 7,
                                    Hp = 250,
                                    Times = 2,
                                    X = 200,
                                    Ratio = 1.0,
                                },
                            },
                        },
                    },
                });
                world.StageProgression.StageSeriesIdx = 10;
                world.StageProgression.WaveIdx = 0;
                world.SetStageProgressionValid(true);

                world.CurrentWaveStageTickAll();

                Expect(world.StageSpawnWaveDeferredEntryApplied == 0 && world.StageSpawnRuntimeWave == 0,
                    "positive stage producer must initialize its deferred marker and runtime wave");
                Expect(world.StageSpawnRuntimeEntryCount.Count == 1 &&
                       world.StageSpawnRuntimeEntryCount[0] == 1 &&
                       world.StageSpawnRuntimeTargetTotal[0] == 2 &&
                       world.StageSpawnRuntimeSpawnedTotal[0] == 1,
                    "positive stage runtime must derive one concurrent entry and two total spawns from factor 1");
                int firstSlot = world.StageSpawnRuntimeSlots[0][0];
                LF2Entity firstSpawn = world.FindEntityByRuntimeSlotForQuery(firstSlot);
                Expect(firstSlot == 20 && firstSpawn != null && firstSpawn.ObjectId == stageOid,
                    "positive stage producer must track its active entity in the first free authority stage slot");

                world.CurrentWaveStageTickAll();
                Expect(world.StageSpawnRuntimeSpawnedTotal[0] == 1 &&
                       world.StageSpawnRuntimeSlots[0][0] == firstSlot,
                    "positive stage producer must not exceed its concurrent entry count while the slot is alive");

                world.Unregister(firstSpawn);
                world.CurrentWaveStageTickAll();

                int replacementSlot = world.StageSpawnRuntimeSlots[0][0];
                LF2Entity replacement = world.FindEntityByRuntimeSlotForQuery(replacementSlot);
                Expect(replacement != null && replacement.ObjectId == stageOid,
                    "positive stage producer must refill a cleared concurrent slot");
                Expect(world.StageSpawnRuntimeSpawnedTotal[0] == 2,
                    "positive stage producer must increment total spawned count on refill");

                world.Unregister(replacement);
                world.CurrentWaveStageTickAll();
                Expect(world.StageSpawnRuntimeSlots[0][0] == -1 &&
                       world.StageSpawnRuntimeSpawnedTotal[0] == 2,
                    "positive stage producer must stop refilling after reaching target total");
            }
            finally
            {
                LF2Entity.RuntimeCharacterConfigResolverOverride = previousResolver;
            }
        }

        private static void CheckAiTargetCacheCoordinateAndDeterminism()
        {
            LF2CharacterData data = BuildComboWrapperCharacterData("SelfCheck_AI", 180);
            SimulationWorld firstWorld = BuildAiSelfCheckWorld(data, 12345, out LF2Character firstAi, out LF2Character firstTarget);
            firstWorld.AiInputAndComboAll(2);

            Expect(firstAi.Runtime.Unk360 == firstTarget.Runtime.SlotIndex,
                "AI must cache the selected target by runtime slot");
            Expect(firstAi.Runtime.KeyRight != 0 || firstAi.Runtime.KeyLeft != 0 ||
                   firstAi.Runtime.KeyUp != 0 || firstAi.Runtime.KeyDown != 0 ||
                   firstAi.Runtime.KeyAttack != 0 || firstAi.Runtime.KeyJump != 0 || firstAi.Runtime.KeyDefend != 0 ||
                   firstAi.Runtime.ComboDra != 0 || firstAi.Runtime.ComboDla != 0 || firstAi.Runtime.ComboDua != 0 ||
                   firstAi.Runtime.ComboDda != 0 || firstAi.Runtime.ComboDrj != 0 || firstAi.Runtime.ComboDlj != 0 ||
                   firstAi.Runtime.ComboDuj != 0 || firstAi.Runtime.ComboDdj != 0 || firstAi.Runtime.ComboDja != 0,
                "AI target pass must produce movement, action, or combo intent");

            SimulationWorld secondWorld = BuildAiSelfCheckWorld(data, 12345, out LF2Character secondAi, out _);
            secondWorld.AiInputAndComboAll(2);
            Expect(AiInputSignature(firstAi.Runtime) == AiInputSignature(secondAi.Runtime),
                "AI decisions must be deterministic for the same seed and runtime-slot world state");

            var spatialWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
            LF2Character spatialSelf = CreateCharacter("SelfCheck_AI_SpatialSelf", 33, data);
            LF2Character tieLow = CreateCharacter("SelfCheck_AI_SpatialTieLow", 4, data);
            LF2Character tieHigh = CreateCharacter("SelfCheck_AI_SpatialTieHigh", 4, data);
            LF2Character airborne = CreateCharacter("SelfCheck_AI_SpatialAir", 4, data);
            spatialSelf.SetRequiredRuntimeSlot(0);
            tieLow.SetRequiredRuntimeSlot(2);
            tieHigh.SetRequiredRuntimeSlot(3);
            airborne.SetRequiredRuntimeSlot(511);
            spatialSelf.RelationTeam = 1;
            tieLow.RelationTeam = tieHigh.RelationTeam = airborne.RelationTeam = 2;
            spatialSelf.Runtime.SetPosition(100, 0, 200);
            tieLow.Runtime.SetPosition(150, 0, 200);
            tieHigh.Runtime.SetPosition(50, 0, 200);
            airborne.Runtime.SetPosition(110, -3, 205);
            spatialSelf.Runtime.SyncIntegerPosition();
            tieLow.Runtime.SyncIntegerPosition();
            tieHigh.Runtime.SyncIntegerPosition();
            airborne.Runtime.SyncIntegerPosition();
            spatialWorld.Register(spatialSelf);
            spatialWorld.Register(tieLow);
            spatialWorld.Register(tieHigh);
            spatialWorld.Register(airborne);
            Expect(spatialWorld.AiNearestSpatialMatchesBruteForSelfCheck(
                       spatialSelf,
                       spatialWorld.InputPhase),
                "AI spatial nearest-target query must preserve slot ties and airborne override semantics");

            int[] targetDistances = { 8193, 9999, 10000 };
            bool[] targetAccepted = { true, true, false };
            for (int index = 0; index < targetDistances.Length; index++)
            {
                var boundaryWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 512);
                LF2Character boundarySelf = CreateCharacter(
                    $"SelfCheck_AI_SpatialBoundarySelf_{targetDistances[index]}",
                    33,
                    data);
                LF2Character boundaryTarget = CreateCharacter(
                    $"SelfCheck_AI_SpatialBoundaryTarget_{targetDistances[index]}",
                    4,
                    data);
                boundarySelf.SetRequiredRuntimeSlot(0);
                boundaryTarget.SetRequiredRuntimeSlot(511);
                boundarySelf.AiControlled = true;
                boundarySelf.RelationTeam = 1;
                boundaryTarget.RelationTeam = 2;
                boundarySelf.Runtime.SetPosition(0, 0, 0);
                boundaryTarget.Runtime.SetPosition(targetDistances[index], 0, 0);
                boundarySelf.Runtime.SyncIntegerPosition();
                boundaryTarget.Runtime.SyncIntegerPosition();
                boundaryWorld.Register(boundarySelf);
                boundaryWorld.Register(boundaryTarget);

                boundaryWorld.AiInputAndComboAll(2);
                Expect((boundarySelf.Runtime.Unk360 == boundaryTarget.Runtime.SlotIndex) == targetAccepted[index],
                    $"AI nearest-target query must {(targetAccepted[index] ? "accept" : "reject")} Manhattan distance {targetDistances[index]}");
                Expect(boundaryWorld.AiNearestSpatialMatchesBruteForSelfCheck(
                           boundarySelf,
                           boundaryWorld.InputPhase),
                    $"AI spatial nearest-target query must match the authority slot scan at Manhattan distance {targetDistances[index]}");
            }

            SimulationWorld coordinateWorld = new SimulationWorld();
            LF2Character coordinateAi = CreateCharacter("SelfCheck_AI_Coordinate", 33, data);
            coordinateAi.SetRuntimeSlotIndex(3);
            coordinateAi.AiControlled = true;
            coordinateAi.RelationTeam = 1;
            coordinateAi.Runtime.SetPosition(100, 0, 100);
            coordinateAi.Runtime.SyncIntegerPosition();
            coordinateAi.Runtime.Unk3FC = 500;
            coordinateAi.Runtime.Unk400 = 300;
            coordinateAi.Runtime.KeyRight = 1;
            coordinateWorld.Runtime.Flow.AiRand3 = 5;
            coordinateWorld.Runtime.Match.Difficulty = 2;
            coordinateWorld.Rng.Seed(3);
            coordinateWorld.Register(coordinateAi);
            coordinateWorld.AiInputAndComboAll(2);
            Expect(coordinateAi.Runtime.KeyRight == 1 && coordinateAi.Runtime.KeyDown == 1,
                "AI coordinate mode must move toward Unk3FC/Unk400 without requiring a target");
            Expect(coordinateAi.Runtime.Unk360 == -1,
                "AI coordinate mode must not mutate the cached combat target");
            Expect(coordinateWorld.Runtime.Flow.AiRand3 == 5 && coordinateAi.Runtime.PrevRight == 0,
                "AI coordinate mode must reuse the previous world AiRand3 before normal-path globals are recomputed");
            Expect(coordinateAi.Runtime.CdRight == 5 &&
                   coordinateAi.Runtime.InputHistory[4] == 6 &&
                   coordinateAi.Runtime.InputHistory[5] == 2,
                "AI coordinate movement must apply right then down edges in authority history order");
        }

        private static void CheckAiSpatialQueryTieAndSentinelContracts()
        {
            var tree = new LooseQuadtreeBroadphase(1, 6);
            var entries = new List<IncrementalSpatialEntry>(20);
            for (int slot = 0; slot < 20; slot++)
            {
                int x = (slot % 5) * 32;
                int z = (slot / 5) * 32;
                entries.Add(new IncrementalSpatialEntry(
                    new RuntimeEntityHandle(slot, 1),
                    new SpatialAabbXZ(x, z, x + 4, z + 4)));
            }

            SpatialSynchronizeResult synchronized = tree.Synchronize(
                entries,
                new SpatialAabbXZ(0, 0, 256, 256));
            var queriedHandles = new List<RuntimeEntityHandle>();
            tree.QueryHandles(new SpatialAabbXZ(0, 0, 256, 256), queriedHandles);
            var uniqueHandles = new HashSet<RuntimeEntityHandle>(queriedHandles);
            Expect(synchronized.Succeeded && queriedHandles.Count == entries.Count &&
                   uniqueHandles.Count == entries.Count,
                "incremental quadtree queries must enumerate every active handle exactly once without AI-side sorting or deduplication");

            LF2CharacterData data = BuildComboWrapperCharacterData("SelfCheck_AI_SpatialTie", 180);
            var world = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 64);
            LF2Character self = CreateCharacter("SelfCheck_AI_SpatialTieSelf", 33, data);
            LF2Character groundLow = CreateCharacter("SelfCheck_AI_SpatialTieGroundLow", 4, data);
            LF2Character groundHigh = CreateCharacter("SelfCheck_AI_SpatialTieGroundHigh", 4, data);
            LF2Character airLow = CreateCharacter("SelfCheck_AI_SpatialTieAirLow", 4, data);
            LF2Character airHigh = CreateCharacter("SelfCheck_AI_SpatialTieAirHigh", 4, data);
            self.SetRequiredRuntimeSlot(0);
            groundLow.SetRequiredRuntimeSlot(2);
            groundHigh.SetRequiredRuntimeSlot(17);
            airLow.SetRequiredRuntimeSlot(4);
            airHigh.SetRequiredRuntimeSlot(6);
            self.RelationTeam = 1;
            groundLow.RelationTeam = groundHigh.RelationTeam = airLow.RelationTeam = airHigh.RelationTeam = 2;
            self.Runtime.SetPosition(0, 0, 0);
            groundLow.Runtime.SetPosition(100, 0, 10);
            groundHigh.Runtime.SetPosition(-100, 0, 10);
            airLow.Runtime.SetPosition(20, -3, 35);
            airHigh.Runtime.SetPosition(-20, -3, 35);
            self.Runtime.SyncIntegerPosition();
            groundLow.Runtime.SyncIntegerPosition();
            groundHigh.Runtime.SyncIntegerPosition();
            airLow.Runtime.SyncIntegerPosition();
            airHigh.Runtime.SyncIntegerPosition();
            world.Register(self);
            world.Register(groundLow);
            world.Register(groundHigh);
            world.Register(airLow);
            world.Register(airHigh);

            world.CaptureAiNearestTargetForSelfCheck(
                self,
                2,
                false,
                out int selected,
                out int bestDistance,
                out bool sameZLane);
            Expect(selected == airLow.Runtime.SlotIndex && bestDistance == 110 && sameZLane,
                "AI spatial selection must keep the lower slot on equal ground and air distances while preserving same-Z from the ground result");

            var boundaryWorld = new SimulationWorld(BattleRuntimeProfile.DesktopExtended, 64);
            LF2Character boundarySelf = CreateCharacter("SelfCheck_AI_SpatialSentinelSelf", 33, data);
            LF2Character boundaryTarget = CreateCharacter("SelfCheck_AI_SpatialSentinelTarget", 4, data);
            boundarySelf.SetRequiredRuntimeSlot(0);
            boundaryTarget.SetRequiredRuntimeSlot(5);
            boundarySelf.RelationTeam = 1;
            boundaryTarget.RelationTeam = 2;
            boundarySelf.Runtime.SetPosition(0, 0, 0);
            boundaryTarget.Runtime.SetPosition(10000, 0, 0);
            boundarySelf.Runtime.SyncIntegerPosition();
            boundaryTarget.Runtime.SyncIntegerPosition();
            boundaryWorld.Register(boundarySelf);
            boundaryWorld.Register(boundaryTarget);
            boundaryWorld.CaptureAiNearestTargetForSelfCheck(
                boundarySelf,
                2,
                false,
                out int boundarySelected,
                out int boundaryDistance,
                out bool boundarySameZ);
            Expect(boundarySelected == -1 && boundaryDistance == 10000 && !boundarySameZ,
                "AI spatial selection must reject an exact 10000-distance ground candidate when no nearer slot exists");
        }

