        private sealed class TemporaryRuntimeObjectConfigs : IDisposable
        {
            private readonly GameDataManager dataManager;
            private readonly CharacterAnimtorManager animatorManager;
            private readonly System.Reflection.FieldInfo objectLookupField;
            private readonly System.Reflection.FieldInfo cachedConfigField;
            private readonly System.Reflection.FieldInfo frameConfigField;
            private readonly Dictionary<int, ObjectDefinition> originalObjectLookup;
            private readonly GameDataConfig originalCachedConfig;
            private readonly Dictionary<int, LF2CharacterDataWrapper> originalFrameConfigs;
            private readonly bool replacedManagerCollections;
            private readonly Dictionary<int, ObjectDefinition> replacedDefinitions = new Dictionary<int, ObjectDefinition>();
            private readonly Dictionary<int, LF2CharacterDataWrapper> replacedWrappers = new Dictionary<int, LF2CharacterDataWrapper>();
            private readonly HashSet<int> addedDefinitions = new HashSet<int>();
            private readonly HashSet<int> addedWrappers = new HashSet<int>();

            public TemporaryRuntimeObjectConfigs(
                Dictionary<int, int> objectTypes,
                Dictionary<int, LF2CharacterDataWrapper> wrappers,
                IReadOnlyList<int> orderedObjectIds = null)
            {
                dataManager = GameDataManager.Instance;
                animatorManager = CharacterAnimtorManager.Instance;
                Expect(dataManager != null && animatorManager != null,
                    "runtime config fixture requires GameDataManager and CharacterAnimtorManager singletons");

                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                objectLookupField = typeof(GameDataManager).GetField("objectLookup", flags);
                cachedConfigField = typeof(GameDataManager).GetField("cachedConfig", flags);
                frameConfigField = typeof(CharacterAnimtorManager).GetField("TotalCharacterFrameConfig", flags);
                Expect(objectLookupField != null && cachedConfigField != null && frameConfigField != null,
                    "runtime config fixture reflection contract changed");

                originalObjectLookup = objectLookupField.GetValue(dataManager) as Dictionary<int, ObjectDefinition>;
                originalCachedConfig = cachedConfigField.GetValue(dataManager) as GameDataConfig;
                originalFrameConfigs = frameConfigField.GetValue(animatorManager) as Dictionary<int, LF2CharacterDataWrapper>;

                replacedManagerCollections = orderedObjectIds != null;
                Dictionary<int, ObjectDefinition> objectLookup = replacedManagerCollections
                    ? new Dictionary<int, ObjectDefinition>()
                    : originalObjectLookup ?? new Dictionary<int, ObjectDefinition>();
                Dictionary<int, LF2CharacterDataWrapper> frameConfigs =
                    originalFrameConfigs ?? new Dictionary<int, LF2CharacterDataWrapper>();
                if (replacedManagerCollections)
                {
                    var replacementConfig = new GameDataConfig();
                    for (int i = 0; i < orderedObjectIds.Count; i++)
                    {
                        int oid = orderedObjectIds[i];
                        Expect(objectTypes.TryGetValue(oid, out int objectType),
                            $"runtime config ordered fixture is missing oid {oid}");
                        var definition = new ObjectDefinition(oid, objectType, "self-check.dat");
                        replacementConfig.objects.Add(definition);
                        objectLookup[oid] = definition;
                    }
                    objectLookupField.SetValue(dataManager, objectLookup);
                    cachedConfigField.SetValue(dataManager, replacementConfig);
                }
                else if (originalObjectLookup == null)
                    objectLookupField.SetValue(dataManager, objectLookup);
                if (!replacedManagerCollections && originalCachedConfig == null)
                    cachedConfigField.SetValue(dataManager, new GameDataConfig());
                if (originalFrameConfigs == null)
                    frameConfigField.SetValue(animatorManager, frameConfigs);

                foreach (KeyValuePair<int, int> pair in objectTypes)
                {
                    if (replacedManagerCollections)
                        continue;
                    if (objectLookup.TryGetValue(pair.Key, out ObjectDefinition existing))
                        replacedDefinitions[pair.Key] = existing;
                    else
                        addedDefinitions.Add(pair.Key);
                    objectLookup[pair.Key] = new ObjectDefinition(pair.Key, pair.Value, "self-check.dat");
                }

                foreach (KeyValuePair<int, LF2CharacterDataWrapper> pair in wrappers)
                {
                    if (frameConfigs.TryGetValue(pair.Key, out LF2CharacterDataWrapper existing))
                        replacedWrappers[pair.Key] = existing;
                    else
                        addedWrappers.Add(pair.Key);
                    frameConfigs[pair.Key] = pair.Value;
                }
            }

            public void Dispose()
            {
                if (replacedManagerCollections)
                {
                    objectLookupField.SetValue(dataManager, originalObjectLookup);
                }
                else if (originalObjectLookup == null)
                {
                    objectLookupField.SetValue(dataManager, null);
                }
                else
                {
                    foreach (int oid in addedDefinitions)
                        originalObjectLookup.Remove(oid);
                    foreach (KeyValuePair<int, ObjectDefinition> pair in replacedDefinitions)
                        originalObjectLookup[pair.Key] = pair.Value;
                }
                cachedConfigField.SetValue(dataManager, originalCachedConfig);

                if (originalFrameConfigs == null)
                {
                    frameConfigField.SetValue(animatorManager, null);
                }
                else
                {
                    foreach (int oid in addedWrappers)
                        originalFrameConfigs.Remove(oid);
                    foreach (KeyValuePair<int, LF2CharacterDataWrapper> pair in replacedWrappers)
                        originalFrameConfigs[pair.Key] = pair.Value;
                }
            }
        }

        private sealed class TemporaryCommonShadowVisualConfig : IDisposable
        {
            private readonly CharacterAnimtorManager animatorManager;
            private readonly System.Reflection.FieldInfo catalogField;
            private readonly BattleCommonVisualCatalog originalCatalog;
            private readonly Sprite temporarySprite;
            private readonly Material temporaryMaterial;
            private readonly Texture2D temporarySparkTexture;
            private readonly Sprite[] temporarySparkSprites;
            private readonly Texture2D[] temporaryWordTextures;
            private readonly Sprite[][] temporaryWordSprites;

            public TemporaryCommonShadowVisualConfig(CharacterAnimtorManager animatorManager)
            {
                Expect(animatorManager != null,
                    "P7 self-check common shadow fixture requires CharacterAnimtorManager");
                this.animatorManager = animatorManager;
                catalogField = typeof(CharacterAnimtorManager).GetField(
                    "<CommonVisualCatalog>k__BackingField",
                    System.Reflection.BindingFlags.Instance |
                    System.Reflection.BindingFlags.NonPublic);
                Expect(catalogField != null,
                    "P7 self-check common shadow publication contract changed");
                originalCatalog = animatorManager.CommonVisualCatalog;

                BattleCommonVisualCatalog catalog;
#if UNITY_EDITOR
                NTSD.App.GameConfig productionConfig =
                    UnityEditor.AssetDatabase.LoadAssetAtPath<NTSD.App.GameConfig>(
                        "Assets/NTSD/Config/GameConfig/GameConfig.asset");
                GameObject productionShadowPrefab = productionConfig?.ShadowPrefab;
                BattleCommonShadowDescriptor productionDescriptor =
                    productionShadowPrefab != null
                        ? productionShadowPrefab.GetComponent<BattleCommonShadowDescriptor>()
                        : null;
                Sprite productionSprite = productionDescriptor != null
                    ? productionDescriptor.Sprite
                    : null;
                Texture2D productionTexture = productionSprite != null
                    ? productionSprite.texture
                    : null;
                BattleSpriteMaterialSemantic productionSemantic =
                    BattleSpriteMaterialContract.Classify(
                        productionDescriptor != null ? productionDescriptor.Material : null);
                catalog = BattleCommonVisualCatalog.Build(productionShadowPrefab);
                Expect(productionConfig != null && productionShadowPrefab != null &&
                       productionDescriptor != null && productionSprite != null &&
                       productionTexture != null &&
                       productionSemantic == BattleSpriteMaterialSemantic.PremultipliedSpriteAlpha &&
                       catalog.IsValid,
                    "P7 production GameConfig shadow asset is invalid: " + catalog.Diagnostic);
#else
                catalog = originalCatalog.IsValid
                    ? originalCatalog
                    : BattleCommonVisualCatalog.Build(NTSD.App.GameConfig.Instance?.ShadowPrefab);
#endif
                if (!catalog.IsValid)
                {
                    temporarySprite = Sprite.Create(
                        Texture2D.whiteTexture,
                        new Rect(0f, 0f, 1f, 1f),
                        new Vector2(0.5f, 0.5f),
                        100f);
                    Shader spriteShader = Shader.Find(BattleSpriteMaterialContract.BuiltInSpriteShaderName);
                    Expect(spriteShader != null,
                        "P7 self-check common shadow fixture requires the built-in sprite shader");
                    temporaryMaterial = new Material(spriteShader);
                    var prefab = new GameObject("SelfCheck_CommonShadowPublication");
                    prefab.AddComponent<BattleCommonShadowDescriptor>().ConfigureForSelfCheck(
                        temporarySprite,
                        temporaryMaterial,
                        Color.white);
                    catalog = BattleCommonVisualCatalog.Build(prefab);
                    DestroySelfCheckObject(prefab);
                }

                Expect(catalog.IsValid,
                    "P7 self-check requires a valid common shadow publication");
                temporarySparkTexture = new Texture2D(510, 256, TextureFormat.RGBA32, false);
                temporarySparkSprites = new Sprite[BattleCommonVisualCatalog.SparkFrameCount];
                for (int pic = 0; pic < temporarySparkSprites.Length; pic++)
                {
                    temporarySparkSprites[pic] = Sprite.Create(
                        temporarySparkTexture,
                        BattleCommonVisualCatalog.GetSparkPixelRect(pic),
                        BattleCommonVisualCatalog.GetSparkPivotNormalized(pic),
                        100f,
                        0,
                        SpriteMeshType.FullRect);
                }
                catalog = catalog.WithSpark(temporarySparkTexture, temporarySparkSprites);
                temporaryWordTextures = new Texture2D[BattleCommonVisualCatalog.WordSheetCount];
                temporaryWordSprites = new Sprite[BattleCommonVisualCatalog.WordSheetCount][];
                for (int sheet = 0; sheet < BattleCommonVisualCatalog.WordSheetCount; sheet++)
                {
                    temporaryWordTextures[sheet] = new Texture2D(
                        BattleCommonVisualCatalog.WordTextureWidth,
                        BattleCommonVisualCatalog.WordTextureHeight,
                        TextureFormat.RGBA32,
                        false);
                    temporaryWordSprites[sheet] = new Sprite[BattleCommonVisualCatalog.WordGlyphsPerSheet];
                    for (int charCode = 0; charCode < BattleCommonVisualCatalog.WordGlyphsPerSheet; charCode++)
                    {
                        temporaryWordSprites[sheet][charCode] = Sprite.Create(
                            temporaryWordTextures[sheet],
                            BattleCommonVisualCatalog.GetWordGlyphPixelRect(charCode),
                            BattleCommonVisualCatalog.GetWordGlyphPivotNormalized(),
                            100f,
                            0,
                            SpriteMeshType.FullRect);
                    }
                }
                catalog = catalog.WithWords(temporaryWordTextures, temporaryWordSprites);
                Expect(catalog.IsComplete,
                    "P7 self-check requires an atomic common Shadow+Spark+WORDS publication");
                catalogField.SetValue(animatorManager, catalog);
            }

            public void Dispose()
            {
                catalogField?.SetValue(animatorManager, originalCatalog);
                if (temporarySprite != null)
                    DestroySelfCheckAsset(temporarySprite);
                if (temporaryMaterial != null)
                    DestroySelfCheckAsset(temporaryMaterial);
                if (temporarySparkSprites != null)
                {
                    for (int pic = 0; pic < temporarySparkSprites.Length; pic++)
                    {
                        if (temporarySparkSprites[pic] != null)
                            DestroySelfCheckAsset(temporarySparkSprites[pic]);
                    }
                }
                if (temporarySparkTexture != null)
                    DestroySelfCheckAsset(temporarySparkTexture);
                if (temporaryWordSprites != null)
                {
                    for (int sheet = 0; sheet < temporaryWordSprites.Length; sheet++)
                    {
                        Sprite[] sprites = temporaryWordSprites[sheet];
                        if (sprites == null) continue;
                        for (int charCode = 0; charCode < sprites.Length; charCode++)
                            if (sprites[charCode] != null) DestroySelfCheckAsset(sprites[charCode]);
                    }
                }
                if (temporaryWordTextures != null)
                {
                    for (int sheet = 0; sheet < temporaryWordTextures.Length; sheet++)
                        if (temporaryWordTextures[sheet] != null) DestroySelfCheckAsset(temporaryWordTextures[sheet]);
                }
            }
        }

        private sealed class TemporaryCharacterSpriteConfig : IDisposable
        {
            private readonly Dictionary<int, List<Sprite>> spritesByObjectId;
            private readonly int objectId;
            private readonly bool hadOriginal;
            private readonly List<Sprite> originalSprites;
            private readonly Sprite temporarySprite;
            private readonly CharacterAnimtorManager animatorManager;
            private readonly System.Reflection.FieldInfo catalogField;
            private readonly BattleSpriteCatalog originalCatalog;

            public Sprite Sprite => temporarySprite;

            public TemporaryCharacterSpriteConfig(
                CharacterAnimtorManager animatorManager,
                int objectId,
                int spriteCount)
            {
                this.animatorManager = animatorManager;
                this.objectId = objectId;
                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                System.Reflection.FieldInfo spritesField = typeof(CharacterAnimtorManager).GetField(
                    "MergedSprites",
                    flags);
                Expect(spritesField != null,
                    "production sprite fixture CharacterAnimtorManager.MergedSprites contract changed");

                spritesByObjectId = spritesField.GetValue(animatorManager) as Dictionary<int, List<Sprite>>;
                Expect(spritesByObjectId != null,
                    "production sprite fixture requires an initialized sprite dictionary");
                hadOriginal = spritesByObjectId.TryGetValue(objectId, out originalSprites);

                temporarySprite = Sprite.Create(
                    Texture2D.whiteTexture,
                    new Rect(0f, 0f, 1f, 1f),
                    new Vector2(0.5f, 0f),
                    100f);
                var sprites = new List<Sprite>(spriteCount);
                for (int i = 0; i < spriteCount; i++)
                    sprites.Add(temporarySprite);
                spritesByObjectId[objectId] = sprites;

                catalogField = typeof(CharacterAnimtorManager).GetField(
                    "<SpriteCatalog>k__BackingField",
                    flags);
                Expect(catalogField != null,
                    "production sprite fixture CharacterAnimtorManager.SpriteCatalog contract changed");
                originalCatalog = catalogField.GetValue(animatorManager) as BattleSpriteCatalog ??
                                  BattleSpriteCatalog.Empty;
                var entries = new Dictionary<BattleSpriteKey, BattleSpriteEntry>();
                foreach (KeyValuePair<BattleSpriteKey, BattleSpriteEntry> pair in originalCatalog.Entries)
                    entries[pair.Key] = pair.Value;
                for (int pic = 0; pic < spriteCount; pic++)
                {
                    var key = new BattleSpriteKey(objectId, pic);
                    entries[key] = new BattleSpriteEntry(
                        key,
                        "self-check-temporary.bmp",
                        Texture2D.whiteTexture,
                        new Rect(0f, 0f, 1f, 1f),
                        new Vector2(0.5f, 0f),
                        temporarySprite);
                }
                catalogField.SetValue(animatorManager, new BattleSpriteCatalog(entries));
            }

            public void Dispose()
            {
                catalogField?.SetValue(animatorManager, originalCatalog);
                if (hadOriginal)
                    spritesByObjectId[objectId] = originalSprites;
                else
                    spritesByObjectId.Remove(objectId);

                if (temporarySprite != null)
                {
                    if (Application.isPlaying)
                        UnityEngine.Object.Destroy(temporarySprite);
                    else
                        UnityEngine.Object.DestroyImmediate(temporarySprite);
                }
            }
        }

        private sealed class TemporarySimulationDriverWorld : IDisposable
        {
            private readonly SimulationTickDriver driver;
            private readonly GameObject temporaryDriverObject;
            private readonly System.Reflection.FieldInfo instanceField;
            private readonly SimulationTickDriver originalDriverInstance;
            private readonly System.Reflection.FieldInfo worldField;
            private readonly SimulationWorld originalWorld;
            private readonly SimulationWorld temporaryWorld;
            private bool worldWasReplaced;

            public TemporarySimulationDriverWorld(SimulationWorld world)
            {
                var flags = System.Reflection.BindingFlags.Instance |
                            System.Reflection.BindingFlags.Static |
                            System.Reflection.BindingFlags.NonPublic;
                Type singletonBaseType = typeof(SimulationTickDriver).BaseType;
                instanceField = singletonBaseType?.GetField("<Instance>k__BackingField", flags);
                originalDriverInstance = instanceField?.GetValue(null) as SimulationTickDriver;
                SimulationTickDriver resolvedDriver = SimulationTickDriver.Instance;
                if (resolvedDriver == null)
                {
                    resolvedDriver = FindSceneComponent<SimulationTickDriver>();
                    if (resolvedDriver != null)
                    {
                        instanceField?.SetValue(null, resolvedDriver);
                    }
                    else
                    {
                        temporaryDriverObject = new GameObject("SelfCheck_TemporarySimulationTickDriver");
                        resolvedDriver = temporaryDriverObject.AddComponent<SimulationTickDriver>();
                        if (SimulationTickDriver.Instance == null)
                            instanceField?.SetValue(null, resolvedDriver);
                    }
                }
                driver = resolvedDriver;
                Expect(driver != null && SimulationTickDriver.Instance == driver,
                    "real opoint fixture failed to create its temporary SimulationTickDriver singleton");
                worldField = typeof(SimulationTickDriver).GetField(
                    "_world",
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                Expect(worldField != null, "real opoint fixture SimulationTickDriver._world contract changed");
                originalWorld = worldField.GetValue(driver) as SimulationWorld;
                temporaryWorld = world;
                worldField.SetValue(driver, temporaryWorld);
                worldWasReplaced = true;
            }

            public void Dispose()
            {
                try
                {
                    var spawned = new List<LF2Entity>();
                    for (int slot = 0; slot < 400; slot++)
                    {
                        LF2Entity entity = temporaryWorld.FindEntityByRuntimeSlotIncludingPending(slot);
                        if (entity != null && entity.ObjectId == 999 && entity.Renderer != null)
                            spawned.Add(entity);
                    }

                    for (int i = 0; i < spawned.Count; i++)
                        spawned[i].FreeEntityLikeExe();
                }
                finally
                {
                    if (worldWasReplaced)
                    {
                        try
                        {
                            worldField.SetValue(driver, originalWorld);
                        }
                        catch (Exception ex)
                        {
                            Debug.LogWarning($"[BattleRuntimeSelfCheck] Failed to restore SimulationTickDriver._world: {ex.Message}");
                        }
                    }

                    try
                    {
                        instanceField?.SetValue(null, originalDriverInstance);
                    }
                    catch (Exception ex)
                    {
                        Debug.LogWarning($"[BattleRuntimeSelfCheck] Failed to restore SimulationTickDriver.Instance: {ex.Message}");
                    }

                    if (temporaryDriverObject != null)
                    {
                        try
                        {
                            DestroySelfCheckObject(temporaryDriverObject);
                        }
                        catch (Exception ex)
                        {
                            Debug.LogWarning($"[BattleRuntimeSelfCheck] Failed to destroy its temporary SimulationTickDriver: {ex.Message}");
                        }
                    }
                }
            }
        }

        private sealed class TemporarySingletonSceneObjectScope : IDisposable
        {
            private readonly HashSet<GameObject> originalObjects = new HashSet<GameObject>();

            public TemporarySingletonSceneObjectScope()
            {
                CaptureSceneObjects<GameDataManager>(originalObjects);
                CaptureSceneObjects<CharacterAnimtorManager>(originalObjects);
                CaptureSceneObjects<LF2ObjectPointFactory>(originalObjects);
                CaptureSceneObjects<LF2ReferencePool>(originalObjects);
                CaptureSceneObjects<LF2ObjectPool>(originalObjects);
                CaptureSceneObjects<SimulationTickDriver>(originalObjects);
            }

            public void Dispose()
            {
                var currentObjects = new HashSet<GameObject>();
                CaptureSceneObjects<GameDataManager>(currentObjects);
                CaptureSceneObjects<CharacterAnimtorManager>(currentObjects);
                CaptureSceneObjects<LF2ObjectPointFactory>(currentObjects);
                CaptureSceneObjects<LF2ReferencePool>(currentObjects);
                CaptureSceneObjects<LF2ObjectPool>(currentObjects);
                CaptureSceneObjects<SimulationTickDriver>(currentObjects);

                foreach (GameObject currentObject in currentObjects)
                {
                    if (currentObject == null || originalObjects.Contains(currentObject))
                        continue;

                    try
                    {
                        DestroySelfCheckObject(currentObject);
                    }
                    catch (Exception ex)
                    {
                        Debug.LogWarning(
                            $"[BattleRuntimeSelfCheck] Failed to destroy self-check singleton '{currentObject.name}': {ex.Message}");
                    }
                }
            }
        }

        private static T FindSceneComponent<T>() where T : Component
        {
            T[] components = Resources.FindObjectsOfTypeAll<T>();
            for (int i = 0; i < components.Length; i++)
            {
                T component = components[i];
                if (component != null && component.gameObject.scene.IsValid())
                    return component;
            }

            return null;
        }

        private static void CaptureSceneObjects<T>(HashSet<GameObject> objects) where T : Component
        {
            T[] components = Resources.FindObjectsOfTypeAll<T>();
            for (int i = 0; i < components.Length; i++)
            {
                T component = components[i];
                if (component != null && component.gameObject.scene.IsValid())
                    objects.Add(component.gameObject);
            }
        }

        private sealed class TemporaryAppManagerRuntimeScope : IDisposable
        {
            private readonly System.Reflection.FieldInfo instanceField;
            private readonly AppManager originalInstance;
            private AppManager fixture;
            private GameObject fixtureObject;
            private bool productionInitialized;

            public AppManager Instance => fixture;

            public TemporaryAppManagerRuntimeScope()
            {
                var flags = System.Reflection.BindingFlags.Instance |
                            System.Reflection.BindingFlags.Static |
                            System.Reflection.BindingFlags.NonPublic;
                instanceField = typeof(NTSD.Tools.SingletonBehaviour<AppManager>).GetField(
                    "<Instance>k__BackingField",
                    flags);
                Expect(instanceField != null,
                    "production AppManager fixture singleton backing field contract changed");

                originalInstance = AppManager.Instance;
                if (originalInstance != null)
                {
                    fixture = originalInstance;
                    Expect(fixture.InputModule != null,
                        "production AppManager singleton exists without its Awake-initialized InputModule");
                    return;
                }

                try
                {
                    fixtureObject = new GameObject("SelfCheck_Audit7AppManager");
                    fixture = fixtureObject.AddComponent<AppManager>();
                    Expect(fixture != null,
                        "production character spawn fixture failed to create AppManager");

                    if (AppManager.Instance == null)
                    {
                        if (Application.isPlaying)
                        {
                            // Play Mode uses the real SingletonBehaviour lifecycle, including
                            // DontDestroyOnLoad and the production OnSingletonAwake dispatch.
                            var awake = typeof(NTSD.Tools.SingletonBehaviour<AppManager>).GetMethod(
                                "Awake",
                                flags);
                            Expect(awake != null,
                                "production AppManager fixture Awake contract changed");
                            awake.Invoke(fixture, null);
                        }
                        else
                        {
                            // EditMode cannot call the full base Awake because Unity rejects
                            // DontDestroyOnLoad outside Play Mode. Register the fixture first,
                            // then invoke the production initialization body directly.
                            instanceField.SetValue(null, fixture);
                            var initialize = typeof(AppManager).GetMethod(
                                "OnSingletonAwake",
                                flags);
                            Expect(initialize != null,
                                "production AppManager fixture OnSingletonAwake contract changed");
                            initialize.Invoke(fixture, null);
                        }

                        productionInitialized = true;
                    }
                    else if (AppManager.Instance == fixture)
                    {
                        productionInitialized = fixture.InputModule != null;
                    }

                    Expect(AppManager.Instance == fixture,
                        "production AppManager fixture failed to register through SingletonBehaviour.Awake");
                    Expect(fixture.InputModule != null,
                        "production AppManager fixture Awake did not initialize InputModule");
                }
                catch
                {
                    try
                    {
                        InvokeProductionCleanup(flags);
                        if (fixtureObject != null)
                            DestroySelfCheckObject(fixtureObject);
                    }
                    finally
                    {
                        instanceField.SetValue(null, originalInstance);
                    }

                    throw;
                }
            }

            public void Dispose()
            {
                try
                {
                    var flags = System.Reflection.BindingFlags.Instance |
                                System.Reflection.BindingFlags.NonPublic;
                    InvokeProductionCleanup(flags);
                    if (fixtureObject != null)
                        DestroySelfCheckObject(fixtureObject);
                }
                finally
                {
                    // Destroy is deferred in Play Mode. Restore the original singleton now so
                    // later checks cannot observe this temporary fixture; its OnDestroy still
                    // removes the sceneLoaded handler when Unity completes destruction.
                    try
                    {
                        instanceField.SetValue(null, originalInstance);
                    }
                    catch (Exception ex)
                    {
                        Debug.LogWarning($"[BattleRuntimeSelfCheck] Failed to restore AppManager.Instance: {ex.Message}");
                    }
                }
            }

            private void InvokeProductionCleanup(System.Reflection.BindingFlags flags)
            {
                if (!productionInitialized || fixture == null)
                    return;

                try
                {
                    var cleanup = typeof(AppManager).GetMethod("OnSingletonDestroyed", flags);
                    if (cleanup != null)
                        cleanup.Invoke(fixture, null);
                }
                catch (Exception ex)
                {
                    Debug.LogWarning($"[BattleRuntimeSelfCheck] Failed to clean up AppManager fixture events: {ex.Message}");
                }
                finally
                {
                    productionInitialized = false;
                }
            }
        }

        private static void DestroySelfCheckObject(GameObject target)
        {
            if (target == null)
                return;

            if (Application.isPlaying)
                UnityEngine.Object.Destroy(target);
            else
                UnityEngine.Object.DestroyImmediate(target);
        }

        private static void DestroySelfCheckAsset(UnityEngine.Object target)
        {
            if (target == null)
                return;

            if (Application.isPlaying)
                UnityEngine.Object.Destroy(target);
            else
                UnityEngine.Object.DestroyImmediate(target);
        }

        private static void DestroySelfCheckAssetImmediately(UnityEngine.Object target)
        {
            if (target != null)
                UnityEngine.Object.DestroyImmediate(target);
        }

        private sealed class TemporaryObjectPoolInitialization : IDisposable
        {
            private readonly LF2ObjectPool pool;
            private readonly GameObject temporaryPoolObject;
            private readonly System.Reflection.FieldInfo availableField;
            private readonly System.Reflection.FieldInfo activeField;
            private readonly System.Reflection.FieldInfo releaseMapField;
            private readonly System.Reflection.FieldInfo spritePoolField;
            private readonly System.Reflection.FieldInfo cachedPrefabField;
            private readonly object originalAvailable;
            private readonly object originalActive;
            private readonly object originalReleaseMap;
            private readonly object originalSpritePool;
            private readonly object originalCachedPrefab;
            private readonly bool ownsState;

            public TemporaryObjectPoolInitialization()
            {
                LF2ObjectPool resolvedPool = LF2ObjectPool.Instance;
                if (resolvedPool == null)
                {
                    temporaryPoolObject = new GameObject("SelfCheck_TemporaryLF2ObjectPool");
                    resolvedPool = temporaryPoolObject.AddComponent<LF2ObjectPool>();
                }
                pool = resolvedPool;
                Expect(pool != null, "real opoint fixture requires an LF2ObjectPool singleton");

                var flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                Type type = typeof(LF2ObjectPool);
                availableField = type.GetField("_availableObjects", flags);
                activeField = type.GetField("_activeObjects", flags);
                releaseMapField = type.GetField("_releaseTimeMap", flags);
                spritePoolField = type.GetField("_spritePool", flags);
                cachedPrefabField = type.GetField("_cachedLF2ObjectPrefab", flags);
                Expect(availableField != null && activeField != null && releaseMapField != null &&
                       spritePoolField != null && cachedPrefabField != null,
                    "real opoint fixture LF2ObjectPool field contract changed");

                originalAvailable = availableField.GetValue(pool);
                originalActive = activeField.GetValue(pool);
                originalReleaseMap = releaseMapField.GetValue(pool);
                originalSpritePool = spritePoolField.GetValue(pool);
                originalCachedPrefab = cachedPrefabField.GetValue(pool);
                ownsState = originalAvailable == null || originalActive == null ||
                            originalReleaseMap == null || originalSpritePool == null;
                if (!ownsState)
                    return;

                availableField.SetValue(pool, new LinkedList<GameObject>());
                activeField.SetValue(pool, new HashSet<GameObject>());
                releaseMapField.SetValue(pool, new Dictionary<GameObject, float>());
                spritePoolField.SetValue(pool, new Stack<SpriteRenderer>());
                cachedPrefabField.SetValue(pool, null);
            }

            public void Dispose()
            {
                try
                {
                    if (ownsState)
                    {
                        var objects = new HashSet<GameObject>();
                        if (availableField.GetValue(pool) is LinkedList<GameObject> available)
                        {
                            foreach (GameObject item in available)
                                if (item != null) objects.Add(item);
                        }
                        if (activeField.GetValue(pool) is HashSet<GameObject> active)
                        {
                            foreach (GameObject item in active)
                                if (item != null) objects.Add(item);
                        }
                        if (spritePoolField.GetValue(pool) is Stack<SpriteRenderer> sprites)
                        {
                            foreach (SpriteRenderer spriteRenderer in sprites)
                            {
                                if (spriteRenderer != null)
                                    objects.Add(spriteRenderer.gameObject);
                            }
                        }

                        foreach (GameObject item in objects)
                        {
                            if (Application.isPlaying)
                                UnityEngine.Object.Destroy(item);
                            else
                                UnityEngine.Object.DestroyImmediate(item);
                        }

                        availableField.SetValue(pool, originalAvailable);
                        activeField.SetValue(pool, originalActive);
                        releaseMapField.SetValue(pool, originalReleaseMap);
                        spritePoolField.SetValue(pool, originalSpritePool);
                        cachedPrefabField.SetValue(pool, originalCachedPrefab);
                    }
                }
                finally
                {
                    if (temporaryPoolObject != null)
                    {
                        if (Application.isPlaying)
                            UnityEngine.Object.Destroy(temporaryPoolObject);
                        else
                            UnityEngine.Object.DestroyImmediate(temporaryPoolObject);
                    }
                }
            }
        }

        private sealed class TemporaryIsolatedObjectPoolState : IDisposable
        {
            private readonly LF2ObjectPool pool;
            private readonly System.Reflection.FieldInfo availableField;
            private readonly System.Reflection.FieldInfo activeField;
            private readonly System.Reflection.FieldInfo releaseMapField;
            private readonly System.Reflection.FieldInfo spritePoolField;
            private readonly System.Reflection.FieldInfo cachedPrefabField;
            private readonly System.Reflection.MethodInfo createNewObjectMethod;
            private readonly object originalAvailable;
            private readonly object originalActive;
            private readonly object originalReleaseMap;
            private readonly object originalSpritePool;
            private readonly object originalCachedPrefab;

            public TemporaryIsolatedObjectPoolState(LF2ObjectPool pool)
            {
                this.pool = pool;
                Expect(pool != null,
                    "P4 pool-overflow opoint regression requires an LF2ObjectPool singleton");

                const System.Reflection.BindingFlags flags =
                    System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
                Type type = typeof(LF2ObjectPool);
                availableField = type.GetField("_availableObjects", flags);
                activeField = type.GetField("_activeObjects", flags);
                releaseMapField = type.GetField("_releaseTimeMap", flags);
                spritePoolField = type.GetField("_spritePool", flags);
                cachedPrefabField = type.GetField("_cachedLF2ObjectPrefab", flags);
                createNewObjectMethod = type.GetMethod("CreateNewObject", flags);
                Expect(availableField != null && activeField != null && releaseMapField != null &&
                       spritePoolField != null && cachedPrefabField != null && createNewObjectMethod != null,
                    "P4 pool-overflow opoint regression LF2ObjectPool private contract changed");

                originalAvailable = availableField.GetValue(pool);
                originalActive = activeField.GetValue(pool);
                originalReleaseMap = releaseMapField.GetValue(pool);
                originalSpritePool = spritePoolField.GetValue(pool);
                originalCachedPrefab = cachedPrefabField.GetValue(pool);

                availableField.SetValue(pool, new LinkedList<GameObject>());
                activeField.SetValue(pool, new HashSet<GameObject>());
                releaseMapField.SetValue(pool, new Dictionary<GameObject, float>());
                spritePoolField.SetValue(pool, new Stack<SpriteRenderer>());
                cachedPrefabField.SetValue(pool, null);
            }

            public IReadOnlyList<GameObject> AvailableObjects
            {
                get
                {
                    var objects = new List<GameObject>();
                    if (availableField.GetValue(pool) is LinkedList<GameObject> available)
                    {
                        foreach (GameObject item in available)
                            objects.Add(item);
                    }
                    return objects;
                }
            }

            public void Prewarm(int count)
            {
                for (int index = 0; index < count; index++)
                    createNewObjectMethod.Invoke(pool, null);

                Expect(AvailableObjects.Count == count,
                    $"P4 pool-overflow opoint regression failed to establish its {count}-object available prewarm");
            }

            public void Dispose()
            {
                var objects = new HashSet<GameObject>();
                try
                {
                    if (availableField.GetValue(pool) is LinkedList<GameObject> available)
                    {
                        foreach (GameObject item in available)
                            if (item != null) objects.Add(item);
                    }
                    if (activeField.GetValue(pool) is HashSet<GameObject> active)
                    {
                        foreach (GameObject item in active)
                            if (item != null) objects.Add(item);
                    }
                }
                finally
                {
                    availableField.SetValue(pool, originalAvailable);
                    activeField.SetValue(pool, originalActive);
                    releaseMapField.SetValue(pool, originalReleaseMap);
                    spritePoolField.SetValue(pool, originalSpritePool);
                    cachedPrefabField.SetValue(pool, originalCachedPrefab);
                }

                foreach (GameObject item in objects)
                    DestroySelfCheckObject(item);
            }
